INSERT INTO pyq_questions (id, topic, subject, exam, year, question, options, correct, explanation, tags, difficulty)
VALUES
  (1, 'Mahad Satyagraha (चवदार तळे)', 'History', 'MPSC Combined Group B & Police Bharti', 2022, 'डॉ. बाबासाहेब आंबेडकरांच्या नेतृत्वाखाली ऐतिहासिक ''महाड येथील चवदार तळ्याचा सत्याग्रह'' कोणत्या दिवशी पार पडला? (हा दिवस सामाजिक सबलीकरण दिन म्हणून साजरा केला जातो)', '{"A":"२० मार्च १९२७","B":"१४ एप्रिल १९२७","C":"२५ डिसेंबर १९२७","D":"२ मार्च १९३०"}'::JSONB, 'A', '२० मार्च १९२७ रोजी महाड येथील चवदार तळ्याचे पाणी अस्पृश्यांसाठी खुले करण्यासाठी सत्याग्रह झाला. याच महाडमध्ये २५ डिसेंबर १९२७ रोजी मनुस्मृतीचे दहन करण्यात आले आणि २ मार्च १९३० रोजी काळाराम मंदिर सत्याग्रह झाला.', ARRAY['mahad satyagraha', 'चवदार तळे', 'आंबेडकर', 'इतिहास', 'mpsc history']::TEXT[], ''),
  (2, 'सत्यशोधक समाज व महात्मा फुले', 'History', 'MPSC Rajyaseva & Combined', 2021, 'महात्मा ज्योतिराव फुले यांनी २४ सप्टेंबर १८७३ रोजी पुण्यात सत्यशोधक समाजाची स्थापना केली. या समाजाचे अधिकृत मुखपत्र खालीलपैकी कोणते होते?', '{"A":"दीनबंधू (कृष्णराव भालेकर)","B":"मूकनायक","C":"केसरी","D":"ज्ञानोदय"}'::JSONB, 'A', 'सत्यशोधक समाजाचे विचार बहुजन समाजापर्यंत पोहोचवण्यासाठी कृष्णराव भालेकर यांनी १ जानेवारी १८७७ रोजी ''दीनबंधू'' हे साप्ताहिक सुरू केले. मूकनायक डॉ. आंबेडकरांचे होते, केसरी लोकमान्य टिळकांचे होते.', ARRAY['सत्यशोधक समाज', 'महात्मा फुले', 'दीनबंधू', 'इतिहास', 'mpsc']::TEXT[], ''),
  (3, '१८५७ चा उठाव व महाराष्ट्र', 'History', 'MPSC Combined Group B', 2023, '१८५७ च्या उठावादरम्यान कोल्हापुरात छत्रपतींच्या घराण्यातील कोणाच्या नेतृत्वाखाली ब्रिटिश सत्तेविरुद्ध उठाव झाला होता?', '{"A":"चीमासाहेब","B":"रंगो बापूजी गुप्ते","C":"बाबासाहेब भावे","D":"भागोजी नाईक"}'::JSONB, 'A', 'कोल्हापुरात १८५७ च्या क्रांतीचे नेतृत्व चीमासाहेब (शहाजी छत्रपतींचे धाकटे बंधू) यांनी केले. रंगो बापूजी गुप्ते यांनी साताऱ्यात उठावाचे नियोजन केले, तर बाबासाहेब भावे यांनी नरगुंद येथे उठाव केला.', ARRAY['1857 revolt', 'चीमासाहेब', 'कोल्हापूर उठाव', 'इतिहास', 'mpsc']::TEXT[], ''),
  (4, 'गोदावरी नदी प्रणाली (Godavari River Basin)', 'Geography', 'MPSC Combined & Police Bharti', 2023, 'गोदावरी नदीचा उगम नाशिक जिल्ह्यातील त्र्यंबकेश्वरजवळील ब्रह्मगिरी पर्वतात होतो. महाराष्ट्रात गोदावरी नदी खोऱ्याने राज्याचे एकूण किती टक्के भौगोलिक क्षेत्र व्यापले आहे?', '{"A":"४९.७%","B":"३५.२%","C":"२१.४%","D":"६०.५%"}'::JSONB, 'A', 'गोदावरी हे महाराष्ट्रातील सर्वात मोठे नदीखोरे असून ते राज्याचे सुमारे ४९.७% (जवळपास अर्धे) क्षेत्र व्यापते. गोदावरीची महाराष्ट्रातील एकूण लांबी ६६८ किमी आहे.', ARRAY['rivers', 'godavari', 'गोदावरी नदी', 'भूगोल', 'mpsc geography']::TEXT[], ''),
  (5, 'महाराष्ट्रातील सर्वोच्च शिखर — कळसूबाई', 'Geography', 'Maharashtra Police Bharti & Talathi', 2023, 'सह्याद्री पर्वतातील ''कळसूबाई'' हे महाराष्ट्रातील सर्वोच्च शिखर कोणत्या दोन जिल्ह्यांच्या सीमेवर (अहिल्यानगर/नाशिक) स्थित असून त्याची उंची किती मीटर आहे?', '{"A":"१६४६ मीटर","B":"१५६७ मीटर","C":"१४३८ मीटर","D":"१२४० मीटर"}'::JSONB, 'A', 'कळसूबाई शिखराची उंची १६४६ मीटर (५४०० फूट) आहे. हे अकोले तालुका (अहिल्यानगर) व इगतपुरी तालुका (नाशिक) यांच्या सीमेवर वसलेले आहे.', ARRAY['kalsubai', 'कळसूबाई', 'सह्याद्री शिखर', 'भूगोल', 'police bharti']::TEXT[], ''),
  (6, 'महाराष्ट्रातील जलविद्युत प्रकल्प — कोयना', 'Geography', 'MPSC Combined & Talathi', 2022, 'सातारा जिल्ह्यातील कोयना नदीवर बांधण्यात आलेल्या शिवसागर जलाशयाला ''महाराष्ट्राची भाग्यलक्ष्मी'' का म्हटले जाते?', '{"A":"सर्वात मोठा जलविद्युत निर्मिती प्रकल्प (Hydroelectric Power)","B":"सर्वात मोठे सोने उत्पादन केंद्र","C":"पहिला अणुऊर्जा प्रकल्प","D":"सर्वात मोठी तेल शुद्धीकरण कंपनी"}'::JSONB, 'A', 'कोयना जलविद्युत प्रकल्प हा महाराष्ट्रातील सर्वात मोठा जलविद्युत प्रकल्प (१९६० मेगावॅट) असून राज्याच्या औद्योगिक व आर्थिक विकासाचा कणा असल्याने त्याला ''महाराष्ट्राची भाग्यलक्ष्मी'' म्हणतात.', ARRAY['koyna dam', 'कोयना धरण', 'शिवसागर', 'जलविद्युत', 'भूगोल']::TEXT[], ''),
  (7, 'महाराष्ट्राचे पठार व काळी रेगूर मृदा', 'Geography', 'MPSC Combined & Rajyaseva', 2021, 'महाराष्ट्र पठाराची निर्मिती प्रामुख्याने कोणत्या खडकाच्या ज्वालामुखी उद्रेकामुळे (Fissure Eruption) झाली आहे आणि त्यापासून कोणती काळी सुपीक मृदा तयार झाली?', '{"A":"बेसाल्ट खडक — रेगूर (कापसाची काळी मृदा)","B":"ग्रॅनाईट खडक — जांभी मृदा","C":"गाळाचा खडक — तांबडी मृदा","D":"संगमरवर — पिवळसर मृदा"}'::JSONB, 'A', 'दख्खनचे पठार २९ वेळा झालेल्या लाव्हाच्या भेगीय उद्रेकामुळे (Basalt) बनले आहे. या बेसाल्ट खडकाच्या विदारणातून ओलावा टिकवून ठेवणारी ''रेगूर'' (Black Cotton Soil) तयार होते.', ARRAY['basalt', 'regur soil', 'काळी मृदा', 'महाराष्ट्र पठार', 'भूगोल']::TEXT[], ''),
  (8, '७३ वी घटनादुरुस्ती कायदा १९९२ (Panchayati Raj)', 'Polity', 'MPSC Combined & ZP Bharti', 2023, '७३ व्या घटनादुरुस्ती कायद्यान्वये भारतीय राज्यघटनेत कोणती अनुसूची (Schedule) जोडली गेली आणि त्यात पंचायतींसाठी किती विषयांची तरतूद करण्यात आली?', '{"A":"११ वी अनुसूची — २९ विषय","B":"१२ वी अनुसूची — १८ विषय","C":"९ वी अनुसूची — २५ विषय","D":"१० वी अनुसूची — २२ विषय"}'::JSONB, 'A', '७३ व्या घटनादुरुस्तीने संविधानात भाग ९ व ११ वी अनुसूची जोडली, ज्यामध्ये पंचायतींना २९ कार्यात्मक विषय सोपवण्यात आले. १२ वी अनुसूची ७४ व्या दुरुस्तीने (नगरपालिका, १८ विषय) जोडली गेली.', ARRAY['73rd amendment', 'panchayati raj', 'पंचायत राज', '११ वी अनुसूची', 'polity']::TEXT[], ''),
  (9, 'ग्रामपंचायत व सरपंच (Gram Panchayat Administration)', 'Polity', 'Maharashtra Police Bharti & ZP', 2023, 'महाराष्ट्रात ग्रामपंचायतीमध्ये महिलांसाठी किती टक्के आरक्षण लागू आहे?', '{"A":"५०%","B":"३३%","C":"२५%","D":"४०%"}'::JSONB, 'A', 'महाराष्ट्रात स्थानिक स्वराज्य संस्थांमध्ये (ग्रामपंचायत, पंचायत समिती, जिल्हा परिषद, नगरपालिका व मनपा) महिलांसाठी ५०% आरक्षण लागू आहे.', ARRAY['gram panchayat', 'महिला आरक्षण ५०%', 'सरपंच', 'polity', 'police bharti']::TEXT[], ''),
  (10, 'राज्यपाल व स्वेच्छाधीन अधिकार (Governor - Article 163)', 'Polity', 'MPSC Combined Group B', 2023, 'भारतीय संविधानाच्या कोणत्या कलमान्वये राज्याच्या राज्यपालांना ''स्वेच्छाधीन अधिकार'' (Discretionary Powers) प्रदान करण्यात आले आहेत?', '{"A":"कलम १५३","B":"कलम १६३","C":"कलम १७४","D":"कलम २१३"}'::JSONB, 'A', 'कलम १६३(१) नुसार राज्यपालांना सल्ला देण्यासाठी मंत्रिमंडळ असते, परंतु ज्या बाबींमध्ये राज्यपालांना स्वविवेकानुसार निर्णय घेण्याचा अधिकार दिला आहे, तेथे मंत्रिमंडळाचा सल्ला बंधनकारक नसतो.', ARRAY['governor', 'article 163', 'राज्यपाल', 'polity', 'mpsc']::TEXT[], ''),
  (11, 'मूलभूत हक्क व घटनात्मक उपाययोजना (Article 32)', 'Polity', 'MPSC Rajyaseva Prelims', 2021, 'डॉ. बाबासाहेब आंबेडकरांनी भारतीय राज्यघटनेच्या कोणत्या कलमास ''घटनेचा आत्मा आणि हृदय'' (Heart and Soul of the Constitution) असे संबोधले आहे?', '{"A":"कलम १४","B":"कलम १९","C":"कलम २१","D":"कलम ३२ (घटनात्मक उपाययोजनांचा अधिकार)"}'::JSONB, 'D', 'कलम ३२ अन्वये सर्वोच्च न्यायालयाला मूलभूत हक्कांचे संरक्षण करण्यासाठी ५ प्रकारचे प्राधिकृत आदेश (Writs - बंदीप्रत्यक्षीकरण, परमादेश, प्रतिषेध, उत्प्रेषण, अधिकारपृच्छा) काढण्याचा अधिकार आहे.', ARRAY['article 32', 'writs', 'कलम ३२', 'मूलभूत हक्क', 'mpsc', 'polity']::TEXT[], ''),
  (12, 'मूलभूत कर्तव्ये (Fundamental Duties - Article 51A)', 'Polity', 'SSC CGL & MPSC', 2022, '४२ व्या घटनादुरुस्ती कायदा १९७६ द्वारे संविधानात स्वर्णसिंग समितीच्या शिफारशीवरून कोणत्या भागात मूलभूत कर्तव्ये समाविष्ट करण्यात आली?', '{"A":"भाग IV-A (कलम ५१-ए)","B":"भाग III-A (कलम ३५-ए)","C":"भाग V (कलम ५२)","D":"भाग IX-A (कलम २४३)"}'::JSONB, 'A', '४२ व्या घटनादुरुस्तीने १० मूलभूत कर्तव्ये समाविष्ट केली, तर ८६ व्या घटनादुरुस्ती २००२ द्वारे ६ ते १४ वयोगटातील पाल्यांना शिक्षणाची संधी उपलब्ध करून देण्याचे ११ वे कर्तव्य जोडले गेले.', ARRAY['fundamental duties', 'article 51a', 'मूलभूत कर्तव्ये', 'स्वर्णसिंग समिती', 'polity']::TEXT[], ''),
  (13, 'रेपो रेट व मौद्रिक धोरण (Repo Rate & Monetary Policy)', 'Economy', 'MPSC Combined & Banking', 2023, 'भारतीय रिझर्व्ह बँकेने (RBI) ''रेपो रेट'' (Repo Rate) वाढवल्यास अर्थव्यवस्थेवर त्याचा काय परिणाम होतो?', '{"A":"बँकांचे कर्ज महाग होते व बाजारातील चलनवाढ (महागाई) कमी होण्यास मदत होते","B":"कर्ज स्वस्त होते आणि बाजारात पैशांची तरलता वाढते","C":"बँकांचे ठेवींवरील व्याजदर अचानक शून्यावर येतात","D":"देशाची निर्यात दुपटीने वाढते"}'::JSONB, 'A', 'रेपो रेट म्हणजे ज्या दराने RBI व्यावसायिक बँकांना अल्पमुदतीचे कर्ज देते. रेपो रेट वाढल्यास बँकांसाठी निधी महाग होतो, त्यामुळे कर्जावरील व्याजदर वाढतात, बाजारातील मागणी कमी होते आणि महागाई आटोक्यात येते.', ARRAY['repo rate', 'rbi', 'रेपो रेट', 'महागाई', 'monetary policy', 'economy']::TEXT[], ''),
  (14, 'वस्तू व सेवा कर (GST - 101st Amendment)', 'Economy', 'Talathi & MPSC', 2022, 'भारतात ''एक देश, एक कर'' संकल्पनेवर आधारित GST (वस्तू व सेवा कर) ची अंमलबजावणी कोणत्या तारखेपासून सुरू झाली?', '{"A":"१ जुलै २०१७","B":"१ एप्रिल २०१६","C":"८ नोव्हेंबर २०१६","D":"१ जानेवारी २०१८"}'::JSONB, 'A', '१०१ व्या घटनादुरुस्ती कायद्यानुसार १ जुलै २०१७ रोजी भारतात वस्तू व सेवा कर (GST) लागू करण्यात आला. जीएसटी कौन्सिलचे अध्यक्ष केंद्रीय अर्थमंत्री असतात (कलम २७९-A).', ARRAY['gst', 'वस्तू व सेवा कर', '101st amendment', 'economy', 'talathi']::TEXT[], ''),
  (15, 'नीती आयोग (NITI Aayog)', 'Economy', 'MPSC Rajyaseva & SSC CGL', 2021, '१ जानेवारी २०१५ रोजी नियोजन आयोगाच्या जागी स्थापन झालेल्या ''नीती आयोगाचे'' (NITI Aayog) पदसिद्ध अध्यक्ष कोण असतात?', '{"A":"भारताचे पंतप्रधान","B":"केंद्रीय अर्थमंत्री","C":"रिझर्व्ह बँकेचे गव्हर्नर","D":"राष्ट्रपती"}'::JSONB, 'A', 'नीती आयोगाचे (National Institution for Transforming India) पदसिद्ध अध्यक्ष पंतप्रधान असतात. यात सहकारी संघराज्यवादाला (Cooperative Federalism) प्रोत्साहन देण्यासाठी सर्व राज्यांचे मुख्यमंत्री सहभागी असतात.', ARRAY['niti aayog', 'नीती आयोग', 'पंतप्रधान', 'economy', 'mpsc']::TEXT[], ''),
  (16, 'राजकोषीय तूट (Fiscal Deficit)', 'Economy', 'MPSC Combined & RBI Grade B', 2020, '''राजकोषीय तूट'' (Fiscal Deficit) म्हणजे खालीलपैकी काय?', '{"A":"एकूण खर्च वजा (एकूण महसूल + बिगर कर्ज भांडवली प्राप्ती)","B":"केवळ महसुली खर्च वजा महसुली प्राप्ती","C":"एकूण निर्यात वजा एकूण आयात","D":"केवळ कर्जावरील व्याजाचा खर्च"}'::JSONB, 'A', 'राजकोषीय तूट म्हणजे सरकारचा एकूण खर्च आणि कर्जाव्यतिरिक्त असणारे एकूण उत्पन्न यातील फरक. हे शासनाला त्या वर्षात घ्याव्या लागणाऱ्या एकूण कर्जाचे (Borrowings) मोजमाप असते.', ARRAY['fiscal deficit', 'राजकोषीय तूट', 'अर्थसंकल्प', 'economy']::TEXT[], ''),
  (17, 'रक्तगट व रुधिरसंक्रमण (Blood Groups & Rh Factor)', 'Science', 'Police Bharti & MPSC Combined', 2023, 'मानवी रक्तगटांचा शोध कार्ल लँडस्टायनर यांनी १९०० मध्ये लावला. यातील ''सर्वयोग्य ग्राहक'' (Universal Recipient) रक्तगट कोणता?', '{"A":"AB+ (एबी पॉझिटिव्ह)","B":"O- (ओ निगेटिव्ह)","C":"A+","D":"B-"}'::JSONB, 'A', 'AB+ रक्तगटात A आणि B दोन्ही प्रतिजन (Antigens) असतात आणि रक्तातील द्रवात कोणतेही प्रतिपिंड (Antibodies) नसतात, त्यामुळे तो कोणाचेही रक्त स्वीकारू शकतो. O- हा ''सर्वयोग्य दाता'' (Universal Donor) आहे.', ARRAY['blood groups', 'रक्तगट', 'ab positive', 'science', 'police bharti']::TEXT[], ''),
  (18, 'जीवनसत्त्वे व अभावजन्य आजार (Vitamins & Deficiency)', 'Science', 'Maharashtra Talathi & ZP Arogya Sevak', 2023, 'दातांच्या हिरड्यांमधून रक्त येणे आणि जखम भरून न येणे ही लक्षणे कोणत्या जीवनसत्त्वाच्या अभावामुळे (Scorbutic) उद्भवतात?', '{"A":"जीवनसत्त्व C (क जीवनसत्त्व - Ascorbic Acid)","B":"जीवनसत्त्व A (रेटिनॉल)","C":"जीवनसत्त्व D (कॅल्सिफेरॉल)","D":"जीवनसत्त्व K (फायलोक्यूनॉन)"}'::JSONB, 'A', 'क जीवनसत्त्वाच्या (Ascorbic Acid) अभावामुळे ''स्कर्व्ही'' (Scurvy) हा आजार होतो. आवळा, लिंबू, संत्री यांसारख्या आंबट फळांमध्ये ''क'' जीवनसत्त्व मुबलक असते.', ARRAY['vitamins', 'scurvy', 'जीवनसत्त्व क', 'science', 'talathi']::TEXT[], ''),
  (19, 'मराठी व्याकरण — समास (Marathi Samas)', 'Marathi', 'MPSC Combined Paper 1 & Talathi', 2024, '''पंचवटी'' या सामासिक शब्दाचा समास ओळखा:', '{"A":"द्विगु समास","B":"द्वंद्व समास","C":"अव्ययीभाव समास","D":"बहुव्रीही समास"}'::JSONB, 'A', 'पंचवटी म्हणजे ''पाच वडांचा समूह''. ज्या कर्मधारय समासातील पहिले पद संख्याविशेषण असते व सामासिक शब्दावरून एका समूहाचा बोध होतो, त्यास ''द्विगु समास'' म्हणतात. (उदा. नवरात्र, त्रिफळा, त्रिभुवन).', ARRAY['समास', 'द्विगु समास', 'मराठी व्याकरण', 'samas', 'marathi vyakaran', 'mpsc paper 1']::TEXT[], ''),
  (20, 'मराठी व्याकरण — प्रयोग (Marathi Prayog)', 'Marathi', 'MPSC Combined & Police Bharti', 2023, '''शिपायाकडून चोर पकडला गेला'' या वाक्यातील प्रयोग कोणता आहे?', '{"A":"नवीन कर्मणी (कर्मकर्तरी प्रयोग)","B":"कर्तरी प्रयोग","C":"भावे प्रयोग","D":"सकर्मक कर्तरी प्रयोग"}'::JSONB, 'A', 'इंग्रजीतील Passive Voice च्या प्रभावामुळे मराठीत कर्त्याला ''कडून'' प्रत्यय लावून आणि क्रियापदाचे ''संयुक्त रूप'' वापरून नवीन कर्मणी (कर्मकर्तरी) प्रयोग केला जातो. उदा. ''न्यायाधीशाकडून दंड ठोठावला गेला''.', ARRAY['प्रयोग', 'नवीन कर्मणी', 'कर्मकर्तरी', 'prayog', 'मराठी', 'police bharti']::TEXT[], ''),
  (21, 'समानार्थी शब्द (Synonyms in Marathi)', 'Marathi', 'MPSC Group C & Talathi', 2022, '''सुधा'' या शब्दाचा योग्य समानार्थी शब्द खालीलपैकी कोणता आहे?', '{"A":"अमृत","B":"विष","C":"पाणी","D":"अनल"}'::JSONB, 'A', '''सुधा'' म्हणजे अमृत, पीयूष, जीवन. पाणी = जल, नीर, तोय, पय, उदक. अनल = अग्नी, पावक, विस्तव, वन्ही.', ARRAY['समानार्थी शब्द', 'सुधा', 'अमृत', 'synonyms', 'marathi shabd', 'talathi']::TEXT[], ''),
  (22, 'विरुद्धार्थी शब्द (Antonyms in Marathi)', 'Marathi', 'MPSC Combined & Zilla Parishad', 2023, '''कृपण'' या शब्दाचा विरुद्धार्थी शब्द ओळखा:', '{"A":"उदार (दानशूर)","B":"कंजूष","C":"लोभी","D":"चिकू"}'::JSONB, 'A', '''कृपण'' म्हणजे कंजूष, हातचा मळ न सोडणारा. याचा थेट विरुद्धार्थी शब्द ''उदार'' किंवा ''दानशूर'' हा होतो.', ARRAY['विरुद्धार्थी शब्द', 'कृपण', 'उदार', 'antonyms', 'marathi', 'mpsc']::TEXT[], ''),
  (23, 'म्हणी व वाक्प्रचार (Marathi Idioms & Proverbs)', 'Marathi', 'Maharashtra Police Bharti & MPSC', 2023, '''काखेत कळसा आणि गावाला वळसा'' या म्हणीचा अचूक अर्थ काय?', '{"A":"आपल्याजवळच असलेली वस्तू इतरत्र सर्वत्र शोधणे","B":"कामात सतत अडथळे येणे","C":"अतिशय दूरचा प्रवास करणे","D":"दुसऱ्याचे ऐकून निर्णय घेणे"}'::JSONB, 'A', '''काखेत कळसा गावाला वळसा'' म्हणजे एखादी हवी असलेली वस्तू अगदी जवळ असताना, तिचा विचार न करता सर्वत्र शोध घेत फिरणे.', ARRAY['म्हणी व वाक्प्रचार', 'म्हणी', 'काखेत कळसा', 'proverbs', 'marathi idiom', 'police']::TEXT[], ''),
  (24, 'वाक्यरचना व प्रकार (Sentence Types)', 'Marathi', 'MPSC Combined Group B', 2021, '''जे चकाकते ते सर्व सोने नसते'' हे वाक्य कोणत्या प्रकारचे आहे?', '{"A":"मिश्र वाक्य","B":"केवल वाक्य","C":"संयुक्त वाक्य","D":"नकारार्थी केवल वाक्य"}'::JSONB, 'A', 'या वाक्यात एक मुख्य वाक्य (ते सर्व सोने नसते) आणि एक त्यावर अवलंबून असलेले गौण वाक्य (जे चकाकते) संबंधी सर्वनामांनी (जे-ते) जोडले आहे. म्हणून हे ''मिश्र वाक्य'' आहे.', ARRAY['वाक्यरचना', 'मिश्र वाक्य', 'वाक्य प्रकार', 'sentence structure', 'marathi', 'mpsc']::TEXT[], ''),
  (25, 'वाक्यप्रचार व म्हणी (Marathi Idioms & Proverbs)', 'Marathi', 'Maharashtra Talathi (TCS)', 2023, '''उंटावरून शेळ्या हाकणे'' या म्हणीचा अचूक अर्थ खालीलपैकी कोणता?', '{"A":"प्रत्यक्ष कामात कष्ट न करता केवळ दुरून पोकळ सूचना देणे","B":"फार मोठे साहस करून दाखवणे","C":"शेतकऱ्यांचे नुकसान करणे","D":"अत्यंत कठीण प्रसंगातून सहीसलामत सुटणे"}'::JSONB, 'A', '''उंटावरून शेळ्या हाकणे'' म्हणजे स्वतः कामात प्रत्यक्ष सहभागी न होता आळशीपणाने केवळ वरवरच्या किंवा दुरून आज्ञा देणे.', ARRAY['म्हणी', 'उंटावरून शेळ्या हाकणे', 'मराठी व्याकरण', 'tcs talathi']::TEXT[], ''),
  (26, 'उतारा आकलन व शब्दसिद्धी (Marathi Shabdasiddhi)', 'Marathi', 'MPSC Combined Group B & Police Bharti', 2023, 'संस्कृतमधून मराठीत येताना ज्या शब्दांच्या मूळ रूपात बदल होत नाही, अशा शब्दांना काय म्हणतात?', '{"A":"तत्सम शब्द","B":"तद्भव शब्द","C":"देशी शब्द","D":"परभाषीय शब्द"}'::JSONB, 'A', 'संस्कृत भाषेतील जे शब्द जसेच्या तसे बदल न होता मराठीत वापरले जातात त्यांना ''तत्सम शब्द'' म्हणतात. (उदा. राजा, भूगोल, कन्या, पुत्र, वृक्ष, सूर्य). बदल होऊन आलेल्यांना ''तद्भव'' म्हणतात (उदा. कान, हात, सासू).', ARRAY['शब्दसिद्धी', 'तत्सम तद्भव', 'मराठी व्याकरण', 'shabdasiddhi', 'marathi', 'mpsc']::TEXT[], ''),
  (27, 'Subject-Verb Agreement', 'English', 'TCS Talathi & SSC CGL', 2023, 'Choose the grammatically correct sentence: ''Neither the manager nor the employees _______ present at the conference yesterday.''', '{"A":"were","B":"was","C":"is","D":"are"}'::JSONB, 'A', 'When subjects are joined by ''neither... nor'', the verb agrees with the subject closest to it. Since ''employees'' is plural and the event took place ''yesterday'' (past tense), the plural past verb ''were'' is correct.', ARRAY['subject verb agreement', 'neither nor', 'english grammar', 'tcs']::TEXT[], ''),
  (28, 'Direct and Indirect Speech', 'English', 'MPSC Combined & SSC CGL', 2022, 'Convert to Indirect Speech: The teacher said to the students, ''Honesty is the best policy.''', '{"A":"The teacher told the students that honesty is the best policy.","B":"The teacher told the students that honesty was the best policy.","C":"The teacher asked the students if honesty is the best policy.","D":"The teacher instructed that honesty had been the best policy."}'::JSONB, 'A', 'Universal truths, scientific facts, and proverbs do NOT change their tense in Indirect Speech. Hence, ''honesty is the best policy'' remains in the simple present tense.', ARRAY['indirect speech', 'narration', 'universal truth', 'english']::TEXT[], ''),
  (29, 'Coding-Decoding & Alphabet Series', 'Reasoning', 'TCS Talathi & Police Bharti', 2023, 'एका विशिष्ट सांकेतिक भाषेत ''MPSC'' हा शब्द ''NQTD'' असा लिहिला जातो, तर त्याच भाषेत ''POLICE'' हा शब्द कसा लिहिला जाईल?', '{"A":"QPMJDF","B":"QPNJDF","C":"ROMJDE","D":"QQMKDF"}'::JSONB, 'A', 'येथे प्रत्येक अक्षरात +१ ची वाढ होत आहे: M+1=N, P+1=Q, S+1=T, C+1=D. त्यानुसार: P+1=Q, O+1=P, L+1=M, I+1=J, C+1=D, E+1=F म्हणजेच ''QPMJDF''.', ARRAY['coding decoding', 'अक्षर मालिका', 'reasoning', 'police bharti']::TEXT[], ''),
  (30, 'काम व काळ (Time and Work)', 'Reasoning', 'Maharashtra Police & Talathi', 2023, '''अ'' एक काम १२ दिवसांत पूर्ण करतो आणि ''ब'' तेच काम २४ दिवसांत पूर्ण करतो. जर दोघांनी मिळून एकत्र काम केले, तर ते काम किती दिवसांत संपेल?', '{"A":"८ दिवस","B":"१० दिवस","C":"१४ दिवस","D":"१६ दिवस"}'::JSONB, 'A', 'अ चे एका दिवसाचे काम = १/१२; ब चे एका दिवसाचे काम = १/२४. दोघांचे एकत्र काम = (१/१२) + (१/२४) = (२+१)/२४ = ३/२४ = १/८. म्हणून एकत्र काम ८ दिवसांत पूर्ण होईल.', ARRAY['time and work', 'काम आणि काळ', 'अंकगणित', 'talathi', 'police bharti']::TEXT[], ''),
  (31, 'रक्तसंबंध (Blood Relations)', 'Reasoning', 'MPSC CSAT & Group B', 2022, 'एका छायाचित्राकडे बोट दाखवून सुरेश म्हणाला, ''ही स्त्री माझ्या आईच्या एकुलत्या एका मुलाची मुलगी आहे.'' तर त्या छायाचित्रातील मुलीचे सुरेशशी काय नाते आहे?', '{"A":"मुलगी (Daughter)","B":"बहीण (Sister)","C":"भाची (Niece)","D":"पत्नी (Wife)"}'::JSONB, 'A', 'सुरेशच्या ''आईचा एकुलता एक मुलगा'' म्हणजे स्वतः सुरेश. आणि त्याची मुलगी म्हणजेच ती सुरेशची प्रत्यक्ष मुलगी आहे.', ARRAY['blood relations', 'रक्तसंबंध', 'reasoning', 'csat']::TEXT[], ''),
  (32, 'Right to Information (माहितीचा अधिकार अधिनियम २००५)', 'Polity', 'MPSC Combined Group B & Talathi', 2023, 'माहितीचा अधिकार अधिनियम २००५ (RTI Act 2005) च्या कलम ७(१) नुसार, जर मागितलेली माहिती एखाद्या व्यक्तीच्या ''जीविताशी किंवा स्वातंत्र्याशी'' संबंधित असेल, तर ती अर्ज मिळाल्यापासून किती तासांच्या आत दिली पाहिजे?', '{"A":"२४ तास","B":"४८ तास","C":"७ दिवस","D":"३० दिवस"}'::JSONB, 'B', 'RTI Act कलम ७(१) नुसार सामान्यतः माहिती ३० दिवसांत देणे बंधनकारक असते, परंतु जर मागितलेली माहिती व्यक्तीच्या जीविताशी किंवा स्वातंत्र्याशी संबंधित असेल, तर ती अर्ज प्राप्त झाल्यापासून ४८ तासांच्या आत देणे अनिवार्य आहे.', ARRAY['rti act 2005', 'right to information', 'माहितीचा अधिकार', 'कलम ७', 'mpsc polity', 'group b']::TEXT[], ''),
  (33, 'RTI Act 2005 — दंडाची तरतूद (Penalty Provisions)', 'Polity', 'MPSC Combined & Rajyaseva', 2022, 'माहिती अधिकार कायदा २००५ च्या कलम २० नुसार, जनमाहिती अधिकाऱ्याने विनाकारण माहिती देण्यास नकार दिल्यास प्रतिदिन किती रुपये दंड आकारला जाऊ शकतो आणि कमाल मर्यादा किती आहे?', '{"A":"₹२५० प्रतिदिन (कमाल ₹२५,०००)","B":"₹१०० प्रतिदिन (कमाल ₹१०,०००)","C":"₹५०० प्रतिदिन (कमाल ₹५०,०००)","D":"₹५० प्रतिदिन (कमाल ₹५,०००)"}'::JSONB, 'A', 'कलम २० नुसार माहिती आयुक्त कसूरदार जनमाहिती अधिकाऱ्याला माहिती देईपर्यंत प्रतिदिन ₹२५० चा दंड आकारू शकतात, परंतु असा एकूण दंड ₹२५,००० पेक्षा जास्त असणार नाही.', ARRAY['rti act 2005', 'कलम २० दंड', 'right to information', 'माहितीचा अधिकार', 'polity']::TEXT[], ''),
  (34, 'महाराष्ट्र लोकसेवा हक्क अधिनियम २०१५ (Maharashtra Public Services Act 2015)', 'Polity', 'MPSC Combined Group B & C', 2022, 'महाराष्ट्र लोकसेवा हक्क अधिनियम २०१५ (सेवा हमी कायदा) अंतर्गत जर पदनिर्देशित अधिकाऱ्याने विहित वेळेत सेवा दिली नाही, तर प्रथम अपील अधिकाऱ्याकडे किती दिवसांत अपील करता येते?', '{"A":"१५ दिवस","B":"३० दिवस","C":"४५ दिवस","D":"६० दिवस"}'::JSONB, 'B', 'महाराष्ट्र लोकसेवा हक्क अधिनियम २०१५ च्या कलम १८ नुसार, सेवा नाकारल्याच्या किंवा मुदत संपल्याच्या दिनांकापासून ३० दिवसांच्या आत प्रथम अपील अधिकाऱ्याकडे अपील करता येते. समाधान न झाल्यास पुढील ३० दिवसांत द्वितीय अपील करता येते.', ARRAY['maharashtra public services act 2015', 'लोकसेवा हक्क कायदा', 'सेवा हमी कायदा', 'mpsc combined', 'group c']::TEXT[], ''),
  (35, 'Maharashtra Public Services Act 2015 — दंड व तरतूद', 'Polity', 'MPSC Combined Group C', 2023, 'महाराष्ट्र लोकसेवा हक्क अधिनियमान्वये, द्वितीय अपील अधिकाऱ्याने पदनिर्देशित अधिकाऱ्याने वाजवी कारणाशिवाय विहित मुदतीत सेवा पुरवण्यात कसूर केल्याचे आढळल्यास, त्या अधिकाऱ्यावर किती रुपयांपर्यंतचा दंड ठोठावला जाऊ शकतो?', '{"A":"₹५०० ते ₹५,०००","B":"₹१,००० ते ₹१०,०००","C":"₹२५० ते ₹२,५००","D":"₹२०० ते ₹१,०००"}'::JSONB, 'A', 'महाराष्ट्र लोकसेवा हक्क कायदा २०१५ च्या कलम १९ नुसार, सेवा देण्यास विलंब किंवा कसूर केल्यास किमान ₹५०० ते कमाल ₹५,००० पर्यंतचा दंड ठोठावण्याची तरतूद आहे.', ARRAY['maharashtra public services act 2015', 'सेवा हमी कायदा', 'दंड', 'mpsc', 'group c']::TEXT[], ''),
  (36, 'Computer & IT Basics (संगणक व माहिती तंत्रज्ञान)', 'Science', 'MPSC Combined Group B & C', 2023, 'इंटरनेटवर वापरकर्त्यांची गोपनीय माहिती (जसे की युझरनेम, पासवर्ड, क्रेडिट कार्ड तपशील) बनावट ईमेल किंवा वेबसाइट्सचा वापर करून चोरण्याच्या सायबर गुन्ह्यास काय म्हणतात?', '{"A":"फिशिंग (Phishing)","B":"स्पॅमिंग (Spamming)","C":"बूटिंग (Booting)","D":"डीफ्रॅगमेंटेशन (Defragmentation)"}'::JSONB, 'A', 'फिशिंग (Phishing) हा एक सायबर गुन्हा आहे ज्यामध्ये विश्वासू संस्थेचे सोंग घेऊन फसव्या ईमेल किंवा संदेशांद्वारे संवेदनशील माहिती चोरली जाते. स्पॅमिंग म्हणजे अवांछित बल्क मेसेज पाठवणे.', ARRAY['computer it basics', 'phishing', 'सायबर सुरक्षा', 'संगणक ज्ञान', 'mpsc', 'information technology']::TEXT[], ''),
  (37, 'Computer & IT Basics — मेमरी व हार्डवेअर', 'Science', 'MPSC Combined & Talathi', 2022, 'संगणकातील कोणती मेमरी ही ''तात्पुरती'' (Volatile Memory) असते, जी संगणक बंद करताच त्यातील सर्व माहिती नष्ट होते?', '{"A":"RAM (Random Access Memory)","B":"ROM (Read Only Memory)","C":"हार्ड डिस्क (Hard Disk)","D":"SSD"}'::JSONB, 'A', 'RAM (Random Access Memory) ही तात्पुरती (Volatile) प्राथमिक मेमरी आहे, ज्यामध्ये चालू प्रक्रियेचा डेटा असतो. पॉवर कट झाल्यावर RAM मधील माहिती पुसली जाते. ROM ही कायमस्वरूपी (Non-volatile) असते.', ARRAY['computer it basics', 'ram rom', 'संगणक मेमरी', 'science', 'mpsc']::TEXT[], ''),
  (38, 'भारतीय न्याय संहिता (BNS) / IPC — सदोष मनुष्यवध व खून', 'Law', 'MPSC PSI Mains (Paper 2)', 2023, 'भारतीय दंड संहिता (IPC) मधील ''सदोष मनुष्यवध'' (Culpable Homicide) आणि ''खून'' (Murder) यांमधील फरक खालीलपैकी कोणत्या कलमांमध्ये स्पष्ट केला आहे, ज्यांची जागा भारतीय न्याय संहिता २०२३ (BNS) मध्ये अनुक्रमे कलम १०० व १०१ ने घेतली आहे?', '{"A":"IPC कलम २९९ आणि ३००","B":"IPC कलम ३०२ आणि ३०७","C":"IPC कलम ३२३ आणि ३२४","D":"IPC कलम ३७५ आणि ३७६"}'::JSONB, 'A', 'IPC कलम २९९ मध्ये सदोष मनुष्यवध (Culpable Homicide not amounting to murder) आणि कलम ३०० मध्ये खून (Murder) ची व्याख्या आहे. भारतीय न्याय संहिता (BNS) २०२३ नुसार हे अनुक्रमे कलम १०० व कलम १०१ मध्ये समाविष्ट केले गेले आहे.', ARRAY['bns', 'ipc', 'criminal law', 'culpable homicide', 'murder', 'mpsc psi', 'भारतीय न्याय संहिता', 'indian penal code']::TEXT[], ''),
  (39, 'CrPC / BNSS — विना वॉरंट अटक (Arrest Without Warrant)', 'Law', 'MPSC PSI Mains (Paper 2)', 2023, 'फौजदारी प्रक्रिया संहिता (CrPC) च्या कलम ४१ (नवीन भारतीय नागरिक सुरक्षा संहिता २०२३ चे कलम ३५) नुसार, पोलीस अधिकारी खालीलपैकी कोणत्या परिस्थितीत विना वॉरंट (Without Warrant) व्यक्तीला अटक करू शकतात?', '{"A":"दखलपात्र गुन्हा (Cognizable Offense) करणाऱ्या किंवा संशयित व्यक्तीला","B":"केवळ अदखलपात्र गुन्ह्याचा आरोप असल्यास","C":"कोणत्याही दिवाणी (Civil) वादाच्या तक्रारीवर","D":"ग्रामपंचायत सरपंचांच्या तोंडी सूचनेवरून"}'::JSONB, 'A', 'CrPC कलम ४१ (BNSS कलम ३५) अन्वये पोलीस अधिकाऱ्याला दखलपात्र गुन्ह्यातील (Cognizable Offence) आरोपीला विना वॉरंट अटक करण्याचा वैधानिक अधिकार आहे. अदखलपात्र गुन्ह्यांमध्ये दंडाधिकाऱ्यांच्या वॉरंटशिवाय अटक करता येत नाही.', ARRAY['crpc', 'bnss', 'arrest without warrant', 'bail', 'विना वॉरंट अटक', 'mpsc psi', 'जामीन', 'criminal procedure']::TEXT[], ''),
  (40, 'CrPC / BNSS — अटकपूर्व जामीन (Anticipatory Bail)', 'Law', 'MPSC PSI Mains (Paper 2)', 2022, 'फौजदारी प्रक्रिया संहितेच्या कलम ४३८ (नवीन BNSS चे कलम ४८२) मधील ''अटकपूर्व जामीन'' (Anticipatory Bail) मंजूर करण्याचे वैधानिक अधिकार कोणाला आहेत?', '{"A":"केवळ सत्र न्यायालय (Sessions Court) आणि उच्च न्यायालय (High Court)","B":"केवळ प्रथम वर्ग न्यायदंडाधिकारी (JMFC)","C":"पोलीस उपअधीक्षक (DySP)","D":"जिल्हा दंडाधिकारी (Collector)"}'::JSONB, 'A', 'कलम ४३८ (BNSS कलम ४८२) अन्वये अटकपूर्व जामीन केवळ सत्र न्यायालय (Sessions Court) किंवा उच्च न्यायालयाकडूनच मंजूर केला जाऊ शकतो; प्रथम वर्ग दंडाधिकाऱ्यांना (Magistrate) अटकपूर्व जामीन देण्याचा अधिकार नसतो.', ARRAY['anticipatory bail', 'अटकपूर्व जामीन', 'crpc 438', 'bnss', 'mpsc psi', 'bail procedures']::TEXT[], ''),
  (41, 'Indian Evidence Act / BSA — मरणोन्मुख जबाब (Dying Declaration)', 'Law', 'MPSC PSI Mains (Paper 2)', 2021, 'भारतीय पुरावा कायदा १८७२ च्या कलम ३२(१) (नवीन भारतीय साक्ष अधिनियम २०२३ चे कलम २६) मधील ''मरणोन्मुख जबाब'' (Dying Declaration) बाबत काय खरे आहे?', '{"A":"मरणोन्मुख जबाब हा व्यक्तीच्या मृत्यूचे कारण किंवा मृत्यू घडवून आणलेल्या परिस्थितीबाबत ग्राह्य असतो","B":"तो केवळ न्यायदंडाधिकाऱ्यांसमोरच नोंदवला पाहिजे, अन्यथा तो पूर्णपणे अवैध ठरतो","C":"मरणोन्मुख जबाब हा कोणत्याही फौजदारी खटल्यात पुरावा म्हणून स्वीकारता येत नाही","D":"तो केवळ लेखी स्वरूपातच असावा लागतो, तोंडी किंवा खाणाखुणा चालत नाहीत"}'::JSONB, 'A', 'कलम ३२(१) नुसार मृत्यूचे कारण किंवा मृत्यूच्या परिस्थितीबद्दल मृत व्यक्तीने दिलेले विधान (Dying Declaration) पुरावा म्हणून अत्यंत महत्त्वाचे मानले जाते. परिस्थितीनुसार सक्षम व्यक्ती, डॉक्टर किंवा पोलीसही जबाब नोंदवू शकतात आणि खाणाखुणांचा जबाबही वैध ठरतो.', ARRAY['evidence act', 'bsa', 'dying declaration', 'मरणोन्मुख जबाब', 'भारतीय साक्ष अधिनियम', 'indian evidence act', 'mpsc psi']::TEXT[], ''),
  (42, 'Indian Evidence Act / BSA — पुराव्याचा भार (Burden of Proof)', 'Law', 'MPSC PSI Mains (Paper 2)', 2022, 'भारतीय पुरावा कायदा १८७२ च्या कलम १०१ (BSA चे कलम १०४) नुसार फौजदारी खटल्यामध्ये गुन्हा सिद्ध करण्याचा भार (Burden of Proof) सामान्यतः कोणावर असतो?', '{"A":"फिर्यादी / अभियोग पक्ष (Prosecution) वर","B":"थेट आरोपीवर","C":"तपास अधिकारी (IO) वर वैयक्तिकरीत्या","D":"न्यायालयाच्या न्यायाधीशांवर"}'::JSONB, 'A', 'फौजदारी कायद्याचे मूलभूत सूत्र आहे: ''जो न्यायालयात तथ्याचा दावा करतो, त्यानेच तो सिद्ध केला पाहिजे'' (कलम १०१). अभियोग पक्षाने आरोपीचा गुन्हा संशयापलीकडे (Beyond reasonable doubt) सिद्ध करावा लागतो.', ARRAY['burden of proof', 'evidence act', 'bsa', 'कलम १०१', 'mpsc psi', 'indian evidence act', 'पुराव्याचा भार']::TEXT[], ''),
  (43, 'Maharashtra Police Act 1951 — तडीपारीची कारवाई (Externment)', 'Law', 'MPSC PSI Mains (Paper 2)', 2023, 'महाराष्ट्र पोलीस अधिनियम १९५१ (पूर्वीचा मुंबई पोलीस कायदा) च्या कोणत्या कलमान्वये धोकादायक व्यक्ती किंवा सराईत गुन्हेगारांवर ''तडीपारीची'' (Externment) कारवाई करण्याचे आदेश दिले जातात?', '{"A":"कलम ५६ आणि ५७","B":"कलम १२ आणि १३","C":"कलम २५ आणि २६","D":"कलम ९९ आणि १००"}'::JSONB, 'A', 'महाराष्ट्र पोलीस कायदा १९५१ च्या कलम ५६ अन्वये गुन्हेगारी हालचाली करणाऱ्या किंवा जनतेच्या जीवितास धोका निर्माण करणाऱ्या इसमांना, आणि कलम ५७ अन्वये विशिष्ट गुन्ह्यांमध्ये पूर्वी शिक्षा झालेल्या इसमांना विहित क्षेत्राबाहेर तडीपार करण्याचे अधिकार पोलीस आयुक्त किंवा जिल्हा दंडाधिकाऱ्यांना आहेत.', ARRAY['maharashtra police act', 'मुंबई पोलीस कायदा', 'तडीपारी', 'externment', 'कलम ५६', 'mpsc psi', 'police act']::TEXT[], ''),
  (44, 'Maharashtra Police Act 1951 — पोलीस अधिकाऱ्यांचे कर्तव्य व अधिकार', 'Law', 'MPSC PSI Mains (Paper 2)', 2022, 'महाराष्ट्र पोलीस अधिनियम १९५१ च्या कलम ६४ नुसार खालीलपैकी कोणते कर्तव्य प्रत्येक पोलीस अधिकाऱ्याचे प्राथमिक वैधानिक कर्तव्य मानले जाते?', '{"A":"कायदा व सुव्यवस्था राखणे, सार्वजनिक उपद्रव टाळणे आणि गुन्ह्यांचा प्रतिबंध व तपास करणे","B":"कर वसुली करणे आणि जमिनीच्या महसुलाची नोंद ठेवणे","C":"पंचायत समितीच्या निवडणुकांचे निकाल जाहीर करणे","D":"खाजगी मालमत्तेचे लिलाव आयोजित करणे"}'::JSONB, 'A', 'महाराष्ट्र पोलीस अधिनियम १९५१ च्या कलम ६४ मध्ये पोलीस अधिकाऱ्यांच्या कर्तव्यांची स्पष्ट यादी दिली आहे, ज्यामध्ये सार्वजनिक शांतता व सुव्यवस्था राखणे, गुन्हे रोखणे व गुन्हेगारांना न्यायालयापुढे आणणे यांचा समावेश आहे.', ARRAY['maharashtra police act', 'powers of police officers', 'police duties', 'पोलीस कर्तव्ये', 'mpsc psi']::TEXT[], ''),
  (45, 'Protection of Human Rights Act 1993 — मानवाधिकार आयोग', 'Polity', 'MPSC PSI Mains & Combined', 2023, 'मानवाधिकार संरक्षण अधिनियम १९९३ नुसार राष्ट्रीय मानवाधिकार आयोगाच्या (NHRC) अध्यक्षांची आणि सदस्यांची नियुक्ती कोणाद्वारे केली जाते?', '{"A":"राष्ट्रपतींद्वारे (पंतप्रधानांच्या अध्यक्षतेखालील ६ सदस्यीय उच्चस्तरीय समितीच्या शिफारशीनुसार)","B":"भारताच्या सरन्यायाधीशांद्वारे थेट","C":"केंद्रीय गृहमंत्र्यांच्या एकट्या आदेशाने","D":"लोकसभेच्या अध्यक्षांद्वारे"}'::JSONB, 'A', 'मानवाधिकार संरक्षण कायदा १९९३ च्या कलम ४ नुसार राष्ट्रपती NHRC च्या अध्यक्षांची नियुक्ती करतात. यासाठी पंतप्रधान, लोकसभा अध्यक्ष, केंद्रीय गृहमंत्री, दोन्ही सभागृहांचे विरोधी पक्षनेते आणि राज्यसभेचे उपसभापती यांची ६ सदस्यीय निवड समिती शिफारस करते.', ARRAY['protection of human rights act 1993', 'nhrc', 'मानवाधिकार संरक्षण कायदा', 'human rights', 'mpsc psi']::TEXT[], ''),
  (46, 'SC & ST (Prevention of Atrocities) Act 1989 — जामीन व तरतुदी', 'Law', 'MPSC PSI Mains (Paper 2)', 2023, 'अनुसूचित जाती आणि अनुसूचित जमाती (अत्याचार प्रतिबंध) अधिनियम १९८९ (Atrocities Act) च्या कलम १८ अन्वये खालीलपैकी कोणती महत्त्वाची कायदेशीर तरतूद आहे?', '{"A":"या कायद्याखालील गुन्ह्यांमध्ये CrPC कलम ४३८ अन्वये अटकपूर्व जामीन (Anticipatory Bail) लागू होत नाही","B":"कोणताही गुन्हा जामीनपात्र असतो आणि पोलीस ठाण्यातच जामीन मिळतो","C":"तपासासाठी न्यायालयाची पूर्वपरवानगी आवश्यक नसते","D":"आरोपीला केवळ आर्थिक दंड होतो, तुरुंगवास होत नाही"}'::JSONB, 'A', 'SC/ST Atrocities Act 1989 च्या कलम १८ नुसार या कायद्यांतर्गत झालेल्या गुन्ह्यांमध्ये CrPC कलम ४३८ (अटकपूर्व जामीन) च्या तरतुदी लागू होत नाहीत. तसेच या कायद्यातील गुन्ह्यांचा तपास पोलीस उपअधीक्षक (DySP) दर्जाच्या अधिकाऱ्यामार्फतच होणे बंधनकारक आहे.', ARRAY['atrocities act', 'sc st act 1989', 'अत्याचार प्रतिबंध कायदा', 'anticipatory bail bar', 'mpsc psi']::TEXT[], ''),
  (47, 'IT Act 2000 — सायबर गुन्हे व शिक्षा (Cyber Crime)', 'Science', 'MPSC PSI Mains & Group C', 2022, 'माहिती तंत्रज्ञान कायदा २००० (IT Act 2000) च्या कलम ६६-E नुसार व्यक्तीच्या संमतीशिवाय तिच्या शरीराच्या खाजगी भागाचे छायाचित्र काढून ते इंटरनेटवर प्रसारित केल्यास (Violation of Privacy) कोणती शिक्षा होऊ शकते?', '{"A":"३ वर्षांपर्यंत कारावास किंवा ₹२ लाखांपर्यंत दंड किंवा दोन्ही","B":"६ महिने कारावास किंवा ₹१०,००० दंड","C":"१० वर्षांचा सश्रम कारावास","D":"केवळ समज देऊन सोडून दिले जाते"}'::JSONB, 'A', 'IT Act कलम ६६-E अन्वये प्रायव्हसीचे उल्लंघन (Violation of bodily privacy) हा दखलपात्र गुन्हा असून यासाठी कमाल ३ वर्षांचा कारावास किंवा ₹२ लाख दंड किंवा दोन्ही शिक्षांची तरतूद आहे.', ARRAY['it act 2000', 'cyber crime', 'कलम ६६e', 'सायबर गुन्हे', 'mpsc psi']::TEXT[], ''),
  (48, 'Goods & Services Tax — Input Tax Credit (ITC)', 'Economy', 'MPSC STI Mains (Paper 2)', 2023, 'वस्तू व सेवा कर (GST) कायद्यातील ''इनपुट टॅक्स क्रेडिट'' (Input Tax Credit - ITC) या संकल्पनेचा प्राथमिक उद्देश कोणता आहे?', '{"A":"करावर कर आकारणी (Cascading Effect of Taxes) रोखणे व अंतिम कराचा भार कमी करणे","B":"सर्व व्यापाऱ्यांना शून्य टक्के कर देणे","C":"केवळ आयात मालावर अतिरिक्त कर आकारणे","D":"रोख रकमेच्या व्यवहारांवर बंदी घालणे"}'::JSONB, 'A', 'Input Tax Credit (ITC) मुळे उत्पादक किंवा विक्रेत्याला कच्चा माल खरेदी करताना भरलेला कर, विक्री करताना जमा करावयाच्या करातून वजा (Set-off) मिळतो. यामुळे ''कॅस्केडिंग इफेक्ट'' (Cascading Effect of Tax on Tax) टळतो.', ARRAY['input tax credit', 'itc', 'gst', 'cgst', 'sgst', 'igst', 'goods and services tax', 'sti mains', 'mpsc sti']::TEXT[], ''),
  (49, 'GST — रचना योजना व जीएसटी परिषद (Composition Levy & GST Council)', 'Economy', 'MPSC STI Mains (Paper 2)', 2022, 'भारतीय संविधानाच्या कलम २७९-A अन्वये स्थापन झालेल्या ''जीएसटी परिषदेचे'' (GST Council) अध्यक्ष कोण असतात आणि निर्णयासाठी किती मताधिक्य आवश्यक असते?', '{"A":"केंद्रीय अर्थमंत्री अध्यक्ष असतात; आणि निर्णयासाठी किमान ७५% (३/४) भारित मताधिक्य (Weighted Majority) लागते","B":"भारताचे पंतप्रधान अध्यक्ष असतात; साधे बहुमताने निर्णय होतात","C":"रिझर्व्ह बँकेचे गव्हर्नर अध्यक्ष असतात; ५०% मताधिक्य लागते","D":"सर्व राज्यांचे मुख्यमंत्री आळीपाळीने अध्यक्ष होतात"}'::JSONB, 'A', 'कलम २७९-A नुसार जीएसटी परिषदेच्या अध्यक्ष केंद्रीय अर्थमंत्री असतात आणि सर्व राज्यांचे अर्थमंत्री सदस्य असतात. परिषदेत केंद्राचे मतभार १/३ आणि राज्यांचे मतभार २/३ असते; कोणताही निर्णय घेण्यासाठी उपस्थित सदस्यांच्या किमान ३/४ (७५%) भारित बहुमताची आवश्यकता असते.', ARRAY['gst council', 'composition levy', 'article 279a', 'जीएसटी परिषद', 'cgst', 'sgst', 'igst', 'mpsc sti', 'taxation']::TEXT[], ''),
  (50, 'Public Finance — FRBM Act व राजकोषीय शिस्त', 'Economy', 'MPSC STI Mains (Paper 2)', 2023, 'राजकोषीय जबाबदारी आणि अंदाजपत्रक व्यवस्थापन कायदा २००३ (FRBM Act 2003) चे मुख्य उद्दिष्ट खालीलपैकी कोणते आहे?', '{"A":"सरकारी महसुली तूट शून्यावर आणणे, राजकोषीय तूट GDP च्या ३% पर्यंत मर्यादित ठेवणे आणि दीर्घकालीन समष्टि-आर्थिक स्थैर्य राखणे","B":"देशातील सर्व बँकांचे विलीनीकरण करणे","C":"परकीय चलनाचा साठा संपवणे","D":"केवळ केंद्र सरकारचा खर्च दुप्पट करणे"}'::JSONB, 'A', 'FRBM Act 2003 द्वारे केंद्र आणि राज्य शासनांना राजकोषीय शिस्त (Fiscal Discipline) पाळणे बंधनकारक करण्यात आले, ज्यामध्ये राजकोषीय तूट ३% च्या आत आणणे व पारदर्शकता राखणे अनिवार्य केले गेले.', ARRAY['frbm act', 'fiscal deficit', 'state fiscal deficit', 'public finance', 'राजकोषीय शिस्त', 'sti mains', 'mpsc']::TEXT[], '')
INSERT INTO pyq_questions (id, topic, subject, exam, year, question, options, correct, explanation, tags, difficulty)
VALUES
  (51, 'Economic Reforms — १९९१ ची आर्थिक सुधारणा (LPG Reforms)', 'Economy', 'MPSC STI Mains (Paper 2)', 2021, 'भारतात १९९१ मध्ये जाहीर करण्यात आलेल्या नवीन औद्योगिक व आर्थिक धोरणामध्ये (LPG Policy) ''L-P-G'' चे पूर्ण रूप काय आहे?', '{"A":"Liberalization (उदारीकरण), Privatization (खाजगीकरण), Globalization (जागतिकीकरण)","B":"Liquidity, Pricing, Growth","C":"Local Production Guarantee","D":"Law, Policy, Governance"}'::JSONB, 'A', '१९९१ च्या परकीय चलन संकटाच्या पार्श्वभूमीवर तत्कालीन पंतप्रधान पी. व्ही. नरसिंहराव आणि अर्थमंत्री डॉ. मनमोहन सिंग यांनी उदारीकरण (Liberalization), खाजगीकरण (Privatization) आणि जागतिकीकरण (Globalization) चे LPG प्रारूप स्वीकारले.', ARRAY['1991 lpg reforms', 'उदारीकरण', 'खाजगीकरण', 'जागतिकीकरण', 'economic reforms', 'mpsc sti']::TEXT[], ''),
  (52, 'भारत छोडो आंदोलन', 'History', 'MPSC Combined & Police Bharti', 2023, '''करेंगे या मरेंगे'' ही घोषणा कोणत्या आंदोलनाशी संबंधित आहे?', '{"A":"भारत छोडो आंदोलन 1942","B":"असहकार चळवळ 1920","C":"सविनय कायदेभंग 1930","D":"खिलाफत चळवळ"}'::JSONB, 'A', 'महात्मा गांधींनी 8 ऑगस्ट 1942 रोजी मुंबईत करेंगे या मरेंगे ही घोषणा दिली. हे भारत छोडो आंदोलन होते.', ARRAY['quit india', 'bharat chhodo', '1942', 'gandhi', 'mpsc history']::TEXT[], ''),
  (53, 'असहकार चळवळ', 'History', 'MPSC Rajyaseva & Combined', 2021, 'असहकार चळवळ कोणत्या वर्षी सुरू झाली आणि कोणत्या घटनेमुळे ती मागे घेण्यात आली?', '{"A":"1920 — चौरीचौरा हत्याकांड फेब्रुवारी 1922","B":"1919 — जालियनवाला बाग","C":"1923 — सायमन कमिशन","D":"1921 — मोपला उठाव"}'::JSONB, 'A', 'फेब्रुवारी 1922 मध्ये चौरीचौरा येथे 22 पोलिसांना जाळून मारले गेले. या हिंसाचारामुळे गांधीजींनी चळवळ मागे घेतली.', ARRAY['non cooperation', 'chauri chaura', '1920', 'gandhi', 'mpsc']::TEXT[], ''),
  (54, 'जालियनवाला बाग हत्याकांड', 'History', 'MPSC Combined Group B', 2022, 'जालियनवाला बाग हत्याकांड (13 एप्रिल 1919) कोणत्या कायद्याविरुद्ध निदर्शनाच्या संदर्भात झाले?', '{"A":"रौलट कायदा 1919 (काळा कायदा)","B":"इलबर्ट बिल","C":"व्हर्नाक्युलर प्रेस कायदा","D":"आर्म्स कायदा"}'::JSONB, 'A', 'रौलट कायद्याच्या निषेधार्थ अमृतसरच्या जालियनवाला बागेत जमलेल्या निशस्त्र जनतेवर जनरल डायरने गोळीबार केला.', ARRAY['jallianwala bagh', 'rowlatt act', 'dyer', '1919', 'history', 'mpsc']::TEXT[], ''),
