VALUES
  (151, 'ज्ञानेश्वरी — 1290', 'Marathi', 'MPSC Combined & Rajyaseva', 2021, 'संत ज्ञानेश्वरांनी ''ज्ञानेश्वरी'' किती वर्षे वयात लिहिली?', '{"A":"15-16 वर्षे वयात (इ.स. 1290)","B":"25 वर्षे","C":"35 वर्षे","D":"12 वर्षे"}'::JSONB, 'A', 'संत ज्ञानेश्वरांनी वयाच्या 15-16 व्या वर्षी (1290) नेवासे येथे ज्ञानेश्वरी लिहिली.', ARRAY['dnyaneshwari', 'dnyaneshwar', 'marathi literature', '1290', 'bhagavad gita']::TEXT[], ''),
  (152, 'मराठी व्याकरण — काळ भविष्यकाळ', 'Marathi', 'MPSC Combined & Talathi', 2023, '''तो शाळेत जाईल'' — या वाक्यातील क्रियापदाचा काळ?', '{"A":"भविष्यकाळ (Future Tense)","B":"भूतकाळ (Past Tense)","C":"वर्तमानकाळ (Present Tense)","D":"अपूर्ण भूतकाळ"}'::JSONB, 'A', 'जाईल हे क्रियापद भविष्यात होणाऱ्या क्रियेचे सूचन करते म्हणून साधा भविष्यकाळ.', ARRAY['kaal', 'tense', 'future tense', 'marathi grammar', 'mpsc']::TEXT[], ''),
  (153, 'संत तुकाराम — देहू', 'Marathi', 'MPSC Combined & Police Bharti', 2022, 'संत तुकाराम महाराजांचे जन्मस्थान कोणते?', '{"A":"देहू (पुणे) — अंदाजे 4500 अभंग","B":"पंढरपूर — 2000 अभंग","C":"आळंदी — 3000 अभंग","D":"नेवासे — 1000 अभंग"}'::JSONB, 'A', 'संत तुकाराम (1608-1650) यांचे जन्मस्थान देहू (पुणे). अंदाजे 4500 अभंग रचले.', ARRAY['tukaram', 'dehu', 'abhang', 'warkari', 'marathi literature']::TEXT[], ''),
  (154, 'मराठी व्याकरण — लिंग शाळा', 'Marathi', 'Police Bharti & Talathi', 2023, '''शाळा'' या शब्दाचे लिंग?', '{"A":"स्त्रीलिंग","B":"पुल्लिंग","C":"नपुंसकलिंग","D":"क्लीबलिंग"}'::JSONB, 'A', 'शाळा, नदी, माती, हवा हे स्त्रीलिंगी शब्द. मराठीत तीन लिंगे: पुल्लिंग, स्त्रीलिंग, नपुंसकलिंग.', ARRAY['linga', 'gender', 'marathi grammar', 'police bharti']::TEXT[], ''),
  (155, 'मराठी साहित्य — संत नामदेव', 'Marathi', 'MPSC Combined & Police Bharti', 2021, 'संत नामदेव महाराजांचे गुरू कोण?', '{"A":"संत विसोबा खेचर","B":"संत ज्ञानेश्वर","C":"संत एकनाथ","D":"संत तुकाराम"}'::JSONB, 'A', 'संत नामदेव (1270-1350) यांचे गुरू संत विसोबा खेचर. हिंदी आणि मराठी दोन्ही भाषांत अभंग रचले.', ARRAY['sant namdev', 'visoba khechar', 'warkari', 'marathi literature', 'saints']::TEXT[], ''),
  (156, 'मराठी वाक्य — मिश्र वाक्य', 'Marathi', 'Police Bharti & Talathi', 2022, '''जे चकाकते ते सर्व सोने नसते'' हे वाक्य कोणत्या प्रकारचे?', '{"A":"मिश्र वाक्य","B":"केवल वाक्य","C":"संयुक्त वाक्य","D":"नकारार्थी केवल वाक्य"}'::JSONB, 'A', 'या वाक्यात मुख्य वाक्य आणि गौण वाक्य संबंधी सर्वनामांनी जोडले. म्हणून मिश्र वाक्य.', ARRAY['vakya prakar', 'मिश्र वाक्य', 'sentence structure', 'marathi', 'mpsc']::TEXT[], ''),
  (157, 'वाक्प्रचार — हात वर करणे', 'Marathi', 'Police Bharti & Talathi', 2022, '''हात वर करणे'' या वाक्प्रचाराचा अर्थ काय?', '{"A":"हार मानणे / शरण जाणे","B":"हात धुणे","C":"आनंद व्यक्त करणे","D":"मदत मागणे"}'::JSONB, 'A', 'हात वर करणे म्हणजे हार मानणे, शरण जाणे. उदा. शत्रूने हात वर केले.', ARRAY['vakprachar', 'idiom', 'marathi grammar', 'police bharti']::TEXT[], ''),
  (158, 'म्हणी — जशास तसे', 'Marathi', 'Police Bharti & Talathi', 2023, '''जशास तसे'' या म्हणीचा अर्थ काय?', '{"A":"ज्या प्रकारे वागवले त्याच प्रकारे उत्तर देणे (Tit for tat)","B":"साध्या माणसाशी साध्याने वागणे","C":"जे मिळेल ते स्वीकारणे","D":"कोणाशीही न भांडणे"}'::JSONB, 'A', 'जशास तसे म्हणजे जो ज्या प्रकारे वागतो त्याला त्याच प्रकारे उत्तर देणे. Tit for tat.', ARRAY['mhani', 'proverbs', 'marathi grammar', 'police bharti', 'talathi']::TEXT[], ''),
  (159, 'Passive Voice — Past Simple', 'English', 'SSC CGL & TCS Talathi', 2023, 'Change to Passive Voice: ''The committee rejected the proposal.''', '{"A":"The proposal was rejected by the committee.","B":"The proposal has been rejected by the committee.","C":"The proposal is rejected by the committee.","D":"The proposal had been rejected by the committee."}'::JSONB, 'A', 'Simple Past Active → Passive: Object + was/were + V₃ + by + Subject. Rejected → was rejected.', ARRAY['passive voice', 'active passive', 'grammar', 'english', 'ssc', 'tcs']::TEXT[], ''),
  (160, 'Synonyms — DILIGENT', 'English', 'SSC CGL & Talathi', 2022, 'Choose the correct synonym for ''DILIGENT'':', '{"A":"Hardworking / Industrious","B":"Lazy / Idle","C":"Brilliant / Intelligent","D":"Corrupt / Dishonest"}'::JSONB, 'A', 'Diligent means showing steady earnest effort. Synonyms: industrious, hardworking, assiduous.', ARRAY['synonyms', 'diligent', 'vocabulary', 'english', 'ssc']::TEXT[], ''),
  (161, 'One Word — Astronomer', 'English', 'SSC CGL & TCS Talathi', 2023, 'One word for ''A person who studies the stars and planets'':', '{"A":"Astronomer","B":"Astrologer","C":"Cosmologist","D":"Physicist"}'::JSONB, 'A', 'Astronomer scientifically studies celestial objects. Astrologer believes stars influence fate.', ARRAY['one word substitution', 'astronomer', 'english', 'ssc', 'vocabulary']::TEXT[], ''),
  (162, 'Prepositions — for', 'English', 'TCS Talathi & SSC CHSL', 2022, 'Choose the correct preposition: ''She has been working _____ this company since 2019.''', '{"A":"for","B":"in","C":"at","D":"with"}'::JSONB, 'A', 'Working for a company is the correct usage. For indicates employment or duration.', ARRAY['prepositions', 'for', 'grammar', 'english', 'talathi', 'ssc']::TEXT[], ''),
  (163, 'Antonyms — BENEVOLENT', 'English', 'SSC CGL & Talathi', 2023, 'Choose the correct antonym of ''BENEVOLENT'':', '{"A":"Malevolent / Malicious","B":"Generous / Kind","C":"Neutral / Indifferent","D":"Eloquent"}'::JSONB, 'A', 'Benevolent means kind, generous. Antonym: Malevolent (wishing harm). Also: cruel, unkind.', ARRAY['antonyms', 'benevolent', 'malevolent', 'vocabulary', 'english', 'ssc']::TEXT[], ''),
  (164, 'Neither — Singular Verb', 'English', 'SSC CGL & TCS Talathi', 2022, 'Find the error: ''Neither of the candidates were qualified for the position.''', '{"A":"B — ''was'' should replace ''were'' (Neither takes singular verb)","B":"A — Neither should be None","C":"C — for this position","D":"No error"}'::JSONB, 'A', 'Neither of the candidates WAS qualified. Neither always takes singular verb.', ARRAY['error detection', 'neither', 'subject verb agreement', 'english', 'ssc']::TEXT[], ''),
  (165, 'Idiom — Kick the Bucket', 'English', 'SSC CGL & Talathi', 2021, 'The idiom ''Kick the bucket'' means:', '{"A":"To die","B":"To score a goal","C":"To fail badly","D":"To run away"}'::JSONB, 'A', 'Kick the bucket is an informal idiom meaning to die. Example: He kicked the bucket last night.', ARRAY['idioms', 'kick the bucket', 'phrases', 'english', 'ssc']::TEXT[], ''),
  (166, 'Articles — an honest', 'English', 'SSC CGL & Talathi', 2022, 'Choose the correct article: ''She is _____ honest woman.''', '{"A":"an","B":"a","C":"the","D":"no article"}'::JSONB, 'A', 'Before words with vowel sound use an. Honest has silent h (vowel sound). Hence: an honest woman.', ARRAY['articles', 'an', 'grammar', 'english', 'ssc', 'talathi']::TEXT[], ''),
  (167, 'बैठक व्यवस्था', 'Reasoning', 'MPSC CSAT & Police Bharti', 2023, 'A B C D E पाच मित्र गोल टेबलाभोवती बसले. A च्या उजव्या B, B च्या उजव्या C, E च्या डाव्या D, C आणि D बाजूला नाहीत. A च्या डाव्या कोण?', '{"A":"D","B":"E","C":"C","D":"B"}'::JSONB, 'A', 'घड्याळाच्या दिशेने: A-B-C-E-D. A च्या डाव्या बाजूला D आहे.', ARRAY['seating arrangement', 'circular', 'reasoning', 'mpsc csat']::TEXT[], ''),
  (168, 'संख्यामालिका 2 6 12 20 30', 'Reasoning', 'TCS Talathi & SSC CGL', 2023, 'मालिका पूर्ण करा: 2, 6, 12, 20, 30, ___', '{"A":"42","B":"40","C":"36","D":"44"}'::JSONB, 'A', 'n(n+1) सूत्राने: 6×7=42. फरक मालिका: 4,6,8,10,12 → 30+12=42.', ARRAY['number series', 'reasoning', 'tcs', 'ssc', 'talathi']::TEXT[], ''),
  (169, 'दिशा — उत्तर पूर्व दक्षिण', 'Reasoning', 'Police Bharti & Talathi', 2022, 'सुरेश उत्तरेकडे 5 किमी, उजवीकडे वळून 3 किमी, पुन्हा उजवीकडे वळून 5 किमी. सुरुवातीपासून कोणत्या दिशेला?', '{"A":"पूर्व","B":"पश्चिम","C":"उत्तर","D":"दक्षिण"}'::JSONB, 'A', 'उत्तर 5 किमी → पूर्व 3 किमी → दक्षिण 5 किमी. सुरुवातीपासून 3 किमी पूर्वेकडे.', ARRAY['direction', 'reasoning', 'police bharti', 'talathi']::TEXT[], ''),
  (170, 'वेन आकृती — 35 25 15', 'Reasoning', 'MPSC CSAT & Police Bharti', 2022, 'वर्गात 35 विद्यार्थी गणित, 25 विज्ञान, 15 दोन्ही शिकतात. एकूण किती?', '{"A":"45","B":"75","C":"60","D":"50"}'::JSONB, 'A', 'n(A∪B) = n(A) + n(B) - n(A∩B) = 35 + 25 - 15 = 45.', ARRAY['venn diagram', 'inclusion exclusion', 'reasoning', 'csat', 'mpsc']::TEXT[], ''),
  (171, 'सरासरी — 5 संख्या', 'Reasoning', 'Talathi & Police Bharti', 2023, '5 संख्यांची सरासरी 42. एक संख्या वाढवून 62 केली, नवीन सरासरी?', '{"A":"46","B":"44","C":"48","D":"50"}'::JSONB, 'A', 'मूळ बेरीज = 210. वाढ = 20. नवी बेरीज = 230. नवी सरासरी = 230/5 = 46.', ARRAY['average', 'arithmetic', 'reasoning', 'talathi']::TEXT[], ''),
  (172, 'शब्दजोड्या DOCTOR HOSPITAL JUDGE', 'Reasoning', 'SSC CGL & Police Bharti', 2022, 'DOCTOR : HOSPITAL :: JUDGE : ?', '{"A":"COURT","B":"SCHOOL","C":"OFFICE","D":"PRISON"}'::JSONB, 'A', 'डॉक्टर रुग्णालयात काम करतो, न्यायाधीश न्यायालयात काम करतो.', ARRAY['analogy', 'doctor hospital', 'judge court', 'reasoning', 'ssc']::TEXT[], ''),
  (173, 'नफा व तोटा 800 920', 'Reasoning', 'Talathi & Police Bharti', 2023, 'वस्तू ₹800 मध्ये विकत घेऊन ₹920 मध्ये विकली, तर नफ्याची टक्केवारी?', '{"A":"15%","B":"12%","C":"10%","D":"18%"}'::JSONB, 'A', 'नफा = 920-800 = ₹120. नफा % = (120/800)×100 = 15%.', ARRAY['profit loss', 'percentage', 'arithmetic', 'talathi']::TEXT[], ''),
  (174, 'गुणोत्तर — 3:5 45', 'Reasoning', 'Talathi & Police Bharti', 2022, 'A आणि B यांचे गुणोत्तर 3:5. जर A = ₹45, तर B?', '{"A":"₹75","B":"₹60","C":"₹90","D":"₹54"}'::JSONB, 'A', '3:5 = 45:? → ? = (45×5)/3 = ₹75. किंवा एक भाग = ₹15, B = 5×15 = ₹75.', ARRAY['ratio proportion', 'arithmetic', 'reasoning', 'talathi']::TEXT[], ''),
  (175, 'टक्केवारी 375/500', 'Reasoning', 'SSC CGL & TCS Talathi', 2023, 'परीक्षेत 500 पैकी 375 गुण. टक्केवारी?', '{"A":"75%","B":"70%","C":"80%","D":"65%"}'::JSONB, 'A', 'टक्केवारी = (375/500)×100 = 75%.', ARRAY['percentage', 'calculation', 'reasoning', 'ssc', 'talathi']::TEXT[], ''),
  (176, 'साधे व्याज SI 5000 8% 3yr', 'Reasoning', 'MPSC Combined & Banking', 2022, '₹5000 वर वार्षिक 8% दराने 3 वर्षांचे साधे व्याज?', '{"A":"₹1200","B":"₹1000","C":"₹1500","D":"₹900"}'::JSONB, 'A', 'साधे व्याज = (P × R × T)/100 = (5000×8×3)/100 = ₹1200.', ARRAY['simple interest', 'SI', 'arithmetic', 'banking', 'mpsc']::TEXT[], ''),
  (177, 'मिश्र व्याज CI 2000 10% 2yr', 'Reasoning', 'Banking & SSC CGL', 2023, '₹2000 वर वार्षिक 10% दराने 2 वर्षांचे मिश्र व्याज?', '{"A":"₹420","B":"₹400","C":"₹440","D":"₹380"}'::JSONB, 'A', 'CI = P[(1+r/100)ⁿ - 1] = 2000[(1.1)² - 1] = 2000×0.21 = ₹420.', ARRAY['compound interest', 'CI', 'arithmetic', 'banking', 'ssc']::TEXT[], ''),
  (178, 'अक्षर मालिका A C F J O', 'Reasoning', 'SSC CGL & Police Bharti', 2022, 'मालिका: A, C, F, J, O, ?', '{"A":"U","B":"V","C":"T","D":"S"}'::JSONB, 'A', 'A+2=C, C+3=F, F+4=J, J+5=O, O+6=U. फरक +2,+3,+4,+5,+6.', ARRAY['letter series', 'reasoning', 'ssc', 'police bharti']::TEXT[], ''),
  (179, 'घड्याळ — 3 वाजता कोन', 'Reasoning', 'TCS Talathi & SSC CGL', 2023, 'घड्याळात 3:00 वाजता तासाचे काटे आणि मिनिटाचे काटे यांच्यात कोन?', '{"A":"90°","B":"180°","C":"45°","D":"60°"}'::JSONB, 'A', '3:00 वाजता: तासाचा काटा 90° (3×30°=90°), मिनिटाचा काटा 0°. कोन = 90°.', ARRAY['clock problems', 'angle', 'reasoning', 'tcs talathi', 'ssc']::TEXT[], ''),
  (180, 'वय प्रमाण — 30 20 5 वर्षापूर्वी', 'Reasoning', 'Talathi & Police Bharti', 2023, 'रामाचे वय 30, श्यामाचे 20. 5 वर्षापूर्वी त्यांचे वय प्रमाण?', '{"A":"5:3","B":"3:2","C":"2:1","D":"5:2"}'::JSONB, 'A', '5 वर्षापूर्वी: राम = 25, श्याम = 15. प्रमाण = 25:15 = 5:3.', ARRAY['age problems', 'age ratio', 'reasoning', 'talathi', 'police bharti']::TEXT[], ''),
  (181, 'त्रिकोण क्षेत्रफळ 12×8', 'Reasoning', 'Talathi & Police Bharti', 2022, 'त्रिकोणाचा पाया 12 सेमी आणि उंची 8 सेमी असल्यास क्षेत्रफळ?', '{"A":"48 चौ.सेमी","B":"96 चौ.सेमी","C":"60 चौ.सेमी","D":"36 चौ.सेमी"}'::JSONB, 'A', 'त्रिकोणाचे क्षेत्रफळ = (1/2)×base×height = (1/2)×12×8 = 48 चौ.सेमी.', ARRAY['area triangle', 'geometry', 'reasoning', 'talathi', 'police bharti']::TEXT[], ''),
  (182, 'पाईप टाकी 6hr 12hr', 'Reasoning', 'Talathi & Banking', 2022, 'एका नळाने टाकी 6 तासात भरते, दुसऱ्याने 12 तासात. दोन्ही एकत्र किती तासात?', '{"A":"4 तास","B":"3 तास","C":"5 तास","D":"8 तास"}'::JSONB, 'A', 'एकत्र दर = 1/6 + 1/12 = 3/12 = 1/4. वेळ = 4 तास.', ARRAY['pipes cisterns', 'LCM', 'reasoning', 'banking', 'talathi']::TEXT[], ''),
  (183, 'वेग अंतर वेळ 120 किमी 2 तास', 'Reasoning', 'SSC CGL & Police Bharti', 2023, 'गाडी 120 किमी अंतर 2 तासात पूर्ण करते. वेग (speed) किती?', '{"A":"60 किमी/तास","B":"120 किमी/तास","C":"90 किमी/तास","D":"30 किमी/तास"}'::JSONB, 'A', 'वेग = अंतर/वेळ = 120/2 = 60 किमी/तास.', ARRAY['speed distance time', 'reasoning', 'ssc', 'police bharti']::TEXT[], ''),
  (184, 'कूटभाषा MPSC NQTD', 'Reasoning', 'TCS Talathi & Police Bharti', 2023, 'MPSC = NQTD कूटभाषेत, ''POLICE'' कसा लिहिला जाईल?', '{"A":"QPMJDF","B":"QPNJDF","C":"ROMJDE","D":"QQMKDF"}'::JSONB, 'A', 'प्रत्येक अक्षरात +1: P+1=Q, O+1=P, L+1=M, I+1=J, C+1=D, E+1=F → QPMJDF.', ARRAY['coding decoding', 'reasoning', 'police bharti', 'tcs']::TEXT[], ''),
  (185, 'रक्तसंबंध — आईचा मुलगा', 'Reasoning', 'MPSC CSAT & Police Bharti', 2022, 'छायाचित्राकडे बोट दाखवून सुरेश म्हणाला, ही स्त्री माझ्या आईच्या एकुलत्या एका मुलाची मुलगी आहे. नाते?', '{"A":"मुलगी (Daughter)","B":"बहीण (Sister)","C":"भाची (Niece)","D":"पत्नी (Wife)"}'::JSONB, 'A', 'माझ्या आईचा एकुलता एक मुलगा = स्वतः सुरेश. त्याची मुलगी = सुरेशची मुलगी.', ARRAY['blood relations', 'reasoning', 'csat']::TEXT[], ''),
  (186, 'PM-KISAN ₹6000', 'Economy', 'MPSC Combined & Talathi', 2023, 'PM-KISAN योजनेअंतर्गत शेतकऱ्यांना दरवर्षी किती रक्कम?', '{"A":"₹6000 (तीन हप्त्यांत ₹2000-₹2000-₹2000)","B":"₹5000","C":"₹8000","D":"₹10000"}'::JSONB, 'A', 'PM-KISAN (Pradhan Mantri Kisan Samman Nidhi) अंतर्गत दरवर्षी ₹6000 तीन समान हप्त्यांत.', ARRAY['PM KISAN', 'farmer scheme', '6000', 'agriculture', 'economy', 'mpsc']::TEXT[], ''),
  (187, 'आयुष्मान भारत ₹5 लाख', 'Economy', 'MPSC Combined & Police Bharti', 2022, 'आयुष्मान भारत (PM-JAY) योजनेअंतर्गत प्रति कुटुंब किती आरोग्य कवच?', '{"A":"₹5 लाख प्रति कुटुंब प्रति वर्ष","B":"₹2 लाख","C":"₹10 लाख","D":"₹1 लाख"}'::JSONB, 'A', 'आयुष्मान भारत PM-JAY अंतर्गत प्रति कुटुंब प्रति वर्ष ₹5 लाख आरोग्य विमा.', ARRAY['ayushman bharat', 'PM-JAY', 'health insurance', '5 lakh', 'economy', 'mpsc']::TEXT[], ''),
