  (225, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'MPSC Combined Group B & C', 2018, 'शुद्ध पाण्याचे pH मूल्य किती असते?', '{"A":"7 (उदासीन)","B":"0","C":"14","D":"4"}'::JSONB, 'A', 'pH स्केलवर 7 म्हणजे उदासीन (उदा. शुद्ध पाणी). 7 पेक्षा कमी म्हणजे आम्लधर्मी (Acidic) आणि 7 पेक्षा जास्त म्हणजे आम्लारीधर्मी (Basic).', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'MPSC', '2018']::TEXT[], 'Hard'),
  (226, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'MPSC State Services (Rajyaseva)', 2019, 'मराठी वर्णमालेत एकूण किती मूळ स्वर मानले जातात?', '{"A":"12 स्वर (+ 2 इंग्रजी स्वर = 14)","B":"10 स्वर","C":"16 स्वर","D":"8 स्वर"}'::JSONB, 'A', 'पारंपरिक वर्णमालेत 12 स्वर होते. महाराष्ट्र शासनाच्या 2009 च्या जीआरनुसार ॲ आणि ऑ मिळून एकूण 14 स्वर आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'MPSC', '2019']::TEXT[], 'Easy'),
