  (231, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'IBPS / State Cooperative Bank', 2024, '1942 च्या चले जाव आंदोलनात सातारा येथे "प्रतिसरकार" (Patri Sarkar) ची स्थापना कोणी केली?', '{"A":"क्रांतिसिंह नाना पाटील","B":"सेनापती बापट","C":"किसन वीर","D":"वसंतदादा पाटील"}'::JSONB, 'A', 'क्रांतिसिंह नाना पाटील यांनी साताऱ्यात प्रतिसरकार स्थापन करून समांतर न्याय व प्रशासकीय व्यवस्था उभारली, ज्यास "पत्री सरकार" म्हटले जायचे.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'IBPS', '2024']::TEXT[], 'Hard'),
  (232, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'MPSC Combined Group B & C', 2014, 'भीमा नदीचा उगम पुणे जिल्ह्यातील कोणत्या ज्योतिर्लिंगाजवळ होतो?', '{"A":"भीमाशंकर","B":"त्र्यंबकेश्वर","C":"घृष्णेश्वर","D":"परळी वैजनाथ"}'::JSONB, 'A', 'भीमा नदीचा उगम सह्याद्री पर्वतात भीमाशंकर येथे होतो. भीमा नदी पंढरपूर येथे चंद्रभागा म्हणून ओळखली जाते व पुढे कर्नाटकात कृष्णा नदीस मिळते.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'MPSC', '2014']::TEXT[], 'Easy'),
  (233, 'बँकिंग, वित्त व महागाई', 'Economy', 'MPSC State Services (Rajyaseva)', 2015, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'MPSC', '2015']::TEXT[], 'Medium'),
  (234, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'Maharashtra Police Constable Bharti', 2016, 'पेशीचे "ऊर्जा केंद्र" (Powerhouse of the Cell) कोणाला म्हणतात?', '{"A":"तंतुकणिका (Mitochondria)","B":"रायबोझोम","C":"लायसोझोम","D":"हरितलवके"}'::JSONB, 'A', 'तंतुकणिकेत (Mitochondria) पेशीय श्वसनातून ATP (Adenosine Triphosphate) च्या स्वरूपात ऊर्जा तयार होते, म्हणून त्यास पेशीचे ऊर्जा केंद्र म्हणतात.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'Maharashtra', '2016']::TEXT[], 'Hard'),
  (235, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2017, '"अन्नास जागणे" या वाक्प्रचाराचा अचूक अर्थ काय?', '{"A":"उपकाराची जाणीव ठेवणे (कृतज्ञ राहणे)","B":"अन्न वाया घालवणे","C":"रात्रभर जागत राहणे","D":"जेवणावर ताव मारणे"}'::JSONB, 'A', 'अन्नास जागणे म्हणजे केलेल्या उपकारांची सदैव जाणीव ठेवणे (कृतज्ञ असणे). याचा विरुद्धार्थी वाक्प्रचार "अन्नास कापणे" (कृतघ्न असणे) हा आहे.', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'Maharashtra', '2017']::TEXT[], 'Easy'),
  (236, 'English Grammar & Vocabulary', 'English', 'Maharashtra Vanrakshak (Forest) Bharti', 2018, 'Choose the correct synonym for "TENACIOUS":', '{"A":"Persistent / Determined","B":"Timid","C":"Weak","D":"Cautious"}'::JSONB, 'A', '"Tenacious" means holding fast, persistent, stubborn or resolute.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2018']::TEXT[], 'Medium'),
  (237, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'SSC CGL & CHSL', 2019, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'SSC', '2019']::TEXT[], 'Hard'),
  (238, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'IBPS / State Cooperative Bank', 2020, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'IBPS', '2020']::TEXT[], 'Easy'),
  (239, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'MPSC Combined Group B & C', 2021, 'सर्वोच्च न्यायालयातील न्यायाधीशांचे निवृत्तीचे वय किती वर्षे असते?', '{"A":"65 वर्षे","B":"62 वर्षे","C":"60 वर्षे","D":"70 वर्षे"}'::JSONB, 'A', 'सर्वोच्च न्यायालयाच्या न्यायाधीशांचे निवृत्ती वय 65 वर्षे, तर उच्च न्यायालयाच्या न्यायाधीशांचे 62 वर्षे असते.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'MPSC', '2021']::TEXT[], 'Medium'),
  (240, 'महाराष्ट्रातील समाजसुधारक', 'History', 'MPSC State Services (Rajyaseva)', 2022, 'महर्षी धोंडो केशव कर्वे यांनी 1916 मध्ये पुण्यात कोणत्या पहिल्या महिला विद्यापीठाची स्थापना केली?', '{"A":"SNDT महिला विद्यापीठ","B":"सावित्रीबाई फुले विद्यापीठ","C":"टिळक महाराष्ट्र विद्यापीठ","D":"मुंबई विद्यापीठ"}'::JSONB, 'A', 'महर्षी कर्व्यांनी 1916 मध्ये हिंगणे (पुणे) येथे जपानच्या धर्तीवर स्वतंत्र महिला विद्यापीठ सुरू केले, ज्यास सर विठ्ठलदास ठाकरसी यांच्या मातोश्री नाथीबाई यांच्या स्मरणार्थ SNDT नाव दिले गेले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'MPSC', '2022']::TEXT[], 'Hard'),
  (241, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'Maharashtra Police Constable Bharti', 2023, 'महाराष्ट्रातील तापी नदी कोणत्या दिशेने वाहते?', '{"A":"पश्चिम वाहिनी","B":"पूर्व वाहिनी","C":"दक्षिण वाहिनी","D":"उत्तर वाहिनी"}'::JSONB, 'A', 'तापी आणि नर्मदा या महाराष्ट्रातील प्रमुख पश्चिम वाहिनी नद्या आहेत, ज्या खचदरीतून वाहत जाऊन अरबी समुद्रास (खंबायतचे आखात) मिळतात.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'Maharashtra', '2023']::TEXT[], 'Easy'),
  (242, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2024, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2024']::TEXT[], 'Medium'),
  (243, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'Maharashtra Vanrakshak (Forest) Bharti', 2014, 'पेनिसिलिन या पहिल्या प्रतिजैविकाचा (Antibiotic) शोध कोणी लावला?', '{"A":"अलेक्झांडर फ्लेमिंग","B":"एडवर्ड जेनर","C":"लुई पाश्चर","D":"रॉबर्ट कॉक"}'::JSONB, 'A', '1928 मध्ये अलेक्झांडर फ्लेमिंग यांनी पेनिसिलियम नोटॅटम या बुरशीपासून जगातील पहिले अँटिबायोटिक पेनिसिलिन शोधले.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'Maharashtra', '2014']::TEXT[], 'Hard'),
  (244, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'SSC CGL & CHSL', 2015, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'SSC', '2015']::TEXT[], 'Easy'),
  (245, 'English Grammar & Vocabulary', 'English', 'IBPS / State Cooperative Bank', 2016, 'Identify the meaning of idiom: "A blessing in disguise"', '{"A":"Something good that isn''t recognized at first","B":"A holy prayer","C":"A fake curse","D":"A sudden disaster"}'::JSONB, 'A', '"A blessing in disguise" means an apparent misfortune that eventually results in something unexpectedly good.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'IBPS', '2016']::TEXT[], 'Medium'),
  (246, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'MPSC Combined Group B & C', 2017, 'जर 5 माणसे एक काम 10 दिवसांत करतात, तर 2 माणसे तेच काम किती दिवसांत करतील?', '{"A":"25 दिवस","B":"20 दिवस","C":"15 दिवस","D":"30 दिवस"}'::JSONB, 'A', 'माणसे x दिवस = स्थिरांक. 5 x 10 = 50 मॅन-डेज. 50 / 2 = 25 दिवस.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'MPSC', '2017']::TEXT[], 'Hard'),
  (247, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC State Services (Rajyaseva)', 2018, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2018']::TEXT[], 'Easy'),
  (248, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'Maharashtra Police Constable Bharti', 2019, 'सर्वोच्च न्यायालयातील न्यायाधीशांचे निवृत्तीचे वय किती वर्षे असते?', '{"A":"65 वर्षे","B":"62 वर्षे","C":"60 वर्षे","D":"70 वर्षे"}'::JSONB, 'A', 'सर्वोच्च न्यायालयाच्या न्यायाधीशांचे निवृत्ती वय 65 वर्षे, तर उच्च न्यायालयाच्या न्यायाधीशांचे 62 वर्षे असते.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'Maharashtra', '2019']::TEXT[], 'Medium'),
  (249, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2020, '1942 च्या चले जाव आंदोलनात सातारा येथे "प्रतिसरकार" (Patri Sarkar) ची स्थापना कोणी केली?', '{"A":"क्रांतिसिंह नाना पाटील","B":"सेनापती बापट","C":"किसन वीर","D":"वसंतदादा पाटील"}'::JSONB, 'A', 'क्रांतिसिंह नाना पाटील यांनी साताऱ्यात प्रतिसरकार स्थापन करून समांतर न्याय व प्रशासकीय व्यवस्था उभारली, ज्यास "पत्री सरकार" म्हटले जायचे.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'Maharashtra', '2020']::TEXT[], 'Hard'),
  (250, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'Maharashtra Vanrakshak (Forest) Bharti', 2021, 'महाराष्ट्रातील तापी नदी कोणत्या दिशेने वाहते?', '{"A":"पश्चिम वाहिनी","B":"पूर्व वाहिनी","C":"दक्षिण वाहिनी","D":"उत्तर वाहिनी"}'::JSONB, 'A', 'तापी आणि नर्मदा या महाराष्ट्रातील प्रमुख पश्चिम वाहिनी नद्या आहेत, ज्या खचदरीतून वाहत जाऊन अरबी समुद्रास (खंबायतचे आखात) मिळतात.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'Maharashtra', '2021']::TEXT[], 'Easy')
