  (251, 'बँकिंग, वित्त व महागाई', 'Economy', 'SSC CGL & CHSL', 2022, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'SSC', '2022']::TEXT[], 'Medium'),
  (252, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'IBPS / State Cooperative Bank', 2023, 'शुद्ध पाण्याचे pH मूल्य किती असते?', '{"A":"7 (उदासीन)","B":"0","C":"14","D":"4"}'::JSONB, 'A', 'pH स्केलवर 7 म्हणजे उदासीन (उदा. शुद्ध पाणी). 7 पेक्षा कमी म्हणजे आम्लधर्मी (Acidic) आणि 7 पेक्षा जास्त म्हणजे आम्लारीधर्मी (Basic).', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'IBPS', '2023']::TEXT[], 'Hard'),
  (253, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'MPSC Combined Group B & C', 2024, '"अळंबी" या शब्दाचा समानार्थी शब्द खालीलपैकी कोणता?', '{"A":"मशरूम / छत्रक","B":"अडथळा","C":"आळस","D":"अंधार"}'::JSONB, 'A', 'अळंबी म्हणजे कुत्र्याची छत्री किंवा खाद्य वनस्पती (Mushroom / छत्रक).', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'MPSC', '2024']::TEXT[], 'Easy'),
  (254, 'English Grammar & Vocabulary', 'English', 'MPSC State Services (Rajyaseva)', 2014, 'Choose the correct synonym for "TENACIOUS":', '{"A":"Persistent / Determined","B":"Timid","C":"Weak","D":"Cautious"}'::JSONB, 'A', '"Tenacious" means holding fast, persistent, stubborn or resolute.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'MPSC', '2014']::TEXT[], 'Medium'),
  (255, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Police Constable Bharti', 2015, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2015']::TEXT[], 'Hard'),
  (256, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2016, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2016']::TEXT[], 'Easy'),
  (257, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'Maharashtra Vanrakshak (Forest) Bharti', 2017, 'संसदेच्या दोन्ही सभागृहांचे संयुक्त अधिवेशन (Joint Sitting) कोण बोलावतात?', '{"A":"भारताचे राष्ट्रपती","B":"लोकसभा अध्यक्ष","C":"उपराष्ट्रपती","D":"पंतप्रधान"}'::JSONB, 'A', 'कलम 108 नुसार राष्ट्रपती संयुक्त अधिवेशन बोलावतात; परंतु त्याचे अध्यक्षस्थान नेहमी लोकसभेचे अध्यक्ष (Speaker) भूषवितात.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'Maharashtra', '2017']::TEXT[], 'Medium'),
  (258, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'SSC CGL & CHSL', 2018, 'संयुक्त महाराष्ट्र समितीची स्थापना 6 फेब्रुवारी 1956 रोजी कोठे झाली आणि तिचे अध्यक्ष कोण होते?', '{"A":"पुणे, भाई माधवराव बागल","B":"मुंबई, एस. एम. जोशी","C":"नागपूर, प्र. के. अत्रे","D":"कोल्हापूर, श्रीपाद डांगे"}'::JSONB, 'A', '6 फेब्रुवारी 1956 रोजी पुण्यात संयुक्त महाराष्ट्र समिती स्थापन झाली. भाई माधवराव बागल अध्यक्ष व एस. एम. जोशी सरचिटणीस होते.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'SSC', '2018']::TEXT[], 'Hard'),
  (259, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'IBPS / State Cooperative Bank', 2019, 'भीमा नदीचा उगम पुणे जिल्ह्यातील कोणत्या ज्योतिर्लिंगाजवळ होतो?', '{"A":"भीमाशंकर","B":"त्र्यंबकेश्वर","C":"घृष्णेश्वर","D":"परळी वैजनाथ"}'::JSONB, 'A', 'भीमा नदीचा उगम सह्याद्री पर्वतात भीमाशंकर येथे होतो. भीमा नदी पंढरपूर येथे चंद्रभागा म्हणून ओळखली जाते व पुढे कर्नाटकात कृष्णा नदीस मिळते.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'IBPS', '2019']::TEXT[], 'Easy'),
