VALUES
  (301, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'IBPS / State Cooperative Bank', 2017, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'IBPS', '2017']::TEXT[], 'Easy'),
  (302, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'MPSC Combined Group B & C', 2018, 'भारताचे नियंत्रक व महालेखापरीक्षक (CAG) यांची नियुक्ती कोणत्या कलमान्वये होते?', '{"A":"कलम 148","B":"कलम 280","C":"कलम 324","D":"कलम 76"}'::JSONB, 'A', 'कलम 148 नुसार राष्ट्रपती CAG ची नियुक्ती करतात. CAG हे सार्वजनिक वित्ताचे संरक्षक असतात (Guardian of Public Purse).', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'MPSC', '2018']::TEXT[], 'Medium'),
  (303, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'MPSC State Services (Rajyaseva)', 2019, 'लोकमान्य बाळ गंगाधर टिळकांनी 1916 मध्ये बेळगाव येथे कोणती चळवळ सुरू केली?', '{"A":"होमरूल लीग चळवळ (Home Rule League)","B":"असहकार आंदोलन","C":"भारत छोडो","D":"सविनय कायदेभंग"}'::JSONB, 'A', 'एप्रिल 1916 मध्ये बेळगाव येथे टिळकांनी होमरूल लीगची स्थापना केली आणि "स्वराज्य हा माझा जन्मसिद्ध हक्क आहे आणि तो मी मिळवणारच" ही सिंहगर्जना केली.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'MPSC', '2019']::TEXT[], 'Hard'),
  (304, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'Maharashtra Police Constable Bharti', 2020, 'महाराष्ट्रातील दगडी कोळशाचे सर्वात प्रसिद्ध क्षेत्र "बल्लारपूर" कोणत्या जिल्ह्यात आहे?', '{"A":"चंद्रपूर","B":"नागपूर","C":"यवतमाळ","D":"भंडारा"}'::JSONB, 'A', 'चंद्रपूर आणि नागपूर जिल्ह्यात विदर्भामध्ये दगडी कोळशाच्या खाणी आहेत. वर्धा-वैणगंगा खोऱ्यात बल्लारपूर हे कोळशाचे मोठे केंद्र आहे.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'Maharashtra', '2020']::TEXT[], 'Easy'),
  (305, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2021, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2021']::TEXT[], 'Medium'),
  (306, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'Maharashtra Vanrakshak (Forest) Bharti', 2022, 'पेशीचे "ऊर्जा केंद्र" (Powerhouse of the Cell) कोणाला म्हणतात?', '{"A":"तंतुकणिका (Mitochondria)","B":"रायबोझोम","C":"लायसोझोम","D":"हरितलवके"}'::JSONB, 'A', 'तंतुकणिकेत (Mitochondria) पेशीय श्वसनातून ATP (Adenosine Triphosphate) च्या स्वरूपात ऊर्जा तयार होते, म्हणून त्यास पेशीचे ऊर्जा केंद्र म्हणतात.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'Maharashtra', '2022']::TEXT[], 'Hard'),
  (307, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'SSC CGL & CHSL', 2023, '"अन्नास जागणे" या वाक्प्रचाराचा अचूक अर्थ काय?', '{"A":"उपकाराची जाणीव ठेवणे (कृतज्ञ राहणे)","B":"अन्न वाया घालवणे","C":"रात्रभर जागत राहणे","D":"जेवणावर ताव मारणे"}'::JSONB, 'A', 'अन्नास जागणे म्हणजे केलेल्या उपकारांची सदैव जाणीव ठेवणे (कृतज्ञ असणे). याचा विरुद्धार्थी वाक्प्रचार "अन्नास कापणे" (कृतघ्न असणे) हा आहे.', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'SSC', '2023']::TEXT[], 'Easy'),
  (308, 'English Grammar & Vocabulary', 'English', 'IBPS / State Cooperative Bank', 2024, 'Fill in the blank with appropriate preposition: "She is proficient _____ speaking Marathi and English."', '{"A":"in","B":"at","C":"with","D":"for"}'::JSONB, 'A', 'The adjective "proficient" is followed by the preposition "in" (e.g. proficient in a language or subject).', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'IBPS', '2024']::TEXT[], 'Medium'),
  (309, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'MPSC Combined Group B & C', 2014, 'जर 5 माणसे एक काम 10 दिवसांत करतात, तर 2 माणसे तेच काम किती दिवसांत करतील?', '{"A":"25 दिवस","B":"20 दिवस","C":"15 दिवस","D":"30 दिवस"}'::JSONB, 'A', 'माणसे x दिवस = स्थिरांक. 5 x 10 = 50 मॅन-डेज. 50 / 2 = 25 दिवस.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'MPSC', '2014']::TEXT[], 'Hard'),
  (310, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC State Services (Rajyaseva)', 2015, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2015']::TEXT[], 'Easy'),
  (311, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'Maharashtra Police Constable Bharti', 2016, 'भारताचे राष्ट्रपती होण्यासाठी किमान वय किती वर्षे पूर्ण असावे लागते?', '{"A":"35 वर्षे","B":"30 वर्षे","C":"25 वर्षे","D":"21 वर्षे"}'::JSONB, 'A', 'राष्ट्रपती व राज्यपालांसाठी किमान वय 35 वर्षे, राज्यसभेसाठी 30 वर्षे, लोकसभेसाठी 25 वर्षे आणि ग्रामपंचायतीसाठी 21 वर्षे आवश्यक आहे.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'Maharashtra', '2016']::TEXT[], 'Medium'),
  (312, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2017, '1942 च्या चले जाव आंदोलनात सातारा येथे "प्रतिसरकार" (Patri Sarkar) ची स्थापना कोणी केली?', '{"A":"क्रांतिसिंह नाना पाटील","B":"सेनापती बापट","C":"किसन वीर","D":"वसंतदादा पाटील"}'::JSONB, 'A', 'क्रांतिसिंह नाना पाटील यांनी साताऱ्यात प्रतिसरकार स्थापन करून समांतर न्याय व प्रशासकीय व्यवस्था उभारली, ज्यास "पत्री सरकार" म्हटले जायचे.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'Maharashtra', '2017']::TEXT[], 'Hard'),
  (313, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'Maharashtra Vanrakshak (Forest) Bharti', 2018, 'अ‍ॅल्युमिनियम बनवण्यासाठी वापरले जाणारे "बॉक्साईट" हे खनिज महाराष्ट्रात प्रामुख्याने कोणत्या जिल्ह्यात आढळते?', '{"A":"कोल्हापूर व रत्नागिरी","B":"नागपूर व भंडारा","C":"चंद्रपूर व यवतमाळ","D":"नाशिक व जळगाव"}'::JSONB, 'A', 'बॉक्साईट हे जांभा खडकाच्या भागात आढळते. कोल्हापूर, रत्नागिरी, सिंधुदुर्ग आणि रायगड जिल्ह्यात बॉक्साईटचे मोठे साठे आहेत.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'Maharashtra', '2018']::TEXT[], 'Easy'),
  (314, 'बँकिंग, वित्त व महागाई', 'Economy', 'SSC CGL & CHSL', 2019, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'SSC', '2019']::TEXT[], 'Medium'),
  (315, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'IBPS / State Cooperative Bank', 2020, 'पेनिसिलिन या पहिल्या प्रतिजैविकाचा (Antibiotic) शोध कोणी लावला?', '{"A":"अलेक्झांडर फ्लेमिंग","B":"एडवर्ड जेनर","C":"लुई पाश्चर","D":"रॉबर्ट कॉक"}'::JSONB, 'A', '1928 मध्ये अलेक्झांडर फ्लेमिंग यांनी पेनिसिलियम नोटॅटम या बुरशीपासून जगातील पहिले अँटिबायोटिक पेनिसिलिन शोधले.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'IBPS', '2020']::TEXT[], 'Hard'),
