  (392, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'IBPS / State Cooperative Bank', 2020, 'भारताचे नियंत्रक व महालेखापरीक्षक (CAG) यांची नियुक्ती कोणत्या कलमान्वये होते?', '{"A":"कलम 148","B":"कलम 280","C":"कलम 324","D":"कलम 76"}'::JSONB, 'A', 'कलम 148 नुसार राष्ट्रपती CAG ची नियुक्ती करतात. CAG हे सार्वजनिक वित्ताचे संरक्षक असतात (Guardian of Public Purse).', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'IBPS', '2020']::TEXT[], 'Medium'),
  (393, 'महाराष्ट्रातील समाजसुधारक', 'History', 'MPSC Combined Group B & C', 2021, 'गोपाळ गणेश आगरकर यांनी लोकमान्य टिळकांपासून वेगळे झाल्यानंतर कोणते वृत्तपत्र सुरू केले?', '{"A":"सुधारक (1888)","B":"केसरी","C":"मराठा","D":"ज्ञानप्रकाश"}'::JSONB, 'A', 'आगरकरांनी राजकीय सुधारणांपेक्षा सामाजिक सुधारणांना प्राधान्य दिले आणि 1888 मध्ये "सुधारक" हे विचारप्रधान वृत्तपत्र सुरू केले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'MPSC', '2021']::TEXT[], 'Hard'),
  (394, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'MPSC State Services (Rajyaseva)', 2022, 'महाराष्ट्रात सर्वाधिक पर्जन्य पडणारे ठिकाण "आंबोली" कोणत्या जिल्ह्यात आहे?', '{"A":"सिंधुदुर्ग","B":"रत्नागिरी","C":"सातारा","D":"कोल्हापूर"}'::JSONB, 'A', 'सिंधुदुर्ग जिल्ह्यातील सावंतवाडी तालुक्यातील आंबोली येथे महाराष्ट्रात सर्वाधिक (सुमारे 750 सेमी) पाऊस पडतो, म्हणून त्यास "महाराष्ट्राचे चेरापुंजी" म्हणतात.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'MPSC', '2022']::TEXT[], 'Easy'),
  (395, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Police Constable Bharti', 2023, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2023']::TEXT[], 'Medium'),
  (396, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2024, 'पेशीचे "ऊर्जा केंद्र" (Powerhouse of the Cell) कोणाला म्हणतात?', '{"A":"तंतुकणिका (Mitochondria)","B":"रायबोझोम","C":"लायसोझोम","D":"हरितलवके"}'::JSONB, 'A', 'तंतुकणिकेत (Mitochondria) पेशीय श्वसनातून ATP (Adenosine Triphosphate) च्या स्वरूपात ऊर्जा तयार होते, म्हणून त्यास पेशीचे ऊर्जा केंद्र म्हणतात.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'Maharashtra', '2024']::TEXT[], 'Hard'),
  (397, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'Maharashtra Vanrakshak (Forest) Bharti', 2014, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'Maharashtra', '2014']::TEXT[], 'Easy'),
  (398, 'English Grammar & Vocabulary', 'English', 'SSC CGL & CHSL', 2015, 'Identify the meaning of idiom: "A blessing in disguise"', '{"A":"Something good that isn''t recognized at first","B":"A holy prayer","C":"A fake curse","D":"A sudden disaster"}'::JSONB, 'A', '"A blessing in disguise" means an apparent misfortune that eventually results in something unexpectedly good.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'SSC', '2015']::TEXT[], 'Medium'),
  (399, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'IBPS / State Cooperative Bank', 2016, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'IBPS', '2016']::TEXT[], 'Hard'),
  (400, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC Combined Group B & C', 2017, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2017']::TEXT[], 'Easy')
