  (588, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'IBPS / State Cooperative Bank', 2018, 'पुढील संख्यामालिकेतील प्रश्नचिन्हाच्या जागी काय येईल: 2, 6, 12, 20, 30, ?', '{"A":"42","B":"40","C":"44","D":"36"}'::JSONB, 'A', 'फरक: +4, +6, +8, +10, +12. म्हणून 30 + 12 = 42. (किंवा n^2 + n: 1^2+1=2, 2^2+2=6, 3^2+3=12, 4^2+4=20, 5^2+5=30, 6^2+6=42).', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'IBPS', '2018']::TEXT[], 'Hard'),
  (589, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC Combined Group B & C', 2019, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2019']::TEXT[], 'Easy'),
  (590, 'राज्यघटना निर्मिती व सरनामा', 'Polity', 'MPSC State Services (Rajyaseva)', 2020, 'भारतीय संविधानात एकूण किती अनुसूच्या (Schedules) सध्या अस्तित्वात आहेत?', '{"A":"12 अनुसूच्या","B":"8 अनुसूच्या","C":"10 अनुसूच्या","D":"14 अनुसूच्या"}'::JSONB, 'A', 'मूळ घटनेत 8 अनुसूच्या होत्या. सध्या भारतीय संविधानात 12 अनुसूच्या आहेत.', ARRAY['संविधान', 'सरनामा', 'Preamble', 'संविधान सभा', 'MPSC', '2020']::TEXT[], 'Medium'),
  (591, 'महाराष्ट्रातील समाजसुधारक', 'History', 'Maharashtra Police Constable Bharti', 2021, 'महर्षी धोंडो केशव कर्वे यांनी 1916 मध्ये पुण्यात कोणत्या पहिल्या महिला विद्यापीठाची स्थापना केली?', '{"A":"SNDT महिला विद्यापीठ","B":"सावित्रीबाई फुले विद्यापीठ","C":"टिळक महाराष्ट्र विद्यापीठ","D":"मुंबई विद्यापीठ"}'::JSONB, 'A', 'महर्षी कर्व्यांनी 1916 मध्ये हिंगणे (पुणे) येथे जपानच्या धर्तीवर स्वतंत्र महिला विद्यापीठ सुरू केले, ज्यास सर विठ्ठलदास ठाकरसी यांच्या मातोश्री नाथीबाई यांच्या स्मरणार्थ SNDT नाव दिले गेले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'Maharashtra', '2021']::TEXT[], 'Hard'),
  (592, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2022, 'भीमा नदीचा उगम पुणे जिल्ह्यातील कोणत्या ज्योतिर्लिंगाजवळ होतो?', '{"A":"भीमाशंकर","B":"त्र्यंबकेश्वर","C":"घृष्णेश्वर","D":"परळी वैजनाथ"}'::JSONB, 'A', 'भीमा नदीचा उगम सह्याद्री पर्वतात भीमाशंकर येथे होतो. भीमा नदी पंढरपूर येथे चंद्रभागा म्हणून ओळखली जाते व पुढे कर्नाटकात कृष्णा नदीस मिळते.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'Maharashtra', '2022']::TEXT[], 'Easy'),
  (593, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Vanrakshak (Forest) Bharti', 2023, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2023']::TEXT[], 'Medium'),
  (594, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'SSC CGL & CHSL', 2024, 'मानवी शरीरातील सर्वात मोठी ग्रंथी (Largest Gland) कोणती?', '{"A":"यकृत (Liver)","B":"स्वादुपिंड (Pancreas)","C":"थायरॉईड ग्रंथी","D":"जठर"}'::JSONB, 'A', 'यकृत ही मानवी शरीरातील सर्वात मोठी ग्रंथी (वजन सुमारे 1.5 किलो) असून ती पित्तरस (Bile juice) तयार करते.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'SSC', '2024']::TEXT[], 'Hard'),
  (595, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'IBPS / State Cooperative Bank', 2014, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'IBPS', '2014']::TEXT[], 'Easy'),
  (596, 'English Grammar & Vocabulary', 'English', 'MPSC Combined Group B & C', 2015, 'Identify the meaning of idiom: "A blessing in disguise"', '{"A":"Something good that isn''t recognized at first","B":"A holy prayer","C":"A fake curse","D":"A sudden disaster"}'::JSONB, 'A', '"A blessing in disguise" means an apparent misfortune that eventually results in something unexpectedly good.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'MPSC', '2015']::TEXT[], 'Medium'),
  (597, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'MPSC State Services (Rajyaseva)', 2016, 'पुढील संख्यामालिकेतील प्रश्नचिन्हाच्या जागी काय येईल: 2, 6, 12, 20, 30, ?', '{"A":"42","B":"40","C":"44","D":"36"}'::JSONB, 'A', 'फरक: +4, +6, +8, +10, +12. म्हणून 30 + 12 = 42. (किंवा n^2 + n: 1^2+1=2, 2^2+2=6, 3^2+3=12, 4^2+4=20, 5^2+5=30, 6^2+6=42).', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'MPSC', '2016']::TEXT[], 'Hard'),
  (598, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Police Constable Bharti', 2017, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2017']::TEXT[], 'Easy'),
  (599, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2018, 'भारताचे नियंत्रक व महालेखापरीक्षक (CAG) यांची नियुक्ती कोणत्या कलमान्वये होते?', '{"A":"कलम 148","B":"कलम 280","C":"कलम 324","D":"कलम 76"}'::JSONB, 'A', 'कलम 148 नुसार राष्ट्रपती CAG ची नियुक्ती करतात. CAG हे सार्वजनिक वित्ताचे संरक्षक असतात (Guardian of Public Purse).', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'Maharashtra', '2018']::TEXT[], 'Medium'),
  (600, 'महाराष्ट्रातील समाजसुधारक', 'History', 'Maharashtra Vanrakshak (Forest) Bharti', 2019, 'गोपाळ गणेश आगरकर यांनी लोकमान्य टिळकांपासून वेगळे झाल्यानंतर कोणते वृत्तपत्र सुरू केले?', '{"A":"सुधारक (1888)","B":"केसरी","C":"मराठा","D":"ज्ञानप्रकाश"}'::JSONB, 'A', 'आगरकरांनी राजकीय सुधारणांपेक्षा सामाजिक सुधारणांना प्राधान्य दिले आणि 1888 मध्ये "सुधारक" हे विचारप्रधान वृत्तपत्र सुरू केले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'Maharashtra', '2019']::TEXT[], 'Hard')
