VALUES
  (601, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'SSC CGL & CHSL', 2020, 'महाराष्ट्रातील दगडी कोळशाचे सर्वात प्रसिद्ध क्षेत्र "बल्लारपूर" कोणत्या जिल्ह्यात आहे?', '{"A":"चंद्रपूर","B":"नागपूर","C":"यवतमाळ","D":"भंडारा"}'::JSONB, 'A', 'चंद्रपूर आणि नागपूर जिल्ह्यात विदर्भामध्ये दगडी कोळशाच्या खाणी आहेत. वर्धा-वैणगंगा खोऱ्यात बल्लारपूर हे कोळशाचे मोठे केंद्र आहे.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'SSC', '2020']::TEXT[], 'Easy'),
  (602, 'बँकिंग, वित्त व महागाई', 'Economy', 'IBPS / State Cooperative Bank', 2021, 'भारतात कृषी आणि ग्रामीण विकासासाठी पतपुरवठा करणारी शिखर संस्था कोणती?', '{"A":"नाबार्ड (NABARD)","B":"सिडबी (SIDBI)","C":"आयडीबीआय (IDBI)","D":"सेबी (SEBI)"}'::JSONB, 'A', 'शिवरामन समितीच्या शिफारशीवरून 12 जुलै 1982 रोजी NABARD (National Bank for Agriculture and Rural Development) ची स्थापना झाली.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'IBPS', '2021']::TEXT[], 'Medium'),
  (603, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'MPSC Combined Group B & C', 2022, 'मानवी शरीरातील सर्वात मोठी ग्रंथी (Largest Gland) कोणती?', '{"A":"यकृत (Liver)","B":"स्वादुपिंड (Pancreas)","C":"थायरॉईड ग्रंथी","D":"जठर"}'::JSONB, 'A', 'यकृत ही मानवी शरीरातील सर्वात मोठी ग्रंथी (वजन सुमारे 1.5 किलो) असून ती पित्तरस (Bile juice) तयार करते.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'MPSC', '2022']::TEXT[], 'Hard'),
  (604, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'MPSC State Services (Rajyaseva)', 2023, '"अळंबी" या शब्दाचा समानार्थी शब्द खालीलपैकी कोणता?', '{"A":"मशरूम / छत्रक","B":"अडथळा","C":"आळस","D":"अंधार"}'::JSONB, 'A', 'अळंबी म्हणजे कुत्र्याची छत्री किंवा खाद्य वनस्पती (Mushroom / छत्रक).', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'MPSC', '2023']::TEXT[], 'Easy'),
  (605, 'English Grammar & Vocabulary', 'English', 'Maharashtra Police Constable Bharti', 2024, 'Choose the correct synonym for "TENACIOUS":', '{"A":"Persistent / Determined","B":"Timid","C":"Weak","D":"Cautious"}'::JSONB, 'A', '"Tenacious" means holding fast, persistent, stubborn or resolute.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2024']::TEXT[], 'Medium'),
  (606, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2014, 'पुढील संख्यामालिकेतील प्रश्नचिन्हाच्या जागी काय येईल: 2, 6, 12, 20, 30, ?', '{"A":"42","B":"40","C":"44","D":"36"}'::JSONB, 'A', 'फरक: +4, +6, +8, +10, +12. म्हणून 30 + 12 = 42. (किंवा n^2 + n: 1^2+1=2, 2^2+2=6, 3^2+3=12, 4^2+4=20, 5^2+5=30, 6^2+6=42).', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2014']::TEXT[], 'Hard'),
  (607, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Vanrakshak (Forest) Bharti', 2015, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2015']::TEXT[], 'Easy'),
  (608, 'राज्यघटना निर्मिती व सरनामा', 'Polity', 'SSC CGL & CHSL', 2016, 'भारतीय संविधानात "मार्गदर्शक तत्वे" (DPSP) कोणत्या देशाच्या घटनेवरून घेण्यात आली आहेत?', '{"A":"आयर्लंड (Ireland)","B":"अमेरिका","C":"ब्रिटन","D":"कॅनडा"}'::JSONB, 'A', 'मार्गदर्शक तत्वे (भाग IV) आयर्लंडच्या संविधानाकडून प्रेरित आहेत. मूलभूत हक्क अमेरिकेकडून, तर संसदीय शासनप्रणाली ब्रिटनकडून घेतली आहे.', ARRAY['संविधान', 'सरनामा', 'Preamble', 'संविधान सभा', 'SSC', '2016']::TEXT[], 'Medium'),
  (609, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'IBPS / State Cooperative Bank', 2017, 'संयुक्त महाराष्ट्र समितीची स्थापना 6 फेब्रुवारी 1956 रोजी कोठे झाली आणि तिचे अध्यक्ष कोण होते?', '{"A":"पुणे, भाई माधवराव बागल","B":"मुंबई, एस. एम. जोशी","C":"नागपूर, प्र. के. अत्रे","D":"कोल्हापूर, श्रीपाद डांगे"}'::JSONB, 'A', '6 फेब्रुवारी 1956 रोजी पुण्यात संयुक्त महाराष्ट्र समिती स्थापन झाली. भाई माधवराव बागल अध्यक्ष व एस. एम. जोशी सरचिटणीस होते.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'IBPS', '2017']::TEXT[], 'Hard'),
  (610, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'MPSC Combined Group B & C', 2018, 'अ‍ॅल्युमिनियम बनवण्यासाठी वापरले जाणारे "बॉक्साईट" हे खनिज महाराष्ट्रात प्रामुख्याने कोणत्या जिल्ह्यात आढळते?', '{"A":"कोल्हापूर व रत्नागिरी","B":"नागपूर व भंडारा","C":"चंद्रपूर व यवतमाळ","D":"नाशिक व जळगाव"}'::JSONB, 'A', 'बॉक्साईट हे जांभा खडकाच्या भागात आढळते. कोल्हापूर, रत्नागिरी, सिंधुदुर्ग आणि रायगड जिल्ह्यात बॉक्साईटचे मोठे साठे आहेत.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'MPSC', '2018']::TEXT[], 'Easy'),
  (611, 'बँकिंग, वित्त व महागाई', 'Economy', 'MPSC State Services (Rajyaseva)', 2019, 'भारतात कृषी आणि ग्रामीण विकासासाठी पतपुरवठा करणारी शिखर संस्था कोणती?', '{"A":"नाबार्ड (NABARD)","B":"सिडबी (SIDBI)","C":"आयडीबीआय (IDBI)","D":"सेबी (SEBI)"}'::JSONB, 'A', 'शिवरामन समितीच्या शिफारशीवरून 12 जुलै 1982 रोजी NABARD (National Bank for Agriculture and Rural Development) ची स्थापना झाली.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'MPSC', '2019']::TEXT[], 'Medium'),
  (612, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'Maharashtra Police Constable Bharti', 2020, 'शुद्ध पाण्याचे pH मूल्य किती असते?', '{"A":"7 (उदासीन)","B":"0","C":"14","D":"4"}'::JSONB, 'A', 'pH स्केलवर 7 म्हणजे उदासीन (उदा. शुद्ध पाणी). 7 पेक्षा कमी म्हणजे आम्लधर्मी (Acidic) आणि 7 पेक्षा जास्त म्हणजे आम्लारीधर्मी (Basic).', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'Maharashtra', '2020']::TEXT[], 'Hard'),
  (613, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2021, '"अळंबी" या शब्दाचा समानार्थी शब्द खालीलपैकी कोणता?', '{"A":"मशरूम / छत्रक","B":"अडथळा","C":"आळस","D":"अंधार"}'::JSONB, 'A', 'अळंबी म्हणजे कुत्र्याची छत्री किंवा खाद्य वनस्पती (Mushroom / छत्रक).', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'Maharashtra', '2021']::TEXT[], 'Easy'),
  (614, 'English Grammar & Vocabulary', 'English', 'Maharashtra Vanrakshak (Forest) Bharti', 2022, 'Fill in the blank with appropriate preposition: "She is proficient _____ speaking Marathi and English."', '{"A":"in","B":"at","C":"with","D":"for"}'::JSONB, 'A', 'The adjective "proficient" is followed by the preposition "in" (e.g. proficient in a language or subject).', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2022']::TEXT[], 'Medium'),
  (615, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'SSC CGL & CHSL', 2023, 'जर 5 माणसे एक काम 10 दिवसांत करतात, तर 2 माणसे तेच काम किती दिवसांत करतील?', '{"A":"25 दिवस","B":"20 दिवस","C":"15 दिवस","D":"30 दिवस"}'::JSONB, 'A', 'माणसे x दिवस = स्थिरांक. 5 x 10 = 50 मॅन-डेज. 50 / 2 = 25 दिवस.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'SSC', '2023']::TEXT[], 'Hard'),
  (616, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'IBPS / State Cooperative Bank', 2024, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'IBPS', '2024']::TEXT[], 'Easy'),
  (617, 'राज्यघटना निर्मिती व सरनामा', 'Polity', 'MPSC Combined Group B & C', 2014, 'भारतीय संविधानात एकूण किती अनुसूच्या (Schedules) सध्या अस्तित्वात आहेत?', '{"A":"12 अनुसूच्या","B":"8 अनुसूच्या","C":"10 अनुसूच्या","D":"14 अनुसूच्या"}'::JSONB, 'A', 'मूळ घटनेत 8 अनुसूच्या होत्या. सध्या भारतीय संविधानात 12 अनुसूच्या आहेत.', ARRAY['संविधान', 'सरनामा', 'Preamble', 'संविधान सभा', 'MPSC', '2014']::TEXT[], 'Medium'),
  (618, 'महाराष्ट्रातील समाजसुधारक', 'History', 'MPSC State Services (Rajyaseva)', 2015, 'महर्षी धोंडो केशव कर्वे यांनी 1916 मध्ये पुण्यात कोणत्या पहिल्या महिला विद्यापीठाची स्थापना केली?', '{"A":"SNDT महिला विद्यापीठ","B":"सावित्रीबाई फुले विद्यापीठ","C":"टिळक महाराष्ट्र विद्यापीठ","D":"मुंबई विद्यापीठ"}'::JSONB, 'A', 'महर्षी कर्व्यांनी 1916 मध्ये हिंगणे (पुणे) येथे जपानच्या धर्तीवर स्वतंत्र महिला विद्यापीठ सुरू केले, ज्यास सर विठ्ठलदास ठाकरसी यांच्या मातोश्री नाथीबाई यांच्या स्मरणार्थ SNDT नाव दिले गेले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'MPSC', '2015']::TEXT[], 'Hard'),
  (619, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'Maharashtra Police Constable Bharti', 2016, 'महाराष्ट्रातील दगडी कोळशाचे सर्वात प्रसिद्ध क्षेत्र "बल्लारपूर" कोणत्या जिल्ह्यात आहे?', '{"A":"चंद्रपूर","B":"नागपूर","C":"यवतमाळ","D":"भंडारा"}'::JSONB, 'A', 'चंद्रपूर आणि नागपूर जिल्ह्यात विदर्भामध्ये दगडी कोळशाच्या खाणी आहेत. वर्धा-वैणगंगा खोऱ्यात बल्लारपूर हे कोळशाचे मोठे केंद्र आहे.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'Maharashtra', '2016']::TEXT[], 'Easy'),
  (620, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2017, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2017']::TEXT[], 'Medium'),
  (621, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'Maharashtra Vanrakshak (Forest) Bharti', 2018, 'शुद्ध पाण्याचे pH मूल्य किती असते?', '{"A":"7 (उदासीन)","B":"0","C":"14","D":"4"}'::JSONB, 'A', 'pH स्केलवर 7 म्हणजे उदासीन (उदा. शुद्ध पाणी). 7 पेक्षा कमी म्हणजे आम्लधर्मी (Acidic) आणि 7 पेक्षा जास्त म्हणजे आम्लारीधर्मी (Basic).', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'Maharashtra', '2018']::TEXT[], 'Hard'),
  (622, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'SSC CGL & CHSL', 2019, '"अन्नास जागणे" या वाक्प्रचाराचा अचूक अर्थ काय?', '{"A":"उपकाराची जाणीव ठेवणे (कृतज्ञ राहणे)","B":"अन्न वाया घालवणे","C":"रात्रभर जागत राहणे","D":"जेवणावर ताव मारणे"}'::JSONB, 'A', 'अन्नास जागणे म्हणजे केलेल्या उपकारांची सदैव जाणीव ठेवणे (कृतज्ञ असणे). याचा विरुद्धार्थी वाक्प्रचार "अन्नास कापणे" (कृतघ्न असणे) हा आहे.', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'SSC', '2019']::TEXT[], 'Easy'),
