  (625, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC State Services (Rajyaseva)', 2022, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2022']::TEXT[], 'Easy'),
  (626, 'मूलभूत हक्क (Fundamental Rights)', 'Polity', 'Maharashtra Police Constable Bharti', 2023, 'कायद्यासमोर समानता (Equality before Law) कोणत्या कलमामध्ये दिली आहे?', '{"A":"कलम 14","B":"कलम 15","C":"कलम 16","D":"कलम 17"}'::JSONB, 'A', 'कलम 14 नुसार भारतातील कोणत्याही व्यक्तीस कायद्यापुढे समानता अथवा कायद्याचे समान संरक्षण नाकारले जाणार नाही.', ARRAY['मूलभूत हक्क', 'कलम १४', 'कलम १९', 'कलम २१', 'कलम ३२', 'Maharashtra', '2023']::TEXT[], 'Medium'),
