  (634, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2020, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2020']::TEXT[], 'Easy'),
  (635, 'मूलभूत हक्क (Fundamental Rights)', 'Polity', 'Maharashtra Vanrakshak (Forest) Bharti', 2021, 'खाजगीपणाचा हक्क (Right to Privacy) हा कोणत्या कलमांतर्गत मूलभूत हक्क ठरवण्यात आला?', '{"A":"कलम 21","B":"कलम 19","C":"कलम 14","D":"कलम 25"}'::JSONB, 'A', 'पुट्टस्वामी खटला (2017) मध्ये सर्वोच्च न्यायालयाच्या 9 न्यायाधीशांच्या खंडपीठाने खाजगीपणाचा हक्क हा कलम 21 मधील जगण्याच्या हक्काचा भाग मानला.', ARRAY['मूलभूत हक्क', 'कलम १४', 'कलम १९', 'कलम २१', 'कलम ३२', 'Maharashtra', '2021']::TEXT[], 'Medium'),
  (636, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'SSC CGL & CHSL', 2022, 'संयुक्त महाराष्ट्र समितीची स्थापना 6 फेब्रुवारी 1956 रोजी कोठे झाली आणि तिचे अध्यक्ष कोण होते?', '{"A":"पुणे, भाई माधवराव बागल","B":"मुंबई, एस. एम. जोशी","C":"नागपूर, प्र. के. अत्रे","D":"कोल्हापूर, श्रीपाद डांगे"}'::JSONB, 'A', '6 फेब्रुवारी 1956 रोजी पुण्यात संयुक्त महाराष्ट्र समिती स्थापन झाली. भाई माधवराव बागल अध्यक्ष व एस. एम. जोशी सरचिटणीस होते.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'SSC', '2022']::TEXT[], 'Hard'),
  (637, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'IBPS / State Cooperative Bank', 2023, 'महाराष्ट्रात सर्वाधिक पर्जन्य पडणारे ठिकाण "आंबोली" कोणत्या जिल्ह्यात आहे?', '{"A":"सिंधुदुर्ग","B":"रत्नागिरी","C":"सातारा","D":"कोल्हापूर"}'::JSONB, 'A', 'सिंधुदुर्ग जिल्ह्यातील सावंतवाडी तालुक्यातील आंबोली येथे महाराष्ट्रात सर्वाधिक (सुमारे 750 सेमी) पाऊस पडतो, म्हणून त्यास "महाराष्ट्राचे चेरापुंजी" म्हणतात.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'IBPS', '2023']::TEXT[], 'Easy'),
  (638, 'बँकिंग, वित्त व महागाई', 'Economy', 'MPSC Combined Group B & C', 2024, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'MPSC', '2024']::TEXT[], 'Medium'),
  (639, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'MPSC State Services (Rajyaseva)', 2014, 'पेनिसिलिन या पहिल्या प्रतिजैविकाचा (Antibiotic) शोध कोणी लावला?', '{"A":"अलेक्झांडर फ्लेमिंग","B":"एडवर्ड जेनर","C":"लुई पाश्चर","D":"रॉबर्ट कॉक"}'::JSONB, 'A', '1928 मध्ये अलेक्झांडर फ्लेमिंग यांनी पेनिसिलियम नोटॅटम या बुरशीपासून जगातील पहिले अँटिबायोटिक पेनिसिलिन शोधले.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'MPSC', '2014']::TEXT[], 'Hard'),
  (640, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'Maharashtra Police Constable Bharti', 2015, '"अन्नास जागणे" या वाक्प्रचाराचा अचूक अर्थ काय?', '{"A":"उपकाराची जाणीव ठेवणे (कृतज्ञ राहणे)","B":"अन्न वाया घालवणे","C":"रात्रभर जागत राहणे","D":"जेवणावर ताव मारणे"}'::JSONB, 'A', 'अन्नास जागणे म्हणजे केलेल्या उपकारांची सदैव जाणीव ठेवणे (कृतज्ञ असणे). याचा विरुद्धार्थी वाक्प्रचार "अन्नास कापणे" (कृतघ्न असणे) हा आहे.', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'Maharashtra', '2015']::TEXT[], 'Easy'),
  (641, 'English Grammar & Vocabulary', 'English', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2016, 'Choose the correct synonym for "TENACIOUS":', '{"A":"Persistent / Determined","B":"Timid","C":"Weak","D":"Cautious"}'::JSONB, 'A', '"Tenacious" means holding fast, persistent, stubborn or resolute.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2016']::TEXT[], 'Medium'),
  (642, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Vanrakshak (Forest) Bharti', 2017, 'पुढील संख्यामालिकेतील प्रश्नचिन्हाच्या जागी काय येईल: 2, 6, 12, 20, 30, ?', '{"A":"42","B":"40","C":"44","D":"36"}'::JSONB, 'A', 'फरक: +4, +6, +8, +10, +12. म्हणून 30 + 12 = 42. (किंवा n^2 + n: 1^2+1=2, 2^2+2=6, 3^2+3=12, 4^2+4=20, 5^2+5=30, 6^2+6=42).', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2017']::TEXT[], 'Hard'),
  (643, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'SSC CGL & CHSL', 2018, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'SSC', '2018']::TEXT[], 'Easy'),
  (644, 'मूलभूत हक्क (Fundamental Rights)', 'Polity', 'IBPS / State Cooperative Bank', 2019, 'कायद्यासमोर समानता (Equality before Law) कोणत्या कलमामध्ये दिली आहे?', '{"A":"कलम 14","B":"कलम 15","C":"कलम 16","D":"कलम 17"}'::JSONB, 'A', 'कलम 14 नुसार भारतातील कोणत्याही व्यक्तीस कायद्यापुढे समानता अथवा कायद्याचे समान संरक्षण नाकारले जाणार नाही.', ARRAY['मूलभूत हक्क', 'कलम १४', 'कलम १९', 'कलम २१', 'कलम ३२', 'IBPS', '2019']::TEXT[], 'Medium'),
  (645, 'महाराष्ट्रातील समाजसुधारक', 'History', 'MPSC Combined Group B & C', 2020, 'डिप्रेस्ड क्लासेस मिशन (Depressed Classes Mission) ची स्थापना 1906 मध्ये कोणी केली?', '{"A":"महर्षी विठ्ठल रामजी शिंदे","B":"डॉ. बाबासाहेब आंबेडकर","C":"छत्रपती शाहू महाराज","D":"महात्मा फुले"}'::JSONB, 'A', '18 ऑक्टोबर 1906 रोजी मुंबईत महर्षी विठ्ठल रामजी शिंदे यांनी अस्पृश्यांच्या उद्धारासाठी डिप्रेस्ड क्लासेस मिशनची स्थापना केली.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'MPSC', '2020']::TEXT[], 'Hard'),
  (646, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'MPSC State Services (Rajyaseva)', 2021, 'महाराष्ट्रातील तापी नदी कोणत्या दिशेने वाहते?', '{"A":"पश्चिम वाहिनी","B":"पूर्व वाहिनी","C":"दक्षिण वाहिनी","D":"उत्तर वाहिनी"}'::JSONB, 'A', 'तापी आणि नर्मदा या महाराष्ट्रातील प्रमुख पश्चिम वाहिनी नद्या आहेत, ज्या खचदरीतून वाहत जाऊन अरबी समुद्रास (खंबायतचे आखात) मिळतात.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'MPSC', '2021']::TEXT[], 'Easy'),
  (647, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Police Constable Bharti', 2022, 'भारतात कृषी आणि ग्रामीण विकासासाठी पतपुरवठा करणारी शिखर संस्था कोणती?', '{"A":"नाबार्ड (NABARD)","B":"सिडबी (SIDBI)","C":"आयडीबीआय (IDBI)","D":"सेबी (SEBI)"}'::JSONB, 'A', 'शिवरामन समितीच्या शिफारशीवरून 12 जुलै 1982 रोजी NABARD (National Bank for Agriculture and Rural Development) ची स्थापना झाली.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2022']::TEXT[], 'Medium'),
  (648, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2023, 'शुद्ध पाण्याचे pH मूल्य किती असते?', '{"A":"7 (उदासीन)","B":"0","C":"14","D":"4"}'::JSONB, 'A', 'pH स्केलवर 7 म्हणजे उदासीन (उदा. शुद्ध पाणी). 7 पेक्षा कमी म्हणजे आम्लधर्मी (Acidic) आणि 7 पेक्षा जास्त म्हणजे आम्लारीधर्मी (Basic).', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'Maharashtra', '2023']::TEXT[], 'Hard'),
  (649, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'Maharashtra Vanrakshak (Forest) Bharti', 2024, '"अन्नास जागणे" या वाक्प्रचाराचा अचूक अर्थ काय?', '{"A":"उपकाराची जाणीव ठेवणे (कृतज्ञ राहणे)","B":"अन्न वाया घालवणे","C":"रात्रभर जागत राहणे","D":"जेवणावर ताव मारणे"}'::JSONB, 'A', 'अन्नास जागणे म्हणजे केलेल्या उपकारांची सदैव जाणीव ठेवणे (कृतज्ञ असणे). याचा विरुद्धार्थी वाक्प्रचार "अन्नास कापणे" (कृतघ्न असणे) हा आहे.', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'Maharashtra', '2024']::TEXT[], 'Easy'),
  (650, 'English Grammar & Vocabulary', 'English', 'SSC CGL & CHSL', 2014, 'Identify the meaning of idiom: "A blessing in disguise"', '{"A":"Something good that isn''t recognized at first","B":"A holy prayer","C":"A fake curse","D":"A sudden disaster"}'::JSONB, 'A', '"A blessing in disguise" means an apparent misfortune that eventually results in something unexpectedly good.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'SSC', '2014']::TEXT[], 'Medium')
INSERT INTO pyq_questions (id, topic, subject, exam, year, question, options, correct, explanation, tags, difficulty)
VALUES
  (651, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'IBPS / State Cooperative Bank', 2015, 'जर 5 माणसे एक काम 10 दिवसांत करतात, तर 2 माणसे तेच काम किती दिवसांत करतील?', '{"A":"25 दिवस","B":"20 दिवस","C":"15 दिवस","D":"30 दिवस"}'::JSONB, 'A', 'माणसे x दिवस = स्थिरांक. 5 x 10 = 50 मॅन-डेज. 50 / 2 = 25 दिवस.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'IBPS', '2015']::TEXT[], 'Hard'),
  (652, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC Combined Group B & C', 2016, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2016']::TEXT[], 'Easy'),
  (653, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'MPSC State Services (Rajyaseva)', 2017, 'भारताचे राष्ट्रपती होण्यासाठी किमान वय किती वर्षे पूर्ण असावे लागते?', '{"A":"35 वर्षे","B":"30 वर्षे","C":"25 वर्षे","D":"21 वर्षे"}'::JSONB, 'A', 'राष्ट्रपती व राज्यपालांसाठी किमान वय 35 वर्षे, राज्यसभेसाठी 30 वर्षे, लोकसभेसाठी 25 वर्षे आणि ग्रामपंचायतीसाठी 21 वर्षे आवश्यक आहे.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'MPSC', '2017']::TEXT[], 'Medium'),
  (654, 'महाराष्ट्रातील समाजसुधारक', 'History', 'Maharashtra Police Constable Bharti', 2018, 'महर्षी धोंडो केशव कर्वे यांनी 1916 मध्ये पुण्यात कोणत्या पहिल्या महिला विद्यापीठाची स्थापना केली?', '{"A":"SNDT महिला विद्यापीठ","B":"सावित्रीबाई फुले विद्यापीठ","C":"टिळक महाराष्ट्र विद्यापीठ","D":"मुंबई विद्यापीठ"}'::JSONB, 'A', 'महर्षी कर्व्यांनी 1916 मध्ये हिंगणे (पुणे) येथे जपानच्या धर्तीवर स्वतंत्र महिला विद्यापीठ सुरू केले, ज्यास सर विठ्ठलदास ठाकरसी यांच्या मातोश्री नाथीबाई यांच्या स्मरणार्थ SNDT नाव दिले गेले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'Maharashtra', '2018']::TEXT[], 'Hard'),
  (655, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2019, 'अ‍ॅल्युमिनियम बनवण्यासाठी वापरले जाणारे "बॉक्साईट" हे खनिज महाराष्ट्रात प्रामुख्याने कोणत्या जिल्ह्यात आढळते?', '{"A":"कोल्हापूर व रत्नागिरी","B":"नागपूर व भंडारा","C":"चंद्रपूर व यवतमाळ","D":"नाशिक व जळगाव"}'::JSONB, 'A', 'बॉक्साईट हे जांभा खडकाच्या भागात आढळते. कोल्हापूर, रत्नागिरी, सिंधुदुर्ग आणि रायगड जिल्ह्यात बॉक्साईटचे मोठे साठे आहेत.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'Maharashtra', '2019']::TEXT[], 'Easy'),
  (656, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Vanrakshak (Forest) Bharti', 2020, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2020']::TEXT[], 'Medium'),
  (657, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'SSC CGL & CHSL', 2021, 'पेशीचे "ऊर्जा केंद्र" (Powerhouse of the Cell) कोणाला म्हणतात?', '{"A":"तंतुकणिका (Mitochondria)","B":"रायबोझोम","C":"लायसोझोम","D":"हरितलवके"}'::JSONB, 'A', 'तंतुकणिकेत (Mitochondria) पेशीय श्वसनातून ATP (Adenosine Triphosphate) च्या स्वरूपात ऊर्जा तयार होते, म्हणून त्यास पेशीचे ऊर्जा केंद्र म्हणतात.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'SSC', '2021']::TEXT[], 'Hard'),
  (658, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'IBPS / State Cooperative Bank', 2022, 'मराठी वर्णमालेत एकूण किती मूळ स्वर मानले जातात?', '{"A":"12 स्वर (+ 2 इंग्रजी स्वर = 14)","B":"10 स्वर","C":"16 स्वर","D":"8 स्वर"}'::JSONB, 'A', 'पारंपरिक वर्णमालेत 12 स्वर होते. महाराष्ट्र शासनाच्या 2009 च्या जीआरनुसार ॲ आणि ऑ मिळून एकूण 14 स्वर आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'IBPS', '2022']::TEXT[], 'Easy'),
  (659, 'English Grammar & Vocabulary', 'English', 'MPSC Combined Group B & C', 2023, 'Fill in the blank with appropriate preposition: "She is proficient _____ speaking Marathi and English."', '{"A":"in","B":"at","C":"with","D":"for"}'::JSONB, 'A', 'The adjective "proficient" is followed by the preposition "in" (e.g. proficient in a language or subject).', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'MPSC', '2023']::TEXT[], 'Medium'),
  (660, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'MPSC State Services (Rajyaseva)', 2024, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'MPSC', '2024']::TEXT[], 'Hard'),
  (661, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Police Constable Bharti', 2014, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2014']::TEXT[], 'Easy'),
  (662, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2015, 'भारताचे राष्ट्रपती होण्यासाठी किमान वय किती वर्षे पूर्ण असावे लागते?', '{"A":"35 वर्षे","B":"30 वर्षे","C":"25 वर्षे","D":"21 वर्षे"}'::JSONB, 'A', 'राष्ट्रपती व राज्यपालांसाठी किमान वय 35 वर्षे, राज्यसभेसाठी 30 वर्षे, लोकसभेसाठी 25 वर्षे आणि ग्रामपंचायतीसाठी 21 वर्षे आवश्यक आहे.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'Maharashtra', '2015']::TEXT[], 'Medium'),
  (663, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'Maharashtra Vanrakshak (Forest) Bharti', 2016, '1942 च्या चले जाव आंदोलनात सातारा येथे "प्रतिसरकार" (Patri Sarkar) ची स्थापना कोणी केली?', '{"A":"क्रांतिसिंह नाना पाटील","B":"सेनापती बापट","C":"किसन वीर","D":"वसंतदादा पाटील"}'::JSONB, 'A', 'क्रांतिसिंह नाना पाटील यांनी साताऱ्यात प्रतिसरकार स्थापन करून समांतर न्याय व प्रशासकीय व्यवस्था उभारली, ज्यास "पत्री सरकार" म्हटले जायचे.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'Maharashtra', '2016']::TEXT[], 'Hard'),
  (664, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'SSC CGL & CHSL', 2017, 'महाराष्ट्रातील दगडी कोळशाचे सर्वात प्रसिद्ध क्षेत्र "बल्लारपूर" कोणत्या जिल्ह्यात आहे?', '{"A":"चंद्रपूर","B":"नागपूर","C":"यवतमाळ","D":"भंडारा"}'::JSONB, 'A', 'चंद्रपूर आणि नागपूर जिल्ह्यात विदर्भामध्ये दगडी कोळशाच्या खाणी आहेत. वर्धा-वैणगंगा खोऱ्यात बल्लारपूर हे कोळशाचे मोठे केंद्र आहे.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'SSC', '2017']::TEXT[], 'Easy'),
  (665, 'बँकिंग, वित्त व महागाई', 'Economy', 'IBPS / State Cooperative Bank', 2018, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'IBPS', '2018']::TEXT[], 'Medium'),
  (666, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'MPSC Combined Group B & C', 2019, 'पेनिसिलिन या पहिल्या प्रतिजैविकाचा (Antibiotic) शोध कोणी लावला?', '{"A":"अलेक्झांडर फ्लेमिंग","B":"एडवर्ड जेनर","C":"लुई पाश्चर","D":"रॉबर्ट कॉक"}'::JSONB, 'A', '1928 मध्ये अलेक्झांडर फ्लेमिंग यांनी पेनिसिलियम नोटॅटम या बुरशीपासून जगातील पहिले अँटिबायोटिक पेनिसिलिन शोधले.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'MPSC', '2019']::TEXT[], 'Hard'),
  (667, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'MPSC State Services (Rajyaseva)', 2020, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'MPSC', '2020']::TEXT[], 'Easy'),
  (668, 'English Grammar & Vocabulary', 'English', 'Maharashtra Police Constable Bharti', 2021, 'Choose the correct synonym for "TENACIOUS":', '{"A":"Persistent / Determined","B":"Timid","C":"Weak","D":"Cautious"}'::JSONB, 'A', '"Tenacious" means holding fast, persistent, stubborn or resolute.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2021']::TEXT[], 'Medium'),
  (669, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2022, 'जर 5 माणसे एक काम 10 दिवसांत करतात, तर 2 माणसे तेच काम किती दिवसांत करतील?', '{"A":"25 दिवस","B":"20 दिवस","C":"15 दिवस","D":"30 दिवस"}'::JSONB, 'A', 'माणसे x दिवस = स्थिरांक. 5 x 10 = 50 मॅन-डेज. 50 / 2 = 25 दिवस.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2022']::TEXT[], 'Hard'),
  (670, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Vanrakshak (Forest) Bharti', 2023, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2023']::TEXT[], 'Easy'),
  (671, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'SSC CGL & CHSL', 2024, 'संसदेच्या दोन्ही सभागृहांचे संयुक्त अधिवेशन (Joint Sitting) कोण बोलावतात?', '{"A":"भारताचे राष्ट्रपती","B":"लोकसभा अध्यक्ष","C":"उपराष्ट्रपती","D":"पंतप्रधान"}'::JSONB, 'A', 'कलम 108 नुसार राष्ट्रपती संयुक्त अधिवेशन बोलावतात; परंतु त्याचे अध्यक्षस्थान नेहमी लोकसभेचे अध्यक्ष (Speaker) भूषवितात.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'SSC', '2024']::TEXT[], 'Medium'),
  (672, 'महाराष्ट्रातील समाजसुधारक', 'History', 'IBPS / State Cooperative Bank', 2014, 'महर्षी धोंडो केशव कर्वे यांनी 1916 मध्ये पुण्यात कोणत्या पहिल्या महिला विद्यापीठाची स्थापना केली?', '{"A":"SNDT महिला विद्यापीठ","B":"सावित्रीबाई फुले विद्यापीठ","C":"टिळक महाराष्ट्र विद्यापीठ","D":"मुंबई विद्यापीठ"}'::JSONB, 'A', 'महर्षी कर्व्यांनी 1916 मध्ये हिंगणे (पुणे) येथे जपानच्या धर्तीवर स्वतंत्र महिला विद्यापीठ सुरू केले, ज्यास सर विठ्ठलदास ठाकरसी यांच्या मातोश्री नाथीबाई यांच्या स्मरणार्थ SNDT नाव दिले गेले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'IBPS', '2014']::TEXT[], 'Hard'),
  (673, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'MPSC Combined Group B & C', 2015, 'महाराष्ट्रात सर्वाधिक पर्जन्य पडणारे ठिकाण "आंबोली" कोणत्या जिल्ह्यात आहे?', '{"A":"सिंधुदुर्ग","B":"रत्नागिरी","C":"सातारा","D":"कोल्हापूर"}'::JSONB, 'A', 'सिंधुदुर्ग जिल्ह्यातील सावंतवाडी तालुक्यातील आंबोली येथे महाराष्ट्रात सर्वाधिक (सुमारे 750 सेमी) पाऊस पडतो, म्हणून त्यास "महाराष्ट्राचे चेरापुंजी" म्हणतात.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'MPSC', '2015']::TEXT[], 'Easy'),
  (674, 'बँकिंग, वित्त व महागाई', 'Economy', 'MPSC State Services (Rajyaseva)', 2016, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'MPSC', '2016']::TEXT[], 'Medium'),
  (675, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'Maharashtra Police Constable Bharti', 2017, 'शुद्ध पाण्याचे pH मूल्य किती असते?', '{"A":"7 (उदासीन)","B":"0","C":"14","D":"4"}'::JSONB, 'A', 'pH स्केलवर 7 म्हणजे उदासीन (उदा. शुद्ध पाणी). 7 पेक्षा कमी म्हणजे आम्लधर्मी (Acidic) आणि 7 पेक्षा जास्त म्हणजे आम्लारीधर्मी (Basic).', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'Maharashtra', '2017']::TEXT[], 'Hard'),
  (676, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2018, '"सूर्य + उदय = सूर्योदय" हा कोणत्या संधीचा प्रकार आहे?', '{"A":"स्वरसंधी (गुणादेश)","B":"व्यंजनसंधी","C":"विसर्गसंधी","D":"पूर्वरूप संधी"}'::JSONB, 'A', 'अ/आ च्या पुढे उ आल्यास दोघांबद्दल ओ होतो (गुणादेश), ही स्वरसंधीची उदाहरणे आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'Maharashtra', '2018']::TEXT[], 'Easy'),
  (677, 'English Grammar & Vocabulary', 'English', 'Maharashtra Vanrakshak (Forest) Bharti', 2019, 'Fill in the blank with appropriate preposition: "She is proficient _____ speaking Marathi and English."', '{"A":"in","B":"at","C":"with","D":"for"}'::JSONB, 'A', 'The adjective "proficient" is followed by the preposition "in" (e.g. proficient in a language or subject).', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2019']::TEXT[], 'Medium'),
  (678, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'SSC CGL & CHSL', 2020, 'पुढील संख्यामालिकेतील प्रश्नचिन्हाच्या जागी काय येईल: 2, 6, 12, 20, 30, ?', '{"A":"42","B":"40","C":"44","D":"36"}'::JSONB, 'A', 'फरक: +4, +6, +8, +10, +12. म्हणून 30 + 12 = 42. (किंवा n^2 + n: 1^2+1=2, 2^2+2=6, 3^2+3=12, 4^2+4=20, 5^2+5=30, 6^2+6=42).', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'SSC', '2020']::TEXT[], 'Hard'),
  (679, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'IBPS / State Cooperative Bank', 2021, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'IBPS', '2021']::TEXT[], 'Easy'),
  (680, 'राज्यघटना निर्मिती व सरनामा', 'Polity', 'MPSC Combined Group B & C', 2022, 'संविधानाच्या सरनाम्यात बंधुता, स्वातंत्र्य आणि समता ही मूल्ये कोणत्या क्रांतीकडून घेण्यात आली?', '{"A":"फ्रेंच राज्यक्रांती (1789)","B":"रशियन क्रांती (1917)","C":"अमेरिकन स्वातंत्र्ययुद्ध","D":"औद्योगिक क्रांती"}'::JSONB, 'A', 'स्वातंत्र्य, समता आणि बंधुता ही मूल्ये 1789 च्या फ्रेंच राज्यक्रांतीतून घेण्यात आली आहेत. तर सामाजिक, आर्थिक व राजकीय न्याय हे रशियन क्रांतीतून घेतले आहेत.', ARRAY['संविधान', 'सरनामा', 'Preamble', 'संविधान सभा', 'MPSC', '2022']::TEXT[], 'Medium'),
  (681, 'महाराष्ट्रातील समाजसुधारक', 'History', 'MPSC State Services (Rajyaseva)', 2023, 'डिप्रेस्ड क्लासेस मिशन (Depressed Classes Mission) ची स्थापना 1906 मध्ये कोणी केली?', '{"A":"महर्षी विठ्ठल रामजी शिंदे","B":"डॉ. बाबासाहेब आंबेडकर","C":"छत्रपती शाहू महाराज","D":"महात्मा फुले"}'::JSONB, 'A', '18 ऑक्टोबर 1906 रोजी मुंबईत महर्षी विठ्ठल रामजी शिंदे यांनी अस्पृश्यांच्या उद्धारासाठी डिप्रेस्ड क्लासेस मिशनची स्थापना केली.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'MPSC', '2023']::TEXT[], 'Hard'),
  (682, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'Maharashtra Police Constable Bharti', 2024, 'अ‍ॅल्युमिनियम बनवण्यासाठी वापरले जाणारे "बॉक्साईट" हे खनिज महाराष्ट्रात प्रामुख्याने कोणत्या जिल्ह्यात आढळते?', '{"A":"कोल्हापूर व रत्नागिरी","B":"नागपूर व भंडारा","C":"चंद्रपूर व यवतमाळ","D":"नाशिक व जळगाव"}'::JSONB, 'A', 'बॉक्साईट हे जांभा खडकाच्या भागात आढळते. कोल्हापूर, रत्नागिरी, सिंधुदुर्ग आणि रायगड जिल्ह्यात बॉक्साईटचे मोठे साठे आहेत.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'Maharashtra', '2024']::TEXT[], 'Easy'),
  (683, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2014, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2014']::TEXT[], 'Medium'),
  (684, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'Maharashtra Vanrakshak (Forest) Bharti', 2015, 'पेशीचे "ऊर्जा केंद्र" (Powerhouse of the Cell) कोणाला म्हणतात?', '{"A":"तंतुकणिका (Mitochondria)","B":"रायबोझोम","C":"लायसोझोम","D":"हरितलवके"}'::JSONB, 'A', 'तंतुकणिकेत (Mitochondria) पेशीय श्वसनातून ATP (Adenosine Triphosphate) च्या स्वरूपात ऊर्जा तयार होते, म्हणून त्यास पेशीचे ऊर्जा केंद्र म्हणतात.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'Maharashtra', '2015']::TEXT[], 'Hard'),
  (685, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'SSC CGL & CHSL', 2016, 'मराठी वर्णमालेत एकूण किती मूळ स्वर मानले जातात?', '{"A":"12 स्वर (+ 2 इंग्रजी स्वर = 14)","B":"10 स्वर","C":"16 स्वर","D":"8 स्वर"}'::JSONB, 'A', 'पारंपरिक वर्णमालेत 12 स्वर होते. महाराष्ट्र शासनाच्या 2009 च्या जीआरनुसार ॲ आणि ऑ मिळून एकूण 14 स्वर आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'SSC', '2016']::TEXT[], 'Easy'),
  (686, 'English Grammar & Vocabulary', 'English', 'IBPS / State Cooperative Bank', 2017, 'Identify the meaning of idiom: "A blessing in disguise"', '{"A":"Something good that isn''t recognized at first","B":"A holy prayer","C":"A fake curse","D":"A sudden disaster"}'::JSONB, 'A', '"A blessing in disguise" means an apparent misfortune that eventually results in something unexpectedly good.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'IBPS', '2017']::TEXT[], 'Medium'),
  (687, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'MPSC Combined Group B & C', 2018, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'MPSC', '2018']::TEXT[], 'Hard'),
  (688, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC State Services (Rajyaseva)', 2019, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2019']::TEXT[], 'Easy'),
  (689, 'राज्यघटना निर्मिती व सरनामा', 'Polity', 'Maharashtra Police Constable Bharti', 2020, 'संविधानाच्या सरनाम्यात बंधुता, स्वातंत्र्य आणि समता ही मूल्ये कोणत्या क्रांतीकडून घेण्यात आली?', '{"A":"फ्रेंच राज्यक्रांती (1789)","B":"रशियन क्रांती (1917)","C":"अमेरिकन स्वातंत्र्ययुद्ध","D":"औद्योगिक क्रांती"}'::JSONB, 'A', 'स्वातंत्र्य, समता आणि बंधुता ही मूल्ये 1789 च्या फ्रेंच राज्यक्रांतीतून घेण्यात आली आहेत. तर सामाजिक, आर्थिक व राजकीय न्याय हे रशियन क्रांतीतून घेतले आहेत.', ARRAY['संविधान', 'सरनामा', 'Preamble', 'संविधान सभा', 'Maharashtra', '2020']::TEXT[], 'Medium'),
  (690, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2021, '1942 च्या चले जाव आंदोलनात सातारा येथे "प्रतिसरकार" (Patri Sarkar) ची स्थापना कोणी केली?', '{"A":"क्रांतिसिंह नाना पाटील","B":"सेनापती बापट","C":"किसन वीर","D":"वसंतदादा पाटील"}'::JSONB, 'A', 'क्रांतिसिंह नाना पाटील यांनी साताऱ्यात प्रतिसरकार स्थापन करून समांतर न्याय व प्रशासकीय व्यवस्था उभारली, ज्यास "पत्री सरकार" म्हटले जायचे.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'Maharashtra', '2021']::TEXT[], 'Hard'),
  (691, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'Maharashtra Vanrakshak (Forest) Bharti', 2022, 'अ‍ॅल्युमिनियम बनवण्यासाठी वापरले जाणारे "बॉक्साईट" हे खनिज महाराष्ट्रात प्रामुख्याने कोणत्या जिल्ह्यात आढळते?', '{"A":"कोल्हापूर व रत्नागिरी","B":"नागपूर व भंडारा","C":"चंद्रपूर व यवतमाळ","D":"नाशिक व जळगाव"}'::JSONB, 'A', 'बॉक्साईट हे जांभा खडकाच्या भागात आढळते. कोल्हापूर, रत्नागिरी, सिंधुदुर्ग आणि रायगड जिल्ह्यात बॉक्साईटचे मोठे साठे आहेत.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'Maharashtra', '2022']::TEXT[], 'Easy'),
  (692, 'बँकिंग, वित्त व महागाई', 'Economy', 'SSC CGL & CHSL', 2023, 'भारतात कृषी आणि ग्रामीण विकासासाठी पतपुरवठा करणारी शिखर संस्था कोणती?', '{"A":"नाबार्ड (NABARD)","B":"सिडबी (SIDBI)","C":"आयडीबीआय (IDBI)","D":"सेबी (SEBI)"}'::JSONB, 'A', 'शिवरामन समितीच्या शिफारशीवरून 12 जुलै 1982 रोजी NABARD (National Bank for Agriculture and Rural Development) ची स्थापना झाली.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'SSC', '2023']::TEXT[], 'Medium'),
  (693, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'IBPS / State Cooperative Bank', 2024, 'पेशीचे "ऊर्जा केंद्र" (Powerhouse of the Cell) कोणाला म्हणतात?', '{"A":"तंतुकणिका (Mitochondria)","B":"रायबोझोम","C":"लायसोझोम","D":"हरितलवके"}'::JSONB, 'A', 'तंतुकणिकेत (Mitochondria) पेशीय श्वसनातून ATP (Adenosine Triphosphate) च्या स्वरूपात ऊर्जा तयार होते, म्हणून त्यास पेशीचे ऊर्जा केंद्र म्हणतात.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'IBPS', '2024']::TEXT[], 'Hard'),
  (694, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'MPSC Combined Group B & C', 2014, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'MPSC', '2014']::TEXT[], 'Easy'),
  (695, 'English Grammar & Vocabulary', 'English', 'MPSC State Services (Rajyaseva)', 2015, 'Fill in the blank with appropriate preposition: "She is proficient _____ speaking Marathi and English."', '{"A":"in","B":"at","C":"with","D":"for"}'::JSONB, 'A', 'The adjective "proficient" is followed by the preposition "in" (e.g. proficient in a language or subject).', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'MPSC', '2015']::TEXT[], 'Medium'),
  (696, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Police Constable Bharti', 2016, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2016']::TEXT[], 'Hard'),
  (697, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2017, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2017']::TEXT[], 'Easy'),
  (698, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'Maharashtra Vanrakshak (Forest) Bharti', 2018, 'भारताचे नियंत्रक व महालेखापरीक्षक (CAG) यांची नियुक्ती कोणत्या कलमान्वये होते?', '{"A":"कलम 148","B":"कलम 280","C":"कलम 324","D":"कलम 76"}'::JSONB, 'A', 'कलम 148 नुसार राष्ट्रपती CAG ची नियुक्ती करतात. CAG हे सार्वजनिक वित्ताचे संरक्षक असतात (Guardian of Public Purse).', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'Maharashtra', '2018']::TEXT[], 'Medium'),
  (699, 'महाराष्ट्रातील समाजसुधारक', 'History', 'SSC CGL & CHSL', 2019, 'डिप्रेस्ड क्लासेस मिशन (Depressed Classes Mission) ची स्थापना 1906 मध्ये कोणी केली?', '{"A":"महर्षी विठ्ठल रामजी शिंदे","B":"डॉ. बाबासाहेब आंबेडकर","C":"छत्रपती शाहू महाराज","D":"महात्मा फुले"}'::JSONB, 'A', '18 ऑक्टोबर 1906 रोजी मुंबईत महर्षी विठ्ठल रामजी शिंदे यांनी अस्पृश्यांच्या उद्धारासाठी डिप्रेस्ड क्लासेस मिशनची स्थापना केली.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'SSC', '2019']::TEXT[], 'Hard'),
  (700, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'IBPS / State Cooperative Bank', 2020, 'महाराष्ट्रातील दगडी कोळशाचे सर्वात प्रसिद्ध क्षेत्र "बल्लारपूर" कोणत्या जिल्ह्यात आहे?', '{"A":"चंद्रपूर","B":"नागपूर","C":"यवतमाळ","D":"भंडारा"}'::JSONB, 'A', 'चंद्रपूर आणि नागपूर जिल्ह्यात विदर्भामध्ये दगडी कोळशाच्या खाणी आहेत. वर्धा-वैणगंगा खोऱ्यात बल्लारपूर हे कोळशाचे मोठे केंद्र आहे.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'IBPS', '2020']::TEXT[], 'Easy')
