  (751, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC State Services (Rajyaseva)', 2016, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2016']::TEXT[], 'Easy'),
  (752, 'मूलभूत हक्क (Fundamental Rights)', 'Polity', 'Maharashtra Police Constable Bharti', 2017, 'खाजगीपणाचा हक्क (Right to Privacy) हा कोणत्या कलमांतर्गत मूलभूत हक्क ठरवण्यात आला?', '{"A":"कलम 21","B":"कलम 19","C":"कलम 14","D":"कलम 25"}'::JSONB, 'A', 'पुट्टस्वामी खटला (2017) मध्ये सर्वोच्च न्यायालयाच्या 9 न्यायाधीशांच्या खंडपीठाने खाजगीपणाचा हक्क हा कलम 21 मधील जगण्याच्या हक्काचा भाग मानला.', ARRAY['मूलभूत हक्क', 'कलम १४', 'कलम १९', 'कलम २१', 'कलम ३२', 'Maharashtra', '2017']::TEXT[], 'Medium'),
  (753, 'महाराष्ट्रातील समाजसुधारक', 'History', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2018, 'डिप्रेस्ड क्लासेस मिशन (Depressed Classes Mission) ची स्थापना 1906 मध्ये कोणी केली?', '{"A":"महर्षी विठ्ठल रामजी शिंदे","B":"डॉ. बाबासाहेब आंबेडकर","C":"छत्रपती शाहू महाराज","D":"महात्मा फुले"}'::JSONB, 'A', '18 ऑक्टोबर 1906 रोजी मुंबईत महर्षी विठ्ठल रामजी शिंदे यांनी अस्पृश्यांच्या उद्धारासाठी डिप्रेस्ड क्लासेस मिशनची स्थापना केली.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'Maharashtra', '2018']::TEXT[], 'Hard'),
  (754, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'Maharashtra Vanrakshak (Forest) Bharti', 2019, 'अ‍ॅल्युमिनियम बनवण्यासाठी वापरले जाणारे "बॉक्साईट" हे खनिज महाराष्ट्रात प्रामुख्याने कोणत्या जिल्ह्यात आढळते?', '{"A":"कोल्हापूर व रत्नागिरी","B":"नागपूर व भंडारा","C":"चंद्रपूर व यवतमाळ","D":"नाशिक व जळगाव"}'::JSONB, 'A', 'बॉक्साईट हे जांभा खडकाच्या भागात आढळते. कोल्हापूर, रत्नागिरी, सिंधुदुर्ग आणि रायगड जिल्ह्यात बॉक्साईटचे मोठे साठे आहेत.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'Maharashtra', '2019']::TEXT[], 'Easy'),
  (755, 'बँकिंग, वित्त व महागाई', 'Economy', 'SSC CGL & CHSL', 2020, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'SSC', '2020']::TEXT[], 'Medium'),
  (756, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'IBPS / State Cooperative Bank', 2021, 'मानवी शरीरातील सर्वात मोठी ग्रंथी (Largest Gland) कोणती?', '{"A":"यकृत (Liver)","B":"स्वादुपिंड (Pancreas)","C":"थायरॉईड ग्रंथी","D":"जठर"}'::JSONB, 'A', 'यकृत ही मानवी शरीरातील सर्वात मोठी ग्रंथी (वजन सुमारे 1.5 किलो) असून ती पित्तरस (Bile juice) तयार करते.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'IBPS', '2021']::TEXT[], 'Hard'),
  (757, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'MPSC Combined Group B & C', 2022, '"अन्नास जागणे" या वाक्प्रचाराचा अचूक अर्थ काय?', '{"A":"उपकाराची जाणीव ठेवणे (कृतज्ञ राहणे)","B":"अन्न वाया घालवणे","C":"रात्रभर जागत राहणे","D":"जेवणावर ताव मारणे"}'::JSONB, 'A', 'अन्नास जागणे म्हणजे केलेल्या उपकारांची सदैव जाणीव ठेवणे (कृतज्ञ असणे). याचा विरुद्धार्थी वाक्प्रचार "अन्नास कापणे" (कृतघ्न असणे) हा आहे.', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'MPSC', '2022']::TEXT[], 'Easy'),
  (758, 'English Grammar & Vocabulary', 'English', 'MPSC State Services (Rajyaseva)', 2023, 'Fill in the blank with appropriate preposition: "She is proficient _____ speaking Marathi and English."', '{"A":"in","B":"at","C":"with","D":"for"}'::JSONB, 'A', 'The adjective "proficient" is followed by the preposition "in" (e.g. proficient in a language or subject).', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'MPSC', '2023']::TEXT[], 'Medium'),
  (759, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Police Constable Bharti', 2024, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2024']::TEXT[], 'Hard'),
  (760, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2014, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2014']::TEXT[], 'Easy'),
  (761, 'राज्यघटना निर्मिती व सरनामा', 'Polity', 'Maharashtra Vanrakshak (Forest) Bharti', 2015, 'संविधान मसुदा समितीचे (Drafting Committee) अध्यक्ष कोण होते?', '{"A":"डॉ. बाबासाहेब आंबेडकर","B":"डॉ. राजेंद्र प्रसाद","C":"पंडित नेहरू","D":"सर बी. एन. राव"}'::JSONB, 'A', '29 ऑगस्ट 1947 रोजी मसुदा समितीची स्थापना झाली व डॉ. बाबासाहेब आंबेडकर अध्यक्ष होते. सर बी. एन. राव हे घटनात्मक सल्लागार होते.', ARRAY['संविधान', 'सरनामा', 'Preamble', 'संविधान सभा', 'Maharashtra', '2015']::TEXT[], 'Medium'),
  (762, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'SSC CGL & CHSL', 2016, 'लोकमान्य बाळ गंगाधर टिळकांनी 1916 मध्ये बेळगाव येथे कोणती चळवळ सुरू केली?', '{"A":"होमरूल लीग चळवळ (Home Rule League)","B":"असहकार आंदोलन","C":"भारत छोडो","D":"सविनय कायदेभंग"}'::JSONB, 'A', 'एप्रिल 1916 मध्ये बेळगाव येथे टिळकांनी होमरूल लीगची स्थापना केली आणि "स्वराज्य हा माझा जन्मसिद्ध हक्क आहे आणि तो मी मिळवणारच" ही सिंहगर्जना केली.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'SSC', '2016']::TEXT[], 'Hard'),
  (763, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'IBPS / State Cooperative Bank', 2017, 'महाराष्ट्रातील तापी नदी कोणत्या दिशेने वाहते?', '{"A":"पश्चिम वाहिनी","B":"पूर्व वाहिनी","C":"दक्षिण वाहिनी","D":"उत्तर वाहिनी"}'::JSONB, 'A', 'तापी आणि नर्मदा या महाराष्ट्रातील प्रमुख पश्चिम वाहिनी नद्या आहेत, ज्या खचदरीतून वाहत जाऊन अरबी समुद्रास (खंबायतचे आखात) मिळतात.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'IBPS', '2017']::TEXT[], 'Easy'),
  (764, 'बँकिंग, वित्त व महागाई', 'Economy', 'MPSC Combined Group B & C', 2018, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'MPSC', '2018']::TEXT[], 'Medium'),
  (765, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'MPSC State Services (Rajyaseva)', 2019, 'सूर्याकडून पृथ्वीकडे येणारी उष्णता कोणत्या पद्धतीने संक्रमित होते?', '{"A":"प्रारण (Radiation)","B":"वहन (Conduction)","C":"अभिसरण (Convection)","D":"बाष्पीभवन"}'::JSONB, 'A', 'प्रारणासाठी (Radiation) कोणत्याही भौतिक माध्यमाची गरज नसते, म्हणून अवकाशातील पोकळीतून सूर्याची ऊर्जा प्रारण पद्धतीने पृथ्वीपर्यंत पोहोचते.', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'MPSC', '2019']::TEXT[], 'Hard'),
  (766, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'Maharashtra Police Constable Bharti', 2020, '"सूर्य + उदय = सूर्योदय" हा कोणत्या संधीचा प्रकार आहे?', '{"A":"स्वरसंधी (गुणादेश)","B":"व्यंजनसंधी","C":"विसर्गसंधी","D":"पूर्वरूप संधी"}'::JSONB, 'A', 'अ/आ च्या पुढे उ आल्यास दोघांबद्दल ओ होतो (गुणादेश), ही स्वरसंधीची उदाहरणे आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'Maharashtra', '2020']::TEXT[], 'Easy'),
  (767, 'English Grammar & Vocabulary', 'English', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2021, 'Fill in the blank with appropriate preposition: "She is proficient _____ speaking Marathi and English."', '{"A":"in","B":"at","C":"with","D":"for"}'::JSONB, 'A', 'The adjective "proficient" is followed by the preposition "in" (e.g. proficient in a language or subject).', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2021']::TEXT[], 'Medium'),
  (768, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Vanrakshak (Forest) Bharti', 2022, 'जर 5 माणसे एक काम 10 दिवसांत करतात, तर 2 माणसे तेच काम किती दिवसांत करतील?', '{"A":"25 दिवस","B":"20 दिवस","C":"15 दिवस","D":"30 दिवस"}'::JSONB, 'A', 'माणसे x दिवस = स्थिरांक. 5 x 10 = 50 मॅन-डेज. 50 / 2 = 25 दिवस.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2022']::TEXT[], 'Hard'),
  (769, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'SSC CGL & CHSL', 2023, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'SSC', '2023']::TEXT[], 'Easy'),
  (770, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'IBPS / State Cooperative Bank', 2024, 'भारताचे राष्ट्रपती होण्यासाठी किमान वय किती वर्षे पूर्ण असावे लागते?', '{"A":"35 वर्षे","B":"30 वर्षे","C":"25 वर्षे","D":"21 वर्षे"}'::JSONB, 'A', 'राष्ट्रपती व राज्यपालांसाठी किमान वय 35 वर्षे, राज्यसभेसाठी 30 वर्षे, लोकसभेसाठी 25 वर्षे आणि ग्रामपंचायतीसाठी 21 वर्षे आवश्यक आहे.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'IBPS', '2024']::TEXT[], 'Medium'),
  (771, 'महाराष्ट्रातील समाजसुधारक', 'History', 'MPSC Combined Group B & C', 2014, 'महर्षी धोंडो केशव कर्वे यांनी 1916 मध्ये पुण्यात कोणत्या पहिल्या महिला विद्यापीठाची स्थापना केली?', '{"A":"SNDT महिला विद्यापीठ","B":"सावित्रीबाई फुले विद्यापीठ","C":"टिळक महाराष्ट्र विद्यापीठ","D":"मुंबई विद्यापीठ"}'::JSONB, 'A', 'महर्षी कर्व्यांनी 1916 मध्ये हिंगणे (पुणे) येथे जपानच्या धर्तीवर स्वतंत्र महिला विद्यापीठ सुरू केले, ज्यास सर विठ्ठलदास ठाकरसी यांच्या मातोश्री नाथीबाई यांच्या स्मरणार्थ SNDT नाव दिले गेले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'MPSC', '2014']::TEXT[], 'Hard'),
  (772, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'MPSC State Services (Rajyaseva)', 2015, 'महाराष्ट्रात सर्वाधिक वनक्षेत्र कोणत्या जिल्ह्यात आढळते?', '{"A":"गडचिरोली","B":"चंद्रपूर","C":"रत्नागिरी","D":"अमरावती"}'::JSONB, 'A', 'गडचिरोली जिल्ह्यात भौगोलिक क्षेत्राच्या सर्वाधिक (सुमारे 68% पेक्षा जास्त) भूभाग वनाच्छादित आहे.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'MPSC', '2015']::TEXT[], 'Easy'),
  (773, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Police Constable Bharti', 2016, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2016']::TEXT[], 'Medium'),
  (774, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2017, 'सूर्याकडून पृथ्वीकडे येणारी उष्णता कोणत्या पद्धतीने संक्रमित होते?', '{"A":"प्रारण (Radiation)","B":"वहन (Conduction)","C":"अभिसरण (Convection)","D":"बाष्पीभवन"}'::JSONB, 'A', 'प्रारणासाठी (Radiation) कोणत्याही भौतिक माध्यमाची गरज नसते, म्हणून अवकाशातील पोकळीतून सूर्याची ऊर्जा प्रारण पद्धतीने पृथ्वीपर्यंत पोहोचते.', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'Maharashtra', '2017']::TEXT[], 'Hard'),
  (775, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'Maharashtra Vanrakshak (Forest) Bharti', 2018, '"अन्नास जागणे" या वाक्प्रचाराचा अचूक अर्थ काय?', '{"A":"उपकाराची जाणीव ठेवणे (कृतज्ञ राहणे)","B":"अन्न वाया घालवणे","C":"रात्रभर जागत राहणे","D":"जेवणावर ताव मारणे"}'::JSONB, 'A', 'अन्नास जागणे म्हणजे केलेल्या उपकारांची सदैव जाणीव ठेवणे (कृतज्ञ असणे). याचा विरुद्धार्थी वाक्प्रचार "अन्नास कापणे" (कृतघ्न असणे) हा आहे.', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'Maharashtra', '2018']::TEXT[], 'Easy'),
  (776, 'English Grammar & Vocabulary', 'English', 'SSC CGL & CHSL', 2019, 'Choose the correct synonym for "TENACIOUS":', '{"A":"Persistent / Determined","B":"Timid","C":"Weak","D":"Cautious"}'::JSONB, 'A', '"Tenacious" means holding fast, persistent, stubborn or resolute.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'SSC', '2019']::TEXT[], 'Medium'),
  (777, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'IBPS / State Cooperative Bank', 2020, 'पुढील संख्यामालिकेतील प्रश्नचिन्हाच्या जागी काय येईल: 2, 6, 12, 20, 30, ?', '{"A":"42","B":"40","C":"44","D":"36"}'::JSONB, 'A', 'फरक: +4, +6, +8, +10, +12. म्हणून 30 + 12 = 42. (किंवा n^2 + n: 1^2+1=2, 2^2+2=6, 3^2+3=12, 4^2+4=20, 5^2+5=30, 6^2+6=42).', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'IBPS', '2020']::TEXT[], 'Hard'),
  (778, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC Combined Group B & C', 2021, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2021']::TEXT[], 'Easy'),
  (779, 'मूलभूत हक्क (Fundamental Rights)', 'Polity', 'MPSC State Services (Rajyaseva)', 2022, 'कोणत्या कलमाद्वारे बालमजुरीवर (14 वर्षांखालील बालकांना कारखान्यात कामावर ठेवण्यास) बंदी घालण्यात आली आहे?', '{"A":"कलम 24","B":"कलम 23","C":"कलम 21A","D":"कलम 25"}'::JSONB, 'A', 'कलम 24 नुसार धोकादायक ठिकाणी 14 वर्षांखालील बालकांना कामावर ठेवण्यास सक्त मनाई आहे. कलम 23 मानवी व्यापार व वेठबिगारीस प्रतिबंध करते.', ARRAY['मूलभूत हक्क', 'कलम १४', 'कलम १९', 'कलम २१', 'कलम ३२', 'MPSC', '2022']::TEXT[], 'Medium'),
  (780, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'Maharashtra Police Constable Bharti', 2023, '1942 च्या चले जाव आंदोलनात सातारा येथे "प्रतिसरकार" (Patri Sarkar) ची स्थापना कोणी केली?', '{"A":"क्रांतिसिंह नाना पाटील","B":"सेनापती बापट","C":"किसन वीर","D":"वसंतदादा पाटील"}'::JSONB, 'A', 'क्रांतिसिंह नाना पाटील यांनी साताऱ्यात प्रतिसरकार स्थापन करून समांतर न्याय व प्रशासकीय व्यवस्था उभारली, ज्यास "पत्री सरकार" म्हटले जायचे.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'Maharashtra', '2023']::TEXT[], 'Hard'),
  (781, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2024, 'महाराष्ट्रातील तापी नदी कोणत्या दिशेने वाहते?', '{"A":"पश्चिम वाहिनी","B":"पूर्व वाहिनी","C":"दक्षिण वाहिनी","D":"उत्तर वाहिनी"}'::JSONB, 'A', 'तापी आणि नर्मदा या महाराष्ट्रातील प्रमुख पश्चिम वाहिनी नद्या आहेत, ज्या खचदरीतून वाहत जाऊन अरबी समुद्रास (खंबायतचे आखात) मिळतात.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'Maharashtra', '2024']::TEXT[], 'Easy'),
  (782, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Vanrakshak (Forest) Bharti', 2014, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2014']::TEXT[], 'Medium'),
  (783, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'SSC CGL & CHSL', 2015, 'शुद्ध पाण्याचे pH मूल्य किती असते?', '{"A":"7 (उदासीन)","B":"0","C":"14","D":"4"}'::JSONB, 'A', 'pH स्केलवर 7 म्हणजे उदासीन (उदा. शुद्ध पाणी). 7 पेक्षा कमी म्हणजे आम्लधर्मी (Acidic) आणि 7 पेक्षा जास्त म्हणजे आम्लारीधर्मी (Basic).', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'SSC', '2015']::TEXT[], 'Hard'),
  (784, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'IBPS / State Cooperative Bank', 2016, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'IBPS', '2016']::TEXT[], 'Easy'),
  (785, 'English Grammar & Vocabulary', 'English', 'MPSC Combined Group B & C', 2017, 'Identify the meaning of idiom: "A blessing in disguise"', '{"A":"Something good that isn''t recognized at first","B":"A holy prayer","C":"A fake curse","D":"A sudden disaster"}'::JSONB, 'A', '"A blessing in disguise" means an apparent misfortune that eventually results in something unexpectedly good.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'MPSC', '2017']::TEXT[], 'Medium'),
  (786, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'MPSC State Services (Rajyaseva)', 2018, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'MPSC', '2018']::TEXT[], 'Hard'),
  (787, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Police Constable Bharti', 2019, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2019']::TEXT[], 'Easy'),
  (788, 'मूलभूत हक्क (Fundamental Rights)', 'Polity', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2020, 'धार्मिक स्वातंत्र्याचा मूलभूत हक्क कोणत्या कलमांतर्गत येतो?', '{"A":"कलम 25 ते 28","B":"कलम 19 ते 22","C":"कलम 29 ते 30","D":"कलम 14 ते 18"}'::JSONB, 'A', 'कलम 25 ते 28 धार्मिक स्वातंत्र्याची हमी देते. कलम 25 नुसार प्रत्येकाला सद्सद्विवेकबुद्धीचे स्वातंत्र्य व धर्माचे आचरण करण्याचा हक्क आहे.', ARRAY['मूलभूत हक्क', 'कलम १४', 'कलम १९', 'कलम २१', 'कलम ३२', 'Maharashtra', '2020']::TEXT[], 'Medium'),
