  (791, 'बँकिंग, वित्त व महागाई', 'Economy', 'IBPS / State Cooperative Bank', 2023, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'IBPS', '2023']::TEXT[], 'Medium'),
  (792, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'MPSC Combined Group B & C', 2024, 'शुद्ध पाण्याचे pH मूल्य किती असते?', '{"A":"7 (उदासीन)","B":"0","C":"14","D":"4"}'::JSONB, 'A', 'pH स्केलवर 7 म्हणजे उदासीन (उदा. शुद्ध पाणी). 7 पेक्षा कमी म्हणजे आम्लधर्मी (Acidic) आणि 7 पेक्षा जास्त म्हणजे आम्लारीधर्मी (Basic).', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'MPSC', '2024']::TEXT[], 'Hard'),
  (793, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'MPSC State Services (Rajyaseva)', 2014, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'MPSC', '2014']::TEXT[], 'Easy'),
  (794, 'English Grammar & Vocabulary', 'English', 'Maharashtra Police Constable Bharti', 2015, 'Fill in the blank with appropriate preposition: "She is proficient _____ speaking Marathi and English."', '{"A":"in","B":"at","C":"with","D":"for"}'::JSONB, 'A', 'The adjective "proficient" is followed by the preposition "in" (e.g. proficient in a language or subject).', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2015']::TEXT[], 'Medium'),
  (795, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2016, 'जर 5 माणसे एक काम 10 दिवसांत करतात, तर 2 माणसे तेच काम किती दिवसांत करतील?', '{"A":"25 दिवस","B":"20 दिवस","C":"15 दिवस","D":"30 दिवस"}'::JSONB, 'A', 'माणसे x दिवस = स्थिरांक. 5 x 10 = 50 मॅन-डेज. 50 / 2 = 25 दिवस.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2016']::TEXT[], 'Hard'),
  (796, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Vanrakshak (Forest) Bharti', 2017, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2017']::TEXT[], 'Easy'),
  (797, 'राज्यघटना निर्मिती व सरनामा', 'Polity', 'SSC CGL & CHSL', 2018, 'संविधान मसुदा समितीचे (Drafting Committee) अध्यक्ष कोण होते?', '{"A":"डॉ. बाबासाहेब आंबेडकर","B":"डॉ. राजेंद्र प्रसाद","C":"पंडित नेहरू","D":"सर बी. एन. राव"}'::JSONB, 'A', '29 ऑगस्ट 1947 रोजी मसुदा समितीची स्थापना झाली व डॉ. बाबासाहेब आंबेडकर अध्यक्ष होते. सर बी. एन. राव हे घटनात्मक सल्लागार होते.', ARRAY['संविधान', 'सरनामा', 'Preamble', 'संविधान सभा', 'SSC', '2018']::TEXT[], 'Medium'),
  (798, 'महाराष्ट्रातील समाजसुधारक', 'History', 'IBPS / State Cooperative Bank', 2019, 'गोपाळ गणेश आगरकर यांनी लोकमान्य टिळकांपासून वेगळे झाल्यानंतर कोणते वृत्तपत्र सुरू केले?', '{"A":"सुधारक (1888)","B":"केसरी","C":"मराठा","D":"ज्ञानप्रकाश"}'::JSONB, 'A', 'आगरकरांनी राजकीय सुधारणांपेक्षा सामाजिक सुधारणांना प्राधान्य दिले आणि 1888 मध्ये "सुधारक" हे विचारप्रधान वृत्तपत्र सुरू केले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'IBPS', '2019']::TEXT[], 'Hard'),
  (799, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'MPSC Combined Group B & C', 2020, 'अ‍ॅल्युमिनियम बनवण्यासाठी वापरले जाणारे "बॉक्साईट" हे खनिज महाराष्ट्रात प्रामुख्याने कोणत्या जिल्ह्यात आढळते?', '{"A":"कोल्हापूर व रत्नागिरी","B":"नागपूर व भंडारा","C":"चंद्रपूर व यवतमाळ","D":"नाशिक व जळगाव"}'::JSONB, 'A', 'बॉक्साईट हे जांभा खडकाच्या भागात आढळते. कोल्हापूर, रत्नागिरी, सिंधुदुर्ग आणि रायगड जिल्ह्यात बॉक्साईटचे मोठे साठे आहेत.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'MPSC', '2020']::TEXT[], 'Easy'),
  (800, 'बँकिंग, वित्त व महागाई', 'Economy', 'MPSC State Services (Rajyaseva)', 2021, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'MPSC', '2021']::TEXT[], 'Medium')
INSERT INTO pyq_questions (id, topic, subject, exam, year, question, options, correct, explanation, tags, difficulty)
VALUES
  (801, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'Maharashtra Police Constable Bharti', 2022, 'मानवी शरीरातील सर्वात मोठी ग्रंथी (Largest Gland) कोणती?', '{"A":"यकृत (Liver)","B":"स्वादुपिंड (Pancreas)","C":"थायरॉईड ग्रंथी","D":"जठर"}'::JSONB, 'A', 'यकृत ही मानवी शरीरातील सर्वात मोठी ग्रंथी (वजन सुमारे 1.5 किलो) असून ती पित्तरस (Bile juice) तयार करते.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'Maharashtra', '2022']::TEXT[], 'Hard'),
  (802, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2023, '"अळंबी" या शब्दाचा समानार्थी शब्द खालीलपैकी कोणता?', '{"A":"मशरूम / छत्रक","B":"अडथळा","C":"आळस","D":"अंधार"}'::JSONB, 'A', 'अळंबी म्हणजे कुत्र्याची छत्री किंवा खाद्य वनस्पती (Mushroom / छत्रक).', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'Maharashtra', '2023']::TEXT[], 'Easy'),
  (803, 'English Grammar & Vocabulary', 'English', 'Maharashtra Vanrakshak (Forest) Bharti', 2024, 'Fill in the blank with appropriate preposition: "She is proficient _____ speaking Marathi and English."', '{"A":"in","B":"at","C":"with","D":"for"}'::JSONB, 'A', 'The adjective "proficient" is followed by the preposition "in" (e.g. proficient in a language or subject).', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2024']::TEXT[], 'Medium'),
  (804, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'SSC CGL & CHSL', 2014, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'SSC', '2014']::TEXT[], 'Hard'),
  (805, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'IBPS / State Cooperative Bank', 2015, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'IBPS', '2015']::TEXT[], 'Easy'),
  (806, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'MPSC Combined Group B & C', 2016, 'संसदेच्या दोन्ही सभागृहांचे संयुक्त अधिवेशन (Joint Sitting) कोण बोलावतात?', '{"A":"भारताचे राष्ट्रपती","B":"लोकसभा अध्यक्ष","C":"उपराष्ट्रपती","D":"पंतप्रधान"}'::JSONB, 'A', 'कलम 108 नुसार राष्ट्रपती संयुक्त अधिवेशन बोलावतात; परंतु त्याचे अध्यक्षस्थान नेहमी लोकसभेचे अध्यक्ष (Speaker) भूषवितात.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'MPSC', '2016']::TEXT[], 'Medium'),
  (807, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'MPSC State Services (Rajyaseva)', 2017, '1942 च्या चले जाव आंदोलनात सातारा येथे "प्रतिसरकार" (Patri Sarkar) ची स्थापना कोणी केली?', '{"A":"क्रांतिसिंह नाना पाटील","B":"सेनापती बापट","C":"किसन वीर","D":"वसंतदादा पाटील"}'::JSONB, 'A', 'क्रांतिसिंह नाना पाटील यांनी साताऱ्यात प्रतिसरकार स्थापन करून समांतर न्याय व प्रशासकीय व्यवस्था उभारली, ज्यास "पत्री सरकार" म्हटले जायचे.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'MPSC', '2017']::TEXT[], 'Hard'),
  (808, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'Maharashtra Police Constable Bharti', 2018, 'भीमा नदीचा उगम पुणे जिल्ह्यातील कोणत्या ज्योतिर्लिंगाजवळ होतो?', '{"A":"भीमाशंकर","B":"त्र्यंबकेश्वर","C":"घृष्णेश्वर","D":"परळी वैजनाथ"}'::JSONB, 'A', 'भीमा नदीचा उगम सह्याद्री पर्वतात भीमाशंकर येथे होतो. भीमा नदी पंढरपूर येथे चंद्रभागा म्हणून ओळखली जाते व पुढे कर्नाटकात कृष्णा नदीस मिळते.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'Maharashtra', '2018']::TEXT[], 'Easy'),
  (809, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2019, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2019']::TEXT[], 'Medium'),
  (810, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'Maharashtra Vanrakshak (Forest) Bharti', 2020, 'सूर्याकडून पृथ्वीकडे येणारी उष्णता कोणत्या पद्धतीने संक्रमित होते?', '{"A":"प्रारण (Radiation)","B":"वहन (Conduction)","C":"अभिसरण (Convection)","D":"बाष्पीभवन"}'::JSONB, 'A', 'प्रारणासाठी (Radiation) कोणत्याही भौतिक माध्यमाची गरज नसते, म्हणून अवकाशातील पोकळीतून सूर्याची ऊर्जा प्रारण पद्धतीने पृथ्वीपर्यंत पोहोचते.', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'Maharashtra', '2020']::TEXT[], 'Hard'),
  (811, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'SSC CGL & CHSL', 2021, '"अळंबी" या शब्दाचा समानार्थी शब्द खालीलपैकी कोणता?', '{"A":"मशरूम / छत्रक","B":"अडथळा","C":"आळस","D":"अंधार"}'::JSONB, 'A', 'अळंबी म्हणजे कुत्र्याची छत्री किंवा खाद्य वनस्पती (Mushroom / छत्रक).', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'SSC', '2021']::TEXT[], 'Easy'),
  (812, 'English Grammar & Vocabulary', 'English', 'IBPS / State Cooperative Bank', 2022, 'Choose the correct synonym for "TENACIOUS":', '{"A":"Persistent / Determined","B":"Timid","C":"Weak","D":"Cautious"}'::JSONB, 'A', '"Tenacious" means holding fast, persistent, stubborn or resolute.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'IBPS', '2022']::TEXT[], 'Medium'),
  (813, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'MPSC Combined Group B & C', 2023, 'जर 5 माणसे एक काम 10 दिवसांत करतात, तर 2 माणसे तेच काम किती दिवसांत करतील?', '{"A":"25 दिवस","B":"20 दिवस","C":"15 दिवस","D":"30 दिवस"}'::JSONB, 'A', 'माणसे x दिवस = स्थिरांक. 5 x 10 = 50 मॅन-डेज. 50 / 2 = 25 दिवस.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'MPSC', '2023']::TEXT[], 'Hard'),
  (814, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC State Services (Rajyaseva)', 2024, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2024']::TEXT[], 'Easy'),
  (815, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'Maharashtra Police Constable Bharti', 2014, 'सर्वोच्च न्यायालयातील न्यायाधीशांचे निवृत्तीचे वय किती वर्षे असते?', '{"A":"65 वर्षे","B":"62 वर्षे","C":"60 वर्षे","D":"70 वर्षे"}'::JSONB, 'A', 'सर्वोच्च न्यायालयाच्या न्यायाधीशांचे निवृत्ती वय 65 वर्षे, तर उच्च न्यायालयाच्या न्यायाधीशांचे 62 वर्षे असते.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'Maharashtra', '2014']::TEXT[], 'Medium'),
  (816, 'महाराष्ट्रातील समाजसुधारक', 'History', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2015, 'डिप्रेस्ड क्लासेस मिशन (Depressed Classes Mission) ची स्थापना 1906 मध्ये कोणी केली?', '{"A":"महर्षी विठ्ठल रामजी शिंदे","B":"डॉ. बाबासाहेब आंबेडकर","C":"छत्रपती शाहू महाराज","D":"महात्मा फुले"}'::JSONB, 'A', '18 ऑक्टोबर 1906 रोजी मुंबईत महर्षी विठ्ठल रामजी शिंदे यांनी अस्पृश्यांच्या उद्धारासाठी डिप्रेस्ड क्लासेस मिशनची स्थापना केली.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'Maharashtra', '2015']::TEXT[], 'Hard'),
  (817, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'Maharashtra Vanrakshak (Forest) Bharti', 2016, 'अ‍ॅल्युमिनियम बनवण्यासाठी वापरले जाणारे "बॉक्साईट" हे खनिज महाराष्ट्रात प्रामुख्याने कोणत्या जिल्ह्यात आढळते?', '{"A":"कोल्हापूर व रत्नागिरी","B":"नागपूर व भंडारा","C":"चंद्रपूर व यवतमाळ","D":"नाशिक व जळगाव"}'::JSONB, 'A', 'बॉक्साईट हे जांभा खडकाच्या भागात आढळते. कोल्हापूर, रत्नागिरी, सिंधुदुर्ग आणि रायगड जिल्ह्यात बॉक्साईटचे मोठे साठे आहेत.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'Maharashtra', '2016']::TEXT[], 'Easy'),
  (818, 'बँकिंग, वित्त व महागाई', 'Economy', 'SSC CGL & CHSL', 2017, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'SSC', '2017']::TEXT[], 'Medium'),
  (819, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'IBPS / State Cooperative Bank', 2018, 'पेशीचे "ऊर्जा केंद्र" (Powerhouse of the Cell) कोणाला म्हणतात?', '{"A":"तंतुकणिका (Mitochondria)","B":"रायबोझोम","C":"लायसोझोम","D":"हरितलवके"}'::JSONB, 'A', 'तंतुकणिकेत (Mitochondria) पेशीय श्वसनातून ATP (Adenosine Triphosphate) च्या स्वरूपात ऊर्जा तयार होते, म्हणून त्यास पेशीचे ऊर्जा केंद्र म्हणतात.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'IBPS', '2018']::TEXT[], 'Hard'),
  (820, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'MPSC Combined Group B & C', 2019, 'मराठी वर्णमालेत एकूण किती मूळ स्वर मानले जातात?', '{"A":"12 स्वर (+ 2 इंग्रजी स्वर = 14)","B":"10 स्वर","C":"16 स्वर","D":"8 स्वर"}'::JSONB, 'A', 'पारंपरिक वर्णमालेत 12 स्वर होते. महाराष्ट्र शासनाच्या 2009 च्या जीआरनुसार ॲ आणि ऑ मिळून एकूण 14 स्वर आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'MPSC', '2019']::TEXT[], 'Easy'),
  (821, 'English Grammar & Vocabulary', 'English', 'MPSC State Services (Rajyaseva)', 2020, 'Choose the correct synonym for "TENACIOUS":', '{"A":"Persistent / Determined","B":"Timid","C":"Weak","D":"Cautious"}'::JSONB, 'A', '"Tenacious" means holding fast, persistent, stubborn or resolute.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'MPSC', '2020']::TEXT[], 'Medium'),
  (822, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Police Constable Bharti', 2021, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2021']::TEXT[], 'Hard'),
  (823, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2022, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2022']::TEXT[], 'Easy'),
  (824, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'Maharashtra Vanrakshak (Forest) Bharti', 2023, 'भारताचे राष्ट्रपती होण्यासाठी किमान वय किती वर्षे पूर्ण असावे लागते?', '{"A":"35 वर्षे","B":"30 वर्षे","C":"25 वर्षे","D":"21 वर्षे"}'::JSONB, 'A', 'राष्ट्रपती व राज्यपालांसाठी किमान वय 35 वर्षे, राज्यसभेसाठी 30 वर्षे, लोकसभेसाठी 25 वर्षे आणि ग्रामपंचायतीसाठी 21 वर्षे आवश्यक आहे.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'Maharashtra', '2023']::TEXT[], 'Medium'),
  (825, 'महाराष्ट्रातील समाजसुधारक', 'History', 'SSC CGL & CHSL', 2024, 'शारदा सदन (1889) आणि मुक्ती मिशन (1898) ची स्थापना कोणी केली?', '{"A":"पंडिता रमाबाई","B":"रमाबाई रानडे","C":"आनंदीबाई जोशी","D":"ताराबाई शिंदे"}'::JSONB, 'A', 'पंडिता रमाबाई यांनी निराधार विधवा व स्त्रियांसाठी 1889 मध्ये मुंबईत शारदा सदन व केडगाव येथे मुक्ती सदन स्थापन केले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'SSC', '2024']::TEXT[], 'Hard'),
  (826, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'IBPS / State Cooperative Bank', 2014, 'महाराष्ट्रात सर्वाधिक पर्जन्य पडणारे ठिकाण "आंबोली" कोणत्या जिल्ह्यात आहे?', '{"A":"सिंधुदुर्ग","B":"रत्नागिरी","C":"सातारा","D":"कोल्हापूर"}'::JSONB, 'A', 'सिंधुदुर्ग जिल्ह्यातील सावंतवाडी तालुक्यातील आंबोली येथे महाराष्ट्रात सर्वाधिक (सुमारे 750 सेमी) पाऊस पडतो, म्हणून त्यास "महाराष्ट्राचे चेरापुंजी" म्हणतात.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'IBPS', '2014']::TEXT[], 'Easy'),
  (827, 'बँकिंग, वित्त व महागाई', 'Economy', 'MPSC Combined Group B & C', 2015, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'MPSC', '2015']::TEXT[], 'Medium'),
  (828, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'MPSC State Services (Rajyaseva)', 2016, 'शुद्ध पाण्याचे pH मूल्य किती असते?', '{"A":"7 (उदासीन)","B":"0","C":"14","D":"4"}'::JSONB, 'A', 'pH स्केलवर 7 म्हणजे उदासीन (उदा. शुद्ध पाणी). 7 पेक्षा कमी म्हणजे आम्लधर्मी (Acidic) आणि 7 पेक्षा जास्त म्हणजे आम्लारीधर्मी (Basic).', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'MPSC', '2016']::TEXT[], 'Hard'),
  (829, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'Maharashtra Police Constable Bharti', 2017, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'Maharashtra', '2017']::TEXT[], 'Easy'),
  (830, 'English Grammar & Vocabulary', 'English', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2018, 'Identify the meaning of idiom: "A blessing in disguise"', '{"A":"Something good that isn''t recognized at first","B":"A holy prayer","C":"A fake curse","D":"A sudden disaster"}'::JSONB, 'A', '"A blessing in disguise" means an apparent misfortune that eventually results in something unexpectedly good.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2018']::TEXT[], 'Medium'),
  (831, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Vanrakshak (Forest) Bharti', 2019, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2019']::TEXT[], 'Hard'),
  (832, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'SSC CGL & CHSL', 2020, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'SSC', '2020']::TEXT[], 'Easy'),
  (833, 'मूलभूत हक्क (Fundamental Rights)', 'Polity', 'IBPS / State Cooperative Bank', 2021, 'कायद्यासमोर समानता (Equality before Law) कोणत्या कलमामध्ये दिली आहे?', '{"A":"कलम 14","B":"कलम 15","C":"कलम 16","D":"कलम 17"}'::JSONB, 'A', 'कलम 14 नुसार भारतातील कोणत्याही व्यक्तीस कायद्यापुढे समानता अथवा कायद्याचे समान संरक्षण नाकारले जाणार नाही.', ARRAY['मूलभूत हक्क', 'कलम १४', 'कलम १९', 'कलम २१', 'कलम ३२', 'IBPS', '2021']::TEXT[], 'Medium'),
  (834, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'MPSC Combined Group B & C', 2022, 'लोकमान्य बाळ गंगाधर टिळकांनी 1916 मध्ये बेळगाव येथे कोणती चळवळ सुरू केली?', '{"A":"होमरूल लीग चळवळ (Home Rule League)","B":"असहकार आंदोलन","C":"भारत छोडो","D":"सविनय कायदेभंग"}'::JSONB, 'A', 'एप्रिल 1916 मध्ये बेळगाव येथे टिळकांनी होमरूल लीगची स्थापना केली आणि "स्वराज्य हा माझा जन्मसिद्ध हक्क आहे आणि तो मी मिळवणारच" ही सिंहगर्जना केली.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'MPSC', '2022']::TEXT[], 'Hard'),
  (835, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'MPSC State Services (Rajyaseva)', 2023, 'अ‍ॅल्युमिनियम बनवण्यासाठी वापरले जाणारे "बॉक्साईट" हे खनिज महाराष्ट्रात प्रामुख्याने कोणत्या जिल्ह्यात आढळते?', '{"A":"कोल्हापूर व रत्नागिरी","B":"नागपूर व भंडारा","C":"चंद्रपूर व यवतमाळ","D":"नाशिक व जळगाव"}'::JSONB, 'A', 'बॉक्साईट हे जांभा खडकाच्या भागात आढळते. कोल्हापूर, रत्नागिरी, सिंधुदुर्ग आणि रायगड जिल्ह्यात बॉक्साईटचे मोठे साठे आहेत.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'MPSC', '2023']::TEXT[], 'Easy'),
  (836, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Police Constable Bharti', 2024, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2024']::TEXT[], 'Medium'),
  (837, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2014, 'पेशीचे "ऊर्जा केंद्र" (Powerhouse of the Cell) कोणाला म्हणतात?', '{"A":"तंतुकणिका (Mitochondria)","B":"रायबोझोम","C":"लायसोझोम","D":"हरितलवके"}'::JSONB, 'A', 'तंतुकणिकेत (Mitochondria) पेशीय श्वसनातून ATP (Adenosine Triphosphate) च्या स्वरूपात ऊर्जा तयार होते, म्हणून त्यास पेशीचे ऊर्जा केंद्र म्हणतात.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'Maharashtra', '2014']::TEXT[], 'Hard'),
  (838, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'Maharashtra Vanrakshak (Forest) Bharti', 2015, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'Maharashtra', '2015']::TEXT[], 'Easy'),
  (839, 'English Grammar & Vocabulary', 'English', 'SSC CGL & CHSL', 2016, 'Choose the correct synonym for "TENACIOUS":', '{"A":"Persistent / Determined","B":"Timid","C":"Weak","D":"Cautious"}'::JSONB, 'A', '"Tenacious" means holding fast, persistent, stubborn or resolute.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'SSC', '2016']::TEXT[], 'Medium'),
  (840, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'IBPS / State Cooperative Bank', 2017, 'जर 5 माणसे एक काम 10 दिवसांत करतात, तर 2 माणसे तेच काम किती दिवसांत करतील?', '{"A":"25 दिवस","B":"20 दिवस","C":"15 दिवस","D":"30 दिवस"}'::JSONB, 'A', 'माणसे x दिवस = स्थिरांक. 5 x 10 = 50 मॅन-डेज. 50 / 2 = 25 दिवस.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'IBPS', '2017']::TEXT[], 'Hard'),
  (841, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC Combined Group B & C', 2018, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2018']::TEXT[], 'Easy'),
  (842, 'राज्यघटना निर्मिती व सरनामा', 'Polity', 'MPSC State Services (Rajyaseva)', 2019, 'संविधानाच्या सरनाम्यात बंधुता, स्वातंत्र्य आणि समता ही मूल्ये कोणत्या क्रांतीकडून घेण्यात आली?', '{"A":"फ्रेंच राज्यक्रांती (1789)","B":"रशियन क्रांती (1917)","C":"अमेरिकन स्वातंत्र्ययुद्ध","D":"औद्योगिक क्रांती"}'::JSONB, 'A', 'स्वातंत्र्य, समता आणि बंधुता ही मूल्ये 1789 च्या फ्रेंच राज्यक्रांतीतून घेण्यात आली आहेत. तर सामाजिक, आर्थिक व राजकीय न्याय हे रशियन क्रांतीतून घेतले आहेत.', ARRAY['संविधान', 'सरनामा', 'Preamble', 'संविधान सभा', 'MPSC', '2019']::TEXT[], 'Medium'),
  (843, 'महाराष्ट्रातील समाजसुधारक', 'History', 'Maharashtra Police Constable Bharti', 2020, 'शारदा सदन (1889) आणि मुक्ती मिशन (1898) ची स्थापना कोणी केली?', '{"A":"पंडिता रमाबाई","B":"रमाबाई रानडे","C":"आनंदीबाई जोशी","D":"ताराबाई शिंदे"}'::JSONB, 'A', 'पंडिता रमाबाई यांनी निराधार विधवा व स्त्रियांसाठी 1889 मध्ये मुंबईत शारदा सदन व केडगाव येथे मुक्ती सदन स्थापन केले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'Maharashtra', '2020']::TEXT[], 'Hard'),
  (844, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2021, 'महाराष्ट्रातील दगडी कोळशाचे सर्वात प्रसिद्ध क्षेत्र "बल्लारपूर" कोणत्या जिल्ह्यात आहे?', '{"A":"चंद्रपूर","B":"नागपूर","C":"यवतमाळ","D":"भंडारा"}'::JSONB, 'A', 'चंद्रपूर आणि नागपूर जिल्ह्यात विदर्भामध्ये दगडी कोळशाच्या खाणी आहेत. वर्धा-वैणगंगा खोऱ्यात बल्लारपूर हे कोळशाचे मोठे केंद्र आहे.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'Maharashtra', '2021']::TEXT[], 'Easy'),
  (845, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Vanrakshak (Forest) Bharti', 2022, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2022']::TEXT[], 'Medium'),
  (846, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'SSC CGL & CHSL', 2023, 'मानवी शरीरातील सर्वात मोठी ग्रंथी (Largest Gland) कोणती?', '{"A":"यकृत (Liver)","B":"स्वादुपिंड (Pancreas)","C":"थायरॉईड ग्रंथी","D":"जठर"}'::JSONB, 'A', 'यकृत ही मानवी शरीरातील सर्वात मोठी ग्रंथी (वजन सुमारे 1.5 किलो) असून ती पित्तरस (Bile juice) तयार करते.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'SSC', '2023']::TEXT[], 'Hard'),
  (847, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'IBPS / State Cooperative Bank', 2024, '"सूर्य + उदय = सूर्योदय" हा कोणत्या संधीचा प्रकार आहे?', '{"A":"स्वरसंधी (गुणादेश)","B":"व्यंजनसंधी","C":"विसर्गसंधी","D":"पूर्वरूप संधी"}'::JSONB, 'A', 'अ/आ च्या पुढे उ आल्यास दोघांबद्दल ओ होतो (गुणादेश), ही स्वरसंधीची उदाहरणे आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'IBPS', '2024']::TEXT[], 'Easy'),
  (848, 'English Grammar & Vocabulary', 'English', 'MPSC Combined Group B & C', 2014, 'Identify the meaning of idiom: "A blessing in disguise"', '{"A":"Something good that isn''t recognized at first","B":"A holy prayer","C":"A fake curse","D":"A sudden disaster"}'::JSONB, 'A', '"A blessing in disguise" means an apparent misfortune that eventually results in something unexpectedly good.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'MPSC', '2014']::TEXT[], 'Medium'),
  (849, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'MPSC State Services (Rajyaseva)', 2015, 'जर 5 माणसे एक काम 10 दिवसांत करतात, तर 2 माणसे तेच काम किती दिवसांत करतील?', '{"A":"25 दिवस","B":"20 दिवस","C":"15 दिवस","D":"30 दिवस"}'::JSONB, 'A', 'माणसे x दिवस = स्थिरांक. 5 x 10 = 50 मॅन-डेज. 50 / 2 = 25 दिवस.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'MPSC', '2015']::TEXT[], 'Hard'),
  (850, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Police Constable Bharti', 2016, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2016']::TEXT[], 'Easy')
