  (892, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'Maharashtra Police Constable Bharti', 2014, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'Maharashtra', '2014']::TEXT[], 'Easy'),
  (893, 'English Grammar & Vocabulary', 'English', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2015, 'Identify the meaning of idiom: "A blessing in disguise"', '{"A":"Something good that isn''t recognized at first","B":"A holy prayer","C":"A fake curse","D":"A sudden disaster"}'::JSONB, 'A', '"A blessing in disguise" means an apparent misfortune that eventually results in something unexpectedly good.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2015']::TEXT[], 'Medium'),
  (894, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Vanrakshak (Forest) Bharti', 2016, 'पुढील संख्यामालिकेतील प्रश्नचिन्हाच्या जागी काय येईल: 2, 6, 12, 20, 30, ?', '{"A":"42","B":"40","C":"44","D":"36"}'::JSONB, 'A', 'फरक: +4, +6, +8, +10, +12. म्हणून 30 + 12 = 42. (किंवा n^2 + n: 1^2+1=2, 2^2+2=6, 3^2+3=12, 4^2+4=20, 5^2+5=30, 6^2+6=42).', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2016']::TEXT[], 'Hard'),
  (895, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'SSC CGL & CHSL', 2017, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'SSC', '2017']::TEXT[], 'Easy'),
  (896, 'राज्यघटना निर्मिती व सरनामा', 'Polity', 'IBPS / State Cooperative Bank', 2018, 'भारतीय संविधानात "मार्गदर्शक तत्वे" (DPSP) कोणत्या देशाच्या घटनेवरून घेण्यात आली आहेत?', '{"A":"आयर्लंड (Ireland)","B":"अमेरिका","C":"ब्रिटन","D":"कॅनडा"}'::JSONB, 'A', 'मार्गदर्शक तत्वे (भाग IV) आयर्लंडच्या संविधानाकडून प्रेरित आहेत. मूलभूत हक्क अमेरिकेकडून, तर संसदीय शासनप्रणाली ब्रिटनकडून घेतली आहे.', ARRAY['संविधान', 'सरनामा', 'Preamble', 'संविधान सभा', 'IBPS', '2018']::TEXT[], 'Medium'),
  (897, 'महाराष्ट्रातील समाजसुधारक', 'History', 'MPSC Combined Group B & C', 2019, 'शारदा सदन (1889) आणि मुक्ती मिशन (1898) ची स्थापना कोणी केली?', '{"A":"पंडिता रमाबाई","B":"रमाबाई रानडे","C":"आनंदीबाई जोशी","D":"ताराबाई शिंदे"}'::JSONB, 'A', 'पंडिता रमाबाई यांनी निराधार विधवा व स्त्रियांसाठी 1889 मध्ये मुंबईत शारदा सदन व केडगाव येथे मुक्ती सदन स्थापन केले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'MPSC', '2019']::TEXT[], 'Hard'),
  (898, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'MPSC State Services (Rajyaseva)', 2020, 'महाराष्ट्रातील दगडी कोळशाचे सर्वात प्रसिद्ध क्षेत्र "बल्लारपूर" कोणत्या जिल्ह्यात आहे?', '{"A":"चंद्रपूर","B":"नागपूर","C":"यवतमाळ","D":"भंडारा"}'::JSONB, 'A', 'चंद्रपूर आणि नागपूर जिल्ह्यात विदर्भामध्ये दगडी कोळशाच्या खाणी आहेत. वर्धा-वैणगंगा खोऱ्यात बल्लारपूर हे कोळशाचे मोठे केंद्र आहे.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'MPSC', '2020']::TEXT[], 'Easy'),
  (899, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Police Constable Bharti', 2021, 'भारतात कृषी आणि ग्रामीण विकासासाठी पतपुरवठा करणारी शिखर संस्था कोणती?', '{"A":"नाबार्ड (NABARD)","B":"सिडबी (SIDBI)","C":"आयडीबीआय (IDBI)","D":"सेबी (SEBI)"}'::JSONB, 'A', 'शिवरामन समितीच्या शिफारशीवरून 12 जुलै 1982 रोजी NABARD (National Bank for Agriculture and Rural Development) ची स्थापना झाली.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2021']::TEXT[], 'Medium'),
  (900, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2022, 'मानवी शरीरातील सर्वात मोठी ग्रंथी (Largest Gland) कोणती?', '{"A":"यकृत (Liver)","B":"स्वादुपिंड (Pancreas)","C":"थायरॉईड ग्रंथी","D":"जठर"}'::JSONB, 'A', 'यकृत ही मानवी शरीरातील सर्वात मोठी ग्रंथी (वजन सुमारे 1.5 किलो) असून ती पित्तरस (Bile juice) तयार करते.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'Maharashtra', '2022']::TEXT[], 'Hard')
