  (932, 'मूलभूत हक्क (Fundamental Rights)', 'Polity', 'MPSC Combined Group B & C', 2021, 'कोणत्या कलमाद्वारे बालमजुरीवर (14 वर्षांखालील बालकांना कारखान्यात कामावर ठेवण्यास) बंदी घालण्यात आली आहे?', '{"A":"कलम 24","B":"कलम 23","C":"कलम 21A","D":"कलम 25"}'::JSONB, 'A', 'कलम 24 नुसार धोकादायक ठिकाणी 14 वर्षांखालील बालकांना कामावर ठेवण्यास सक्त मनाई आहे. कलम 23 मानवी व्यापार व वेठबिगारीस प्रतिबंध करते.', ARRAY['मूलभूत हक्क', 'कलम १४', 'कलम १९', 'कलम २१', 'कलम ३२', 'MPSC', '2021']::TEXT[], 'Medium'),
  (933, 'महाराष्ट्रातील समाजसुधारक', 'History', 'MPSC State Services (Rajyaseva)', 2022, 'डिप्रेस्ड क्लासेस मिशन (Depressed Classes Mission) ची स्थापना 1906 मध्ये कोणी केली?', '{"A":"महर्षी विठ्ठल रामजी शिंदे","B":"डॉ. बाबासाहेब आंबेडकर","C":"छत्रपती शाहू महाराज","D":"महात्मा फुले"}'::JSONB, 'A', '18 ऑक्टोबर 1906 रोजी मुंबईत महर्षी विठ्ठल रामजी शिंदे यांनी अस्पृश्यांच्या उद्धारासाठी डिप्रेस्ड क्लासेस मिशनची स्थापना केली.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'MPSC', '2022']::TEXT[], 'Hard'),
  (934, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'Maharashtra Police Constable Bharti', 2023, 'अ‍ॅल्युमिनियम बनवण्यासाठी वापरले जाणारे "बॉक्साईट" हे खनिज महाराष्ट्रात प्रामुख्याने कोणत्या जिल्ह्यात आढळते?', '{"A":"कोल्हापूर व रत्नागिरी","B":"नागपूर व भंडारा","C":"चंद्रपूर व यवतमाळ","D":"नाशिक व जळगाव"}'::JSONB, 'A', 'बॉक्साईट हे जांभा खडकाच्या भागात आढळते. कोल्हापूर, रत्नागिरी, सिंधुदुर्ग आणि रायगड जिल्ह्यात बॉक्साईटचे मोठे साठे आहेत.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'Maharashtra', '2023']::TEXT[], 'Easy'),
  (935, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2024, 'भारतात कृषी आणि ग्रामीण विकासासाठी पतपुरवठा करणारी शिखर संस्था कोणती?', '{"A":"नाबार्ड (NABARD)","B":"सिडबी (SIDBI)","C":"आयडीबीआय (IDBI)","D":"सेबी (SEBI)"}'::JSONB, 'A', 'शिवरामन समितीच्या शिफारशीवरून 12 जुलै 1982 रोजी NABARD (National Bank for Agriculture and Rural Development) ची स्थापना झाली.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2024']::TEXT[], 'Medium'),
  (936, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'Maharashtra Vanrakshak (Forest) Bharti', 2014, 'पेनिसिलिन या पहिल्या प्रतिजैविकाचा (Antibiotic) शोध कोणी लावला?', '{"A":"अलेक्झांडर फ्लेमिंग","B":"एडवर्ड जेनर","C":"लुई पाश्चर","D":"रॉबर्ट कॉक"}'::JSONB, 'A', '1928 मध्ये अलेक्झांडर फ्लेमिंग यांनी पेनिसिलियम नोटॅटम या बुरशीपासून जगातील पहिले अँटिबायोटिक पेनिसिलिन शोधले.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'Maharashtra', '2014']::TEXT[], 'Hard'),
  (937, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'SSC CGL & CHSL', 2015, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'SSC', '2015']::TEXT[], 'Easy'),
  (938, 'English Grammar & Vocabulary', 'English', 'IBPS / State Cooperative Bank', 2016, 'Choose the correct synonym for "TENACIOUS":', '{"A":"Persistent / Determined","B":"Timid","C":"Weak","D":"Cautious"}'::JSONB, 'A', '"Tenacious" means holding fast, persistent, stubborn or resolute.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'IBPS', '2016']::TEXT[], 'Medium'),
  (939, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'MPSC Combined Group B & C', 2017, 'पुढील संख्यामालिकेतील प्रश्नचिन्हाच्या जागी काय येईल: 2, 6, 12, 20, 30, ?', '{"A":"42","B":"40","C":"44","D":"36"}'::JSONB, 'A', 'फरक: +4, +6, +8, +10, +12. म्हणून 30 + 12 = 42. (किंवा n^2 + n: 1^2+1=2, 2^2+2=6, 3^2+3=12, 4^2+4=20, 5^2+5=30, 6^2+6=42).', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'MPSC', '2017']::TEXT[], 'Hard'),
  (940, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC State Services (Rajyaseva)', 2018, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2018']::TEXT[], 'Easy'),
  (941, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'Maharashtra Police Constable Bharti', 2019, 'संसदेच्या दोन्ही सभागृहांचे संयुक्त अधिवेशन (Joint Sitting) कोण बोलावतात?', '{"A":"भारताचे राष्ट्रपती","B":"लोकसभा अध्यक्ष","C":"उपराष्ट्रपती","D":"पंतप्रधान"}'::JSONB, 'A', 'कलम 108 नुसार राष्ट्रपती संयुक्त अधिवेशन बोलावतात; परंतु त्याचे अध्यक्षस्थान नेहमी लोकसभेचे अध्यक्ष (Speaker) भूषवितात.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'Maharashtra', '2019']::TEXT[], 'Medium'),
  (942, 'महाराष्ट्रातील समाजसुधारक', 'History', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2020, 'गोपाळ गणेश आगरकर यांनी लोकमान्य टिळकांपासून वेगळे झाल्यानंतर कोणते वृत्तपत्र सुरू केले?', '{"A":"सुधारक (1888)","B":"केसरी","C":"मराठा","D":"ज्ञानप्रकाश"}'::JSONB, 'A', 'आगरकरांनी राजकीय सुधारणांपेक्षा सामाजिक सुधारणांना प्राधान्य दिले आणि 1888 मध्ये "सुधारक" हे विचारप्रधान वृत्तपत्र सुरू केले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'Maharashtra', '2020']::TEXT[], 'Hard'),
  (943, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'Maharashtra Vanrakshak (Forest) Bharti', 2021, 'महाराष्ट्रातील दगडी कोळशाचे सर्वात प्रसिद्ध क्षेत्र "बल्लारपूर" कोणत्या जिल्ह्यात आहे?', '{"A":"चंद्रपूर","B":"नागपूर","C":"यवतमाळ","D":"भंडारा"}'::JSONB, 'A', 'चंद्रपूर आणि नागपूर जिल्ह्यात विदर्भामध्ये दगडी कोळशाच्या खाणी आहेत. वर्धा-वैणगंगा खोऱ्यात बल्लारपूर हे कोळशाचे मोठे केंद्र आहे.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'Maharashtra', '2021']::TEXT[], 'Easy'),
  (944, 'बँकिंग, वित्त व महागाई', 'Economy', 'SSC CGL & CHSL', 2022, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'SSC', '2022']::TEXT[], 'Medium'),
  (945, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'IBPS / State Cooperative Bank', 2023, 'सूर्याकडून पृथ्वीकडे येणारी उष्णता कोणत्या पद्धतीने संक्रमित होते?', '{"A":"प्रारण (Radiation)","B":"वहन (Conduction)","C":"अभिसरण (Convection)","D":"बाष्पीभवन"}'::JSONB, 'A', 'प्रारणासाठी (Radiation) कोणत्याही भौतिक माध्यमाची गरज नसते, म्हणून अवकाशातील पोकळीतून सूर्याची ऊर्जा प्रारण पद्धतीने पृथ्वीपर्यंत पोहोचते.', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'IBPS', '2023']::TEXT[], 'Hard'),
  (946, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'MPSC Combined Group B & C', 2024, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'MPSC', '2024']::TEXT[], 'Easy'),
  (947, 'English Grammar & Vocabulary', 'English', 'MPSC State Services (Rajyaseva)', 2014, 'Choose the correct synonym for "TENACIOUS":', '{"A":"Persistent / Determined","B":"Timid","C":"Weak","D":"Cautious"}'::JSONB, 'A', '"Tenacious" means holding fast, persistent, stubborn or resolute.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'MPSC', '2014']::TEXT[], 'Medium'),
  (948, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Police Constable Bharti', 2015, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2015']::TEXT[], 'Hard'),
  (949, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2016, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2016']::TEXT[], 'Easy'),
  (950, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'Maharashtra Vanrakshak (Forest) Bharti', 2017, 'भारताचे राष्ट्रपती होण्यासाठी किमान वय किती वर्षे पूर्ण असावे लागते?', '{"A":"35 वर्षे","B":"30 वर्षे","C":"25 वर्षे","D":"21 वर्षे"}'::JSONB, 'A', 'राष्ट्रपती व राज्यपालांसाठी किमान वय 35 वर्षे, राज्यसभेसाठी 30 वर्षे, लोकसभेसाठी 25 वर्षे आणि ग्रामपंचायतीसाठी 21 वर्षे आवश्यक आहे.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'Maharashtra', '2017']::TEXT[], 'Medium')
