  (968, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'MPSC State Services (Rajyaseva)', 2024, 'भारताचे राष्ट्रपती होण्यासाठी किमान वय किती वर्षे पूर्ण असावे लागते?', '{"A":"35 वर्षे","B":"30 वर्षे","C":"25 वर्षे","D":"21 वर्षे"}'::JSONB, 'A', 'राष्ट्रपती व राज्यपालांसाठी किमान वय 35 वर्षे, राज्यसभेसाठी 30 वर्षे, लोकसभेसाठी 25 वर्षे आणि ग्रामपंचायतीसाठी 21 वर्षे आवश्यक आहे.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'MPSC', '2024']::TEXT[], 'Medium'),
  (969, 'महाराष्ट्रातील समाजसुधारक', 'History', 'Maharashtra Police Constable Bharti', 2014, 'डिप्रेस्ड क्लासेस मिशन (Depressed Classes Mission) ची स्थापना 1906 मध्ये कोणी केली?', '{"A":"महर्षी विठ्ठल रामजी शिंदे","B":"डॉ. बाबासाहेब आंबेडकर","C":"छत्रपती शाहू महाराज","D":"महात्मा फुले"}'::JSONB, 'A', '18 ऑक्टोबर 1906 रोजी मुंबईत महर्षी विठ्ठल रामजी शिंदे यांनी अस्पृश्यांच्या उद्धारासाठी डिप्रेस्ड क्लासेस मिशनची स्थापना केली.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'Maharashtra', '2014']::TEXT[], 'Hard'),
