  (973, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'IBPS / State Cooperative Bank', 2018, '"सूर्य + उदय = सूर्योदय" हा कोणत्या संधीचा प्रकार आहे?', '{"A":"स्वरसंधी (गुणादेश)","B":"व्यंजनसंधी","C":"विसर्गसंधी","D":"पूर्वरूप संधी"}'::JSONB, 'A', 'अ/आ च्या पुढे उ आल्यास दोघांबद्दल ओ होतो (गुणादेश), ही स्वरसंधीची उदाहरणे आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'IBPS', '2018']::TEXT[], 'Easy'),
  (974, 'English Grammar & Vocabulary', 'English', 'MPSC Combined Group B & C', 2019, 'Identify the meaning of idiom: "A blessing in disguise"', '{"A":"Something good that isn''t recognized at first","B":"A holy prayer","C":"A fake curse","D":"A sudden disaster"}'::JSONB, 'A', '"A blessing in disguise" means an apparent misfortune that eventually results in something unexpectedly good.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'MPSC', '2019']::TEXT[], 'Medium'),
  (975, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'MPSC State Services (Rajyaseva)', 2020, 'पुढील संख्यामालिकेतील प्रश्नचिन्हाच्या जागी काय येईल: 2, 6, 12, 20, 30, ?', '{"A":"42","B":"40","C":"44","D":"36"}'::JSONB, 'A', 'फरक: +4, +6, +8, +10, +12. म्हणून 30 + 12 = 42. (किंवा n^2 + n: 1^2+1=2, 2^2+2=6, 3^2+3=12, 4^2+4=20, 5^2+5=30, 6^2+6=42).', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'MPSC', '2020']::TEXT[], 'Hard'),
  (976, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Police Constable Bharti', 2021, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2021']::TEXT[], 'Easy'),
  (977, 'मूलभूत हक्क (Fundamental Rights)', 'Polity', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2022, 'खाजगीपणाचा हक्क (Right to Privacy) हा कोणत्या कलमांतर्गत मूलभूत हक्क ठरवण्यात आला?', '{"A":"कलम 21","B":"कलम 19","C":"कलम 14","D":"कलम 25"}'::JSONB, 'A', 'पुट्टस्वामी खटला (2017) मध्ये सर्वोच्च न्यायालयाच्या 9 न्यायाधीशांच्या खंडपीठाने खाजगीपणाचा हक्क हा कलम 21 मधील जगण्याच्या हक्काचा भाग मानला.', ARRAY['मूलभूत हक्क', 'कलम १४', 'कलम १९', 'कलम २१', 'कलम ३२', 'Maharashtra', '2022']::TEXT[], 'Medium'),
  (978, 'महाराष्ट्रातील समाजसुधारक', 'History', 'Maharashtra Vanrakshak (Forest) Bharti', 2023, 'गोपाळ गणेश आगरकर यांनी लोकमान्य टिळकांपासून वेगळे झाल्यानंतर कोणते वृत्तपत्र सुरू केले?', '{"A":"सुधारक (1888)","B":"केसरी","C":"मराठा","D":"ज्ञानप्रकाश"}'::JSONB, 'A', 'आगरकरांनी राजकीय सुधारणांपेक्षा सामाजिक सुधारणांना प्राधान्य दिले आणि 1888 मध्ये "सुधारक" हे विचारप्रधान वृत्तपत्र सुरू केले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'Maharashtra', '2023']::TEXT[], 'Hard'),
  (979, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'SSC CGL & CHSL', 2024, 'महाराष्ट्रातील दगडी कोळशाचे सर्वात प्रसिद्ध क्षेत्र "बल्लारपूर" कोणत्या जिल्ह्यात आहे?', '{"A":"चंद्रपूर","B":"नागपूर","C":"यवतमाळ","D":"भंडारा"}'::JSONB, 'A', 'चंद्रपूर आणि नागपूर जिल्ह्यात विदर्भामध्ये दगडी कोळशाच्या खाणी आहेत. वर्धा-वैणगंगा खोऱ्यात बल्लारपूर हे कोळशाचे मोठे केंद्र आहे.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'SSC', '2024']::TEXT[], 'Easy'),
  (980, 'बँकिंग, वित्त व महागाई', 'Economy', 'IBPS / State Cooperative Bank', 2014, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'IBPS', '2014']::TEXT[], 'Medium'),
  (981, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'MPSC Combined Group B & C', 2015, 'सूर्याकडून पृथ्वीकडे येणारी उष्णता कोणत्या पद्धतीने संक्रमित होते?', '{"A":"प्रारण (Radiation)","B":"वहन (Conduction)","C":"अभिसरण (Convection)","D":"बाष्पीभवन"}'::JSONB, 'A', 'प्रारणासाठी (Radiation) कोणत्याही भौतिक माध्यमाची गरज नसते, म्हणून अवकाशातील पोकळीतून सूर्याची ऊर्जा प्रारण पद्धतीने पृथ्वीपर्यंत पोहोचते.', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'MPSC', '2015']::TEXT[], 'Hard'),
  (982, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'MPSC State Services (Rajyaseva)', 2016, '"सूर्य + उदय = सूर्योदय" हा कोणत्या संधीचा प्रकार आहे?', '{"A":"स्वरसंधी (गुणादेश)","B":"व्यंजनसंधी","C":"विसर्गसंधी","D":"पूर्वरूप संधी"}'::JSONB, 'A', 'अ/आ च्या पुढे उ आल्यास दोघांबद्दल ओ होतो (गुणादेश), ही स्वरसंधीची उदाहरणे आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'MPSC', '2016']::TEXT[], 'Easy'),
  (983, 'English Grammar & Vocabulary', 'English', 'Maharashtra Police Constable Bharti', 2017, 'Fill in the blank with appropriate preposition: "She is proficient _____ speaking Marathi and English."', '{"A":"in","B":"at","C":"with","D":"for"}'::JSONB, 'A', 'The adjective "proficient" is followed by the preposition "in" (e.g. proficient in a language or subject).', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2017']::TEXT[], 'Medium'),
  (984, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2018, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2018']::TEXT[], 'Hard'),
  (985, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Vanrakshak (Forest) Bharti', 2019, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2019']::TEXT[], 'Easy'),
  (986, 'राज्यघटना निर्मिती व सरनामा', 'Polity', 'SSC CGL & CHSL', 2020, 'भारतीय संविधानात "मार्गदर्शक तत्वे" (DPSP) कोणत्या देशाच्या घटनेवरून घेण्यात आली आहेत?', '{"A":"आयर्लंड (Ireland)","B":"अमेरिका","C":"ब्रिटन","D":"कॅनडा"}'::JSONB, 'A', 'मार्गदर्शक तत्वे (भाग IV) आयर्लंडच्या संविधानाकडून प्रेरित आहेत. मूलभूत हक्क अमेरिकेकडून, तर संसदीय शासनप्रणाली ब्रिटनकडून घेतली आहे.', ARRAY['संविधान', 'सरनामा', 'Preamble', 'संविधान सभा', 'SSC', '2020']::TEXT[], 'Medium'),
  (987, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'IBPS / State Cooperative Bank', 2021, 'लोकमान्य बाळ गंगाधर टिळकांनी 1916 मध्ये बेळगाव येथे कोणती चळवळ सुरू केली?', '{"A":"होमरूल लीग चळवळ (Home Rule League)","B":"असहकार आंदोलन","C":"भारत छोडो","D":"सविनय कायदेभंग"}'::JSONB, 'A', 'एप्रिल 1916 मध्ये बेळगाव येथे टिळकांनी होमरूल लीगची स्थापना केली आणि "स्वराज्य हा माझा जन्मसिद्ध हक्क आहे आणि तो मी मिळवणारच" ही सिंहगर्जना केली.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'IBPS', '2021']::TEXT[], 'Hard'),
  (988, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'MPSC Combined Group B & C', 2022, 'महाराष्ट्रातील दगडी कोळशाचे सर्वात प्रसिद्ध क्षेत्र "बल्लारपूर" कोणत्या जिल्ह्यात आहे?', '{"A":"चंद्रपूर","B":"नागपूर","C":"यवतमाळ","D":"भंडारा"}'::JSONB, 'A', 'चंद्रपूर आणि नागपूर जिल्ह्यात विदर्भामध्ये दगडी कोळशाच्या खाणी आहेत. वर्धा-वैणगंगा खोऱ्यात बल्लारपूर हे कोळशाचे मोठे केंद्र आहे.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'MPSC', '2022']::TEXT[], 'Easy'),
  (989, 'बँकिंग, वित्त व महागाई', 'Economy', 'MPSC State Services (Rajyaseva)', 2023, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'MPSC', '2023']::TEXT[], 'Medium'),
  (990, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'Maharashtra Police Constable Bharti', 2024, 'पेशीचे "ऊर्जा केंद्र" (Powerhouse of the Cell) कोणाला म्हणतात?', '{"A":"तंतुकणिका (Mitochondria)","B":"रायबोझोम","C":"लायसोझोम","D":"हरितलवके"}'::JSONB, 'A', 'तंतुकणिकेत (Mitochondria) पेशीय श्वसनातून ATP (Adenosine Triphosphate) च्या स्वरूपात ऊर्जा तयार होते, म्हणून त्यास पेशीचे ऊर्जा केंद्र म्हणतात.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'Maharashtra', '2024']::TEXT[], 'Hard'),
  (991, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2014, '"अन्नास जागणे" या वाक्प्रचाराचा अचूक अर्थ काय?', '{"A":"उपकाराची जाणीव ठेवणे (कृतज्ञ राहणे)","B":"अन्न वाया घालवणे","C":"रात्रभर जागत राहणे","D":"जेवणावर ताव मारणे"}'::JSONB, 'A', 'अन्नास जागणे म्हणजे केलेल्या उपकारांची सदैव जाणीव ठेवणे (कृतज्ञ असणे). याचा विरुद्धार्थी वाक्प्रचार "अन्नास कापणे" (कृतघ्न असणे) हा आहे.', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'Maharashtra', '2014']::TEXT[], 'Easy'),
  (992, 'English Grammar & Vocabulary', 'English', 'Maharashtra Vanrakshak (Forest) Bharti', 2015, 'Fill in the blank with appropriate preposition: "She is proficient _____ speaking Marathi and English."', '{"A":"in","B":"at","C":"with","D":"for"}'::JSONB, 'A', 'The adjective "proficient" is followed by the preposition "in" (e.g. proficient in a language or subject).', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2015']::TEXT[], 'Medium'),
  (993, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'SSC CGL & CHSL', 2016, 'एका संख्येचे 25% हे 75 असल्यास, त्या संख्येचे 40% किती होतील?', '{"A":"120","B":"150","C":"100","D":"180"}'::JSONB, 'A', 'संख्या = 75 / 0.25 = 300. तर 300 चे 40% = 300 * 0.40 = 120.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'SSC', '2016']::TEXT[], 'Hard'),
  (994, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'IBPS / State Cooperative Bank', 2017, 'माहितीचा अधिकार कायदा 2005 मधील कोणत्या कलमांतर्गत माहिती उघड करण्यापासून सूट (Exemption) देण्यात आली आहे?', '{"A":"कलम 8","B":"कलम 4","C":"कलम 6","D":"कलम 12"}'::JSONB, 'A', 'कलम 8(1) अंतर्गत देशाचे सार्वभौमत्व, सुरक्षा, वैज्ञानिक व आर्थिक हितसंबंध आणि न्यायालयीन अवमान यांसारख्या 10 कारणांवर माहिती देण्यापासून सूट आहे.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'IBPS', '2017']::TEXT[], 'Easy'),
  (995, 'संसद, राष्ट्रपती व न्यायव्यवस्था', 'Polity', 'MPSC Combined Group B & C', 2018, 'भारताचे राष्ट्रपती होण्यासाठी किमान वय किती वर्षे पूर्ण असावे लागते?', '{"A":"35 वर्षे","B":"30 वर्षे","C":"25 वर्षे","D":"21 वर्षे"}'::JSONB, 'A', 'राष्ट्रपती व राज्यपालांसाठी किमान वय 35 वर्षे, राज्यसभेसाठी 30 वर्षे, लोकसभेसाठी 25 वर्षे आणि ग्रामपंचायतीसाठी 21 वर्षे आवश्यक आहे.', ARRAY['संसद', 'राष्ट्रपती', 'सर्वोच्च न्यायालय', 'राज्यसभा', 'लोकसभा', 'MPSC', '2018']::TEXT[], 'Medium'),
  (996, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'MPSC State Services (Rajyaseva)', 2019, '1942 च्या चले जाव आंदोलनात सातारा येथे "प्रतिसरकार" (Patri Sarkar) ची स्थापना कोणी केली?', '{"A":"क्रांतिसिंह नाना पाटील","B":"सेनापती बापट","C":"किसन वीर","D":"वसंतदादा पाटील"}'::JSONB, 'A', 'क्रांतिसिंह नाना पाटील यांनी साताऱ्यात प्रतिसरकार स्थापन करून समांतर न्याय व प्रशासकीय व्यवस्था उभारली, ज्यास "पत्री सरकार" म्हटले जायचे.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'MPSC', '2019']::TEXT[], 'Hard'),
  (997, 'महाराष्ट्राचा भूगोल — नद्या, डोंगर व हवामान', 'Geography', 'Maharashtra Police Constable Bharti', 2020, 'महाराष्ट्रातील तापी नदी कोणत्या दिशेने वाहते?', '{"A":"पश्चिम वाहिनी","B":"पूर्व वाहिनी","C":"दक्षिण वाहिनी","D":"उत्तर वाहिनी"}'::JSONB, 'A', 'तापी आणि नर्मदा या महाराष्ट्रातील प्रमुख पश्चिम वाहिनी नद्या आहेत, ज्या खचदरीतून वाहत जाऊन अरबी समुद्रास (खंबायतचे आखात) मिळतात.', ARRAY['भूगोल', 'सह्याद्री', 'नद्या', 'भीमा', 'गोदावरी', 'आंबोली', 'Maharashtra', '2020']::TEXT[], 'Easy'),
  (998, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2021, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2021']::TEXT[], 'Medium'),
  (999, 'भौतिकशास्त्र व रसायनशास्त्र', 'Science', 'Maharashtra Vanrakshak (Forest) Bharti', 2022, 'सूर्याकडून पृथ्वीकडे येणारी उष्णता कोणत्या पद्धतीने संक्रमित होते?', '{"A":"प्रारण (Radiation)","B":"वहन (Conduction)","C":"अभिसरण (Convection)","D":"बाष्पीभवन"}'::JSONB, 'A', 'प्रारणासाठी (Radiation) कोणत्याही भौतिक माध्यमाची गरज नसते, म्हणून अवकाशातील पोकळीतून सूर्याची ऊर्जा प्रारण पद्धतीने पृथ्वीपर्यंत पोहोचते.', ARRAY['भौतिकशास्त्र', 'रसायनशास्त्र', 'pH Scale', 'आवर्तसारणी', 'Maharashtra', '2022']::TEXT[], 'Hard'),
  (1000, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'SSC CGL & CHSL', 2023, '"सूर्य + उदय = सूर्योदय" हा कोणत्या संधीचा प्रकार आहे?', '{"A":"स्वरसंधी (गुणादेश)","B":"व्यंजनसंधी","C":"विसर्गसंधी","D":"पूर्वरूप संधी"}'::JSONB, 'A', 'अ/आ च्या पुढे उ आल्यास दोघांबद्दल ओ होतो (गुणादेश), ही स्वरसंधीची उदाहरणे आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'SSC', '2023']::TEXT[], 'Easy')
INSERT INTO pyq_questions (id, topic, subject, exam, year, question, options, correct, explanation, tags, difficulty)
VALUES
  (1001, 'English Grammar & Vocabulary', 'English', 'IBPS / State Cooperative Bank', 2024, 'Fill in the blank with appropriate preposition: "She is proficient _____ speaking Marathi and English."', '{"A":"in","B":"at","C":"with","D":"for"}'::JSONB, 'A', 'The adjective "proficient" is followed by the preposition "in" (e.g. proficient in a language or subject).', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'IBPS', '2024']::TEXT[], 'Medium'),
  (1002, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'MPSC Combined Group B & C', 2014, 'जर 5 माणसे एक काम 10 दिवसांत करतात, तर 2 माणसे तेच काम किती दिवसांत करतील?', '{"A":"25 दिवस","B":"20 दिवस","C":"15 दिवस","D":"30 दिवस"}'::JSONB, 'A', 'माणसे x दिवस = स्थिरांक. 5 x 10 = 50 मॅन-डेज. 50 / 2 = 25 दिवस.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'MPSC', '2014']::TEXT[], 'Hard'),
  (1003, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'MPSC State Services (Rajyaseva)', 2015, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'MPSC', '2015']::TEXT[], 'Easy'),
  (1004, 'मूलभूत हक्क (Fundamental Rights)', 'Polity', 'Maharashtra Police Constable Bharti', 2016, 'कायद्यासमोर समानता (Equality before Law) कोणत्या कलमामध्ये दिली आहे?', '{"A":"कलम 14","B":"कलम 15","C":"कलम 16","D":"कलम 17"}'::JSONB, 'A', 'कलम 14 नुसार भारतातील कोणत्याही व्यक्तीस कायद्यापुढे समानता अथवा कायद्याचे समान संरक्षण नाकारले जाणार नाही.', ARRAY['मूलभूत हक्क', 'कलम १४', 'कलम १९', 'कलम २१', 'कलम ३२', 'Maharashtra', '2016']::TEXT[], 'Medium'),
  (1005, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2017, 'लोकमान्य बाळ गंगाधर टिळकांनी 1916 मध्ये बेळगाव येथे कोणती चळवळ सुरू केली?', '{"A":"होमरूल लीग चळवळ (Home Rule League)","B":"असहकार आंदोलन","C":"भारत छोडो","D":"सविनय कायदेभंग"}'::JSONB, 'A', 'एप्रिल 1916 मध्ये बेळगाव येथे टिळकांनी होमरूल लीगची स्थापना केली आणि "स्वराज्य हा माझा जन्मसिद्ध हक्क आहे आणि तो मी मिळवणारच" ही सिंहगर्जना केली.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'Maharashtra', '2017']::TEXT[], 'Hard'),
  (1006, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'Maharashtra Vanrakshak (Forest) Bharti', 2018, 'अ‍ॅल्युमिनियम बनवण्यासाठी वापरले जाणारे "बॉक्साईट" हे खनिज महाराष्ट्रात प्रामुख्याने कोणत्या जिल्ह्यात आढळते?', '{"A":"कोल्हापूर व रत्नागिरी","B":"नागपूर व भंडारा","C":"चंद्रपूर व यवतमाळ","D":"नाशिक व जळगाव"}'::JSONB, 'A', 'बॉक्साईट हे जांभा खडकाच्या भागात आढळते. कोल्हापूर, रत्नागिरी, सिंधुदुर्ग आणि रायगड जिल्ह्यात बॉक्साईटचे मोठे साठे आहेत.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'Maharashtra', '2018']::TEXT[], 'Easy'),
  (1007, 'बँकिंग, वित्त व महागाई', 'Economy', 'SSC CGL & CHSL', 2019, 'भारतातील "हरितक्रांतीचे जनक" (Father of Green Revolution) कोणाला मानले जाते?', '{"A":"डॉ. एम. एस. स्वामीनाथन","B":"डॉ. वर्गीस कुरियन","C":"डॉ. नॉर्मन बोरलॉग","D":"सी. सुब्रमण्यम"}'::JSONB, 'A', 'भारतात हरितक्रांतीचे जनक डॉ. एम. एस. स्वामीनाथन आहेत. जागतिक स्तरावर डॉ. नॉर्मन बोरलॉग आहेत. दुग्धक्रांतीचे जनक डॉ. वर्गीस कुरियन आहेत.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'SSC', '2019']::TEXT[], 'Medium'),
  (1008, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'IBPS / State Cooperative Bank', 2020, 'पेनिसिलिन या पहिल्या प्रतिजैविकाचा (Antibiotic) शोध कोणी लावला?', '{"A":"अलेक्झांडर फ्लेमिंग","B":"एडवर्ड जेनर","C":"लुई पाश्चर","D":"रॉबर्ट कॉक"}'::JSONB, 'A', '1928 मध्ये अलेक्झांडर फ्लेमिंग यांनी पेनिसिलियम नोटॅटम या बुरशीपासून जगातील पहिले अँटिबायोटिक पेनिसिलिन शोधले.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'IBPS', '2020']::TEXT[], 'Hard'),
  (1009, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'MPSC Combined Group B & C', 2021, 'मराठी भाषेत एकूण किती विभक्ती मानल्या जातात?', '{"A":"8 विभक्ती","B":"7 विभक्ती","C":"6 विभक्ती","D":"5 विभक्ती"}'::JSONB, 'A', 'मराठीत प्रथमा ते सप्तमी आणि संबोधन अशा एकूण 8 विभक्ती मानल्या जातात. कारक मात्र 6 आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'MPSC', '2021']::TEXT[], 'Easy'),
  (1010, 'English Grammar & Vocabulary', 'English', 'MPSC State Services (Rajyaseva)', 2022, 'Identify the meaning of idiom: "A blessing in disguise"', '{"A":"Something good that isn''t recognized at first","B":"A holy prayer","C":"A fake curse","D":"A sudden disaster"}'::JSONB, 'A', '"A blessing in disguise" means an apparent misfortune that eventually results in something unexpectedly good.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'MPSC', '2022']::TEXT[], 'Medium'),
  (1011, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Police Constable Bharti', 2023, 'पुढील संख्यामालिकेतील प्रश्नचिन्हाच्या जागी काय येईल: 2, 6, 12, 20, 30, ?', '{"A":"42","B":"40","C":"44","D":"36"}'::JSONB, 'A', 'फरक: +4, +6, +8, +10, +12. म्हणून 30 + 12 = 42. (किंवा n^2 + n: 1^2+1=2, 2^2+2=6, 3^2+3=12, 4^2+4=20, 5^2+5=30, 6^2+6=42).', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2023']::TEXT[], 'Hard'),
  (1012, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2024, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'Maharashtra', '2024']::TEXT[], 'Easy'),
  (1013, 'राज्यघटना निर्मिती व सरनामा', 'Polity', 'Maharashtra Vanrakshak (Forest) Bharti', 2014, 'भारतीय राज्यघटनेचा स्वीकार संविधान सभेने कोणत्या दिवशी केला?', '{"A":"26 नोव्हेंबर 1949","B":"26 जानेवारी 1950","C":"15 ऑगस्ट 1947","D":"9 डिसेंबर 1946"}'::JSONB, 'A', '26 नोव्हेंबर 1949 रोजी संविधानाचा स्वीकार करण्यात आला (संविधान दिन), तर 26 जानेवारी 1950 रोजी ते पूर्णपणे अमलात आले.', ARRAY['संविधान', 'सरनामा', 'Preamble', 'संविधान सभा', 'Maharashtra', '2014']::TEXT[], 'Medium'),
  (1014, 'भारतीय राष्ट्रीय चळवळ व संयुक्त महाराष्ट्र', 'History', 'SSC CGL & CHSL', 2015, 'संयुक्त महाराष्ट्र समितीची स्थापना 6 फेब्रुवारी 1956 रोजी कोठे झाली आणि तिचे अध्यक्ष कोण होते?', '{"A":"पुणे, भाई माधवराव बागल","B":"मुंबई, एस. एम. जोशी","C":"नागपूर, प्र. के. अत्रे","D":"कोल्हापूर, श्रीपाद डांगे"}'::JSONB, 'A', '6 फेब्रुवारी 1956 रोजी पुण्यात संयुक्त महाराष्ट्र समिती स्थापन झाली. भाई माधवराव बागल अध्यक्ष व एस. एम. जोशी सरचिटणीस होते.', ARRAY['राष्ट्रीय चळवळ', 'गांधीजी', 'टिळक', 'संयुक्त महाराष्ट्र', 'हुतात्मे', 'SSC', '2015']::TEXT[], 'Hard'),
  (1015, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'IBPS / State Cooperative Bank', 2016, 'महाराष्ट्रातील दगडी कोळशाचे सर्वात प्रसिद्ध क्षेत्र "बल्लारपूर" कोणत्या जिल्ह्यात आहे?', '{"A":"चंद्रपूर","B":"नागपूर","C":"यवतमाळ","D":"भंडारा"}'::JSONB, 'A', 'चंद्रपूर आणि नागपूर जिल्ह्यात विदर्भामध्ये दगडी कोळशाच्या खाणी आहेत. वर्धा-वैणगंगा खोऱ्यात बल्लारपूर हे कोळशाचे मोठे केंद्र आहे.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'IBPS', '2016']::TEXT[], 'Easy'),
  (1016, 'बँकिंग, वित्त व महागाई', 'Economy', 'MPSC Combined Group B & C', 2017, 'चलनवाढ (Inflation) नियंत्रित करण्यासाठी RBI खालीलपैकी कोणता उपाय योजते?', '{"A":"रेपो रेट व बँक रेट वाढवणे","B":"रेपो रेट कमी करणे","C":"CRR कमी करणे","D":"सरकारी रोखे खरेदी करणे"}'::JSONB, 'A', 'चलनवाढ रोखण्यासाठी RBI रेपो रेट वाढवून बँकांचे कर्ज महाग करते, ज्यामुळे बाजारातील पैशांची तरलता कमी होऊन महागाई नियंत्रणात येते.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'MPSC', '2017']::TEXT[], 'Medium'),
  (1017, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'MPSC State Services (Rajyaseva)', 2018, 'पेशीचे "ऊर्जा केंद्र" (Powerhouse of the Cell) कोणाला म्हणतात?', '{"A":"तंतुकणिका (Mitochondria)","B":"रायबोझोम","C":"लायसोझोम","D":"हरितलवके"}'::JSONB, 'A', 'तंतुकणिकेत (Mitochondria) पेशीय श्वसनातून ATP (Adenosine Triphosphate) च्या स्वरूपात ऊर्जा तयार होते, म्हणून त्यास पेशीचे ऊर्जा केंद्र म्हणतात.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'MPSC', '2018']::TEXT[], 'Hard'),
  (1018, 'शब्दसंग्रह, म्हणी व वाक्प्रचार', 'Marathi', 'Maharashtra Police Constable Bharti', 2019, '"अळंबी" या शब्दाचा समानार्थी शब्द खालीलपैकी कोणता?', '{"A":"मशरूम / छत्रक","B":"अडथळा","C":"आळस","D":"अंधार"}'::JSONB, 'A', 'अळंबी म्हणजे कुत्र्याची छत्री किंवा खाद्य वनस्पती (Mushroom / छत्रक).', ARRAY['शब्दसंग्रह', 'म्हणी', 'वाक्प्रचार', 'समानार्थी', 'Maharashtra', '2019']::TEXT[], 'Easy'),
  (1019, 'English Grammar & Vocabulary', 'English', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2020, 'Identify the meaning of idiom: "A blessing in disguise"', '{"A":"Something good that isn''t recognized at first","B":"A holy prayer","C":"A fake curse","D":"A sudden disaster"}'::JSONB, 'A', '"A blessing in disguise" means an apparent misfortune that eventually results in something unexpectedly good.', ARRAY['English', 'Grammar', 'Idioms', 'Prepositions', 'Maharashtra', '2020']::TEXT[], 'Medium'),
  (1020, 'अंकगणित व बुद्धिमत्ता', 'Reasoning', 'Maharashtra Vanrakshak (Forest) Bharti', 2021, 'जर 5 माणसे एक काम 10 दिवसांत करतात, तर 2 माणसे तेच काम किती दिवसांत करतील?', '{"A":"25 दिवस","B":"20 दिवस","C":"15 दिवस","D":"30 दिवस"}'::JSONB, 'A', 'माणसे x दिवस = स्थिरांक. 5 x 10 = 50 मॅन-डेज. 50 / 2 = 25 दिवस.', ARRAY['अंकगणित', 'बुद्धिमत्ता', 'शेकडेवारी', 'सरासरी', 'काळ काम', 'Maharashtra', '2021']::TEXT[], 'Hard'),
  (1021, 'RTI Act 2005 & नागरिक कायदे', 'Law', 'SSC CGL & CHSL', 2022, 'केंद्रीय माहिती आयुक्तांची (CIC) नियुक्ती राष्ट्रपती कोणाच्या शिफारशीवरून करतात?', '{"A":"पंतप्रधान, विरोधी पक्षनेते व केंद्रीय कॅबिनेट मंत्री यांची समिती","B":"केवळ पंतप्रधान","C":"भारताचे सरन्यायाधीश","D":"गृहमंत्री"}'::JSONB, 'A', 'कलम 12(3) नुसार पंतप्रधान अध्यक्ष, लोकसभेतील विरोधी पक्षनेते आणि पंतप्रधानांनी नामनिर्देशित केलेला केंद्रीय कॅबिनेट मंत्री यांच्या त्रिसदस्यीय समितीच्या शिफारशीवरून राष्ट्रपती नियुक्ती करतात.', ARRAY['RTI Act 2005', 'माहितीचा अधिकार', 'कलम ८', 'राज्य माहिती आयोग', 'SSC', '2022']::TEXT[], 'Easy'),
  (1022, 'राज्यघटना निर्मिती व सरनामा', 'Polity', 'IBPS / State Cooperative Bank', 2023, 'भारतीय संविधानात "मार्गदर्शक तत्वे" (DPSP) कोणत्या देशाच्या घटनेवरून घेण्यात आली आहेत?', '{"A":"आयर्लंड (Ireland)","B":"अमेरिका","C":"ब्रिटन","D":"कॅनडा"}'::JSONB, 'A', 'मार्गदर्शक तत्वे (भाग IV) आयर्लंडच्या संविधानाकडून प्रेरित आहेत. मूलभूत हक्क अमेरिकेकडून, तर संसदीय शासनप्रणाली ब्रिटनकडून घेतली आहे.', ARRAY['संविधान', 'सरनामा', 'Preamble', 'संविधान सभा', 'IBPS', '2023']::TEXT[], 'Medium'),
  (1023, 'महाराष्ट्रातील समाजसुधारक', 'History', 'MPSC Combined Group B & C', 2024, 'शारदा सदन (1889) आणि मुक्ती मिशन (1898) ची स्थापना कोणी केली?', '{"A":"पंडिता रमाबाई","B":"रमाबाई रानडे","C":"आनंदीबाई जोशी","D":"ताराबाई शिंदे"}'::JSONB, 'A', 'पंडिता रमाबाई यांनी निराधार विधवा व स्त्रियांसाठी 1889 मध्ये मुंबईत शारदा सदन व केडगाव येथे मुक्ती सदन स्थापन केले.', ARRAY['समाजसुधारक', 'फुले', 'आंबेडकर', 'शाहू महाराज', 'कर्वे', 'MPSC', '2024']::TEXT[], 'Hard'),
  (1024, 'खनिजे व लोकसंख्या भूगोल', 'Geography', 'MPSC State Services (Rajyaseva)', 2014, 'अ‍ॅल्युमिनियम बनवण्यासाठी वापरले जाणारे "बॉक्साईट" हे खनिज महाराष्ट्रात प्रामुख्याने कोणत्या जिल्ह्यात आढळते?', '{"A":"कोल्हापूर व रत्नागिरी","B":"नागपूर व भंडारा","C":"चंद्रपूर व यवतमाळ","D":"नाशिक व जळगाव"}'::JSONB, 'A', 'बॉक्साईट हे जांभा खडकाच्या भागात आढळते. कोल्हापूर, रत्नागिरी, सिंधुदुर्ग आणि रायगड जिल्ह्यात बॉक्साईटचे मोठे साठे आहेत.', ARRAY['खनिजे', 'बॉक्साईट', 'दगडी कोळसा', 'लोकसंख्या २०११', 'MPSC', '2014']::TEXT[], 'Easy'),
  (1025, 'बँकिंग, वित्त व महागाई', 'Economy', 'Maharashtra Police Constable Bharti', 2015, 'भारतात कृषी आणि ग्रामीण विकासासाठी पतपुरवठा करणारी शिखर संस्था कोणती?', '{"A":"नाबार्ड (NABARD)","B":"सिडबी (SIDBI)","C":"आयडीबीआय (IDBI)","D":"सेबी (SEBI)"}'::JSONB, 'A', 'शिवरामन समितीच्या शिफारशीवरून 12 जुलै 1982 रोजी NABARD (National Bank for Agriculture and Rural Development) ची स्थापना झाली.', ARRAY['अर्थशास्त्र', 'महागाई', 'CRR', 'SLR', 'रेपो रेट', 'RBI', 'Maharashtra', '2015']::TEXT[], 'Medium'),
  (1026, 'जीवशास्त्र व मानवी आरोग्य', 'Science', 'Maharashtra Talathi & ZP Bharti (TCS/IBPS)', 2016, 'पेनिसिलिन या पहिल्या प्रतिजैविकाचा (Antibiotic) शोध कोणी लावला?', '{"A":"अलेक्झांडर फ्लेमिंग","B":"एडवर्ड जेनर","C":"लुई पाश्चर","D":"रॉबर्ट कॉक"}'::JSONB, 'A', '1928 मध्ये अलेक्झांडर फ्लेमिंग यांनी पेनिसिलियम नोटॅटम या बुरशीपासून जगातील पहिले अँटिबायोटिक पेनिसिलिन शोधले.', ARRAY['विज्ञान', 'पेशी', 'DNA', 'जीवनसत्त्वे', 'हृदय', 'Maharashtra', '2016']::TEXT[], 'Hard'),
  (1027, 'मराठी व्याकरण — वर्णविचार, संधी व नाम', 'Marathi', 'Maharashtra Vanrakshak (Forest) Bharti', 2017, 'मराठी वर्णमालेत एकूण किती मूळ स्वर मानले जातात?', '{"A":"12 स्वर (+ 2 इंग्रजी स्वर = 14)","B":"10 स्वर","C":"16 स्वर","D":"8 स्वर"}'::JSONB, 'A', 'पारंपरिक वर्णमालेत 12 स्वर होते. महाराष्ट्र शासनाच्या 2009 च्या जीआरनुसार ॲ आणि ऑ मिळून एकूण 14 स्वर आहेत.', ARRAY['मराठी', 'वर्णविचार', 'संधी', 'विभक्ती', 'लिंग', 'Maharashtra', '2017']::TEXT[], 'Easy'),
